export const FLASH = [{"id":"t:4c","kind":"term","course":"m02","lesson":"marketing-mix","front":"4Cs","back":"Robert Lauterborn’s (1990) buyer’s-side alternative to the 4Ps: consumer wants and needs, cost to satisfy, convenience to buy, and communication.","href":"learn/marketing/m02/marketing-mix/"},{"id":"t:4p","kind":"term","course":"m02","lesson":"marketing-mix","front":"4Ps","back":"Product, price, place and promotion: the four headings E. Jerome McCarthy (1960) used to organise the marketing mix.","href":"learn/marketing/m02/marketing-mix/"},{"id":"t:7p","kind":"term","course":"m02","lesson":"marketing-mix","front":"7Ps","back":"The 4Ps plus people, process and physical evidence, proposed by Booms and Bitner (1981) for marketing services.","href":"learn/marketing/m02/marketing-mix/"},{"id":"t:account","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Account","back":"A record of all the increases and decreases in one item, such as cash or accounts payable, together with its balance.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:account balance","kind":"term","course":"f01","lesson":"debits-and-credits","front":"Account balance","back":"The difference between an account’s total debits and total credits, including any balance brought forward, stated on the side of the larger total.","href":"learn/finance/f01/debits-and-credits/"},{"id":"t:accounting","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Accounting","back":"An information system that identifies the economic events of an organisation, records them in money and communicates the results to the people who make decisions about it.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:accounting cycle","kind":"term","course":"f01","lesson":"accounting-cycle","front":"Accounting cycle","back":"The sequence of steps a business repeats every accounting period, from analysing transactions to preparing a post-closing trial balance.","href":"learn/finance/f01/accounting-cycle/"},{"id":"t:accounting equation","kind":"term","course":"f01","lesson":"accounting-equation","front":"Accounting equation","back":"Assets = liabilities + equity: the business’s resources equal the claims of creditors and owners on them.","href":"learn/finance/f01/accounting-equation/"},{"id":"t:accounting profit","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Accounting profit","back":"Revenue minus expenses as measured under the accounting rules; also called net income.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:accrual","kind":"term","course":"f01","lesson":"accrual-vs-cash","front":"Accrual","back":"A timing difference in which revenue or an expense is recognised before the cash is received or paid. Meanwhile the amount is a receivable or a payable.","href":"learn/finance/f01/accrual-vs-cash/"},{"id":"t:accrual basi","kind":"term","course":"f01","lesson":"accrual-vs-cash","front":"Accrual basis","back":"A way of keeping accounts that records revenue when it is earned and expenses when they are incurred, whenever the cash is received or paid. Financial statements under US GAAP and IFRS use it.","href":"learn/finance/f01/accrual-vs-cash/"},{"id":"t:accrued expense","kind":"term","course":"f01","lesson":"adjusting-entries","front":"Accrued expense","back":"An expense incurred in the period but not yet paid or recorded, such as wages or interest owed. It is recorded with a payable.","href":"learn/finance/f01/adjusting-entries/"},{"id":"t:accrued revenue","kind":"term","course":"f01","lesson":"adjusting-entries","front":"Accrued revenue","back":"Revenue earned in the period but not yet received or recorded, for example work done but not yet invoiced. It is recorded with a receivable.","href":"learn/finance/f01/adjusting-entries/"},{"id":"t:accumulated depreciation","kind":"term","course":"f01","lesson":"adjusting-entries","front":"Accumulated depreciation","back":"All the depreciation recorded on an asset since it was acquired, held in a contra-asset account with a credit balance.","href":"learn/finance/f01/adjusting-entries/"},{"id":"t:accuracy","kind":"term","course":"b02","lesson":"profiling-and-validation","front":"Accuracy","back":"Whether values correctly describe the real-world thing or event they represent.","href":"learn/analytics/b02/profiling-and-validation/"},{"id":"t:actual product","kind":"term","course":"m02","lesson":"product-decisions","front":"Actual product","back":"The features, quality level, design, brand name and packaging that deliver the core benefit.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:adjusted trial balance","kind":"term","course":"f01","lesson":"adjusting-entries","front":"Adjusted trial balance","back":"A list of every account and its balance after the adjusting entries have been posted, used to prepare the financial statements.","href":"learn/finance/f01/adjusting-entries/"},{"id":"t:adjusting entry","kind":"term","course":"f01","lesson":"adjusting-entries","front":"Adjusting entry","back":"A journal entry made at the end of a period to bring an account up to date, so that revenue and expenses are recognised in the right period. It involves at least one income statement account and one balance sheet account, and never Cash.","href":"learn/finance/f01/adjusting-entries/"},{"id":"t:advertising","kind":"term","course":"m02","lesson":"promotion-mix","front":"Advertising","back":"Paid, non-personal communication from an identified sponsor through mass or digital media.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:affordable method","kind":"term","course":"m02","lesson":"promotion-mix","front":"Affordable method","back":"Setting the promotion budget at whatever the business has left after its other costs and profit target.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:agency cost","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Agency costs","back":"The total cost of an agency relationship: monitoring costs paid by principals, bonding costs paid by agents, and the residual loss that remains.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:agency problem","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Agency problem","back":"The conflict that arises when an agent’s interests differ from the principal’s and the principal cannot fully observe or control the agent’s actions.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:agent","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Agent","back":"In an agency relationship, the person who acts and makes decisions on behalf of a principal.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:agent or broker","kind":"term","course":"m02","lesson":"distribution-channels","front":"Agent or broker","back":"An intermediary that arranges sales for a producer in return for a commission or fee without taking ownership of the goods.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:aggregation","kind":"term","course":"b02","lesson":"transforming-data","front":"Aggregation","back":"Collapsing groups of rows into one summary row per group by applying a function such as sum, mean or count. It moves a table to a coarser granularity.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:aida","kind":"term","course":"m02","lesson":"promotion-mix","front":"AIDA","back":"A response-hierarchy model in which a buyer moves through attention, interest, desire and action. Usually credited to E. St. Elmo Lewis around 1898, though the attribution is disputed.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:ambiguous date","kind":"term","course":"b02","lesson":"types-and-formats","front":"Ambiguous date","back":"A date written so that its day and month could be swapped to give a different valid date, such as 04/03/2026 (4 March or 3 April).","href":"learn/analytics/b02/types-and-formats/"},{"id":"t:amortisation","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"Amortisation","back":"The spreading of the cost of an intangible asset, such as purchased software or a customer contract, over the years it is used. The word is also used for the gradual repayment of a loan’s principal.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:annual percentage yield","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Annual percentage yield","back":"The rate US banks disclose on deposit accounts under the Truth in Savings rules, reflecting the total interest paid on the account including compounding. An effective annual rate. Often shortened to APY.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:apr","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"APR","back":"Annual percentage rate. In its simple sense, a periodic rate multiplied by the number of periods in a year, ignoring compounding; a US credit card’s APR is calculated this way. For closed-end US consumer loans, such as mortgages and car loans, the disclosed APR is broader and also reflects certain fees.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:arbitrage","kind":"term","course":"f00","lesson":"decision-principles","front":"Arbitrage","back":"Buying and selling the same, or equivalent, cash flows at the same time for different prices, making a profit with no risk and none of one’s own money.","href":"learn/finance/f00/decision-principles/"},{"id":"t:articulation","kind":"term","course":"f01","lesson":"financial-statements","front":"Articulation","back":"The links between the financial statements: net income flows into equity, ending equity into the balance sheet, and ending cash from the statement of cash flows into the balance sheet.","href":"learn/finance/f01/financial-statements/"},{"id":"t:ask","kind":"term","course":"f00","lesson":"market-participants","front":"Ask","back":"The price at which a dealer will sell a security; also called the offer.","href":"learn/finance/f00/market-participants/"},{"id":"t:asset","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Asset","back":"A resource the business controls as a result of past events and that is expected to bring it economic benefits. The FASB defines it as a present right of an entity to an economic benefit.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:attribution","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Attribution","back":"Rules for dividing credit for a conversion among the marketing touchpoints that preceded it, such as last click, first click, linear or data-driven.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:audit","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Audit","back":"An independent examination of financial statements, after which the auditor gives an opinion on whether they are presented fairly, in all material respects, in accordance with the applicable financial reporting framework.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:augmented product","kind":"term","course":"m02","lesson":"product-decisions","front":"Augmented product","back":"The additional services and benefits offered with the actual product, such as guarantees, installation, support and loyalty schemes.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:balance sheet","kind":"term","course":"f01","lesson":"financial-statements","front":"Balance sheet","back":"The statement of assets, liabilities and equity at a point in time. Called the statement of financial position under IFRS.","href":"learn/finance/f01/financial-statements/"},{"id":"t:balance-column account","kind":"term","course":"f01","lesson":"general-ledger","front":"Balance-column account","back":"A ledger account laid out with date, explanation, reference, debit, credit and balance columns, showing the balance after every posting. Also called a running-balance or three-column account.","href":"learn/finance/f01/general-ledger/"},{"id":"t:bank run","kind":"term","course":"f00","lesson":"market-participants","front":"Bank run","back":"A rush by many depositors to withdraw their money at once, which can bring down even a sound bank because its loans cannot be turned into cash quickly.","href":"learn/finance/f00/market-participants/"},{"id":"t:bid","kind":"term","course":"f00","lesson":"market-participants","front":"Bid","back":"The price at which a dealer will buy a security.","href":"learn/finance/f00/market-participants/"},{"id":"t:bid-ask spread","kind":"term","course":"f00","lesson":"market-participants","front":"Bid-ask spread","back":"The ask minus the bid: the cost of buying and immediately selling, and the dealer’s gross reward for providing liquidity.","href":"learn/finance/f00/market-participants/"},{"id":"t:binning","kind":"term","course":"b02","lesson":"transforming-data","front":"Binning","back":"Replacing a numeric value with the interval (bin) it falls in. Bin edges can be equal-width, equal-frequency (quantiles) or set by a business rule.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:board of director","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Board of directors","back":"The group elected by a corporation’s shareholders to oversee management: hiring and paying the chief executive, approving strategy and dividends, and overseeing financial reporting.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:bond","kind":"term","course":"f00","lesson":"financial-markets","front":"Bond","back":"A debt security that promises interest and repayment of the amount borrowed on stated dates; its holder is a lender to the issuer.","href":"learn/finance/f00/financial-markets/"},{"id":"t:bond market","kind":"term","course":"f00","lesson":"financial-markets","front":"Bond market","back":"The market for debt securities issued by governments, companies and other bodies.","href":"learn/finance/f00/financial-markets/"},{"id":"t:book value","kind":"term","course":"f01","lesson":"adjusting-entries","front":"Book value","back":"An asset’s cost minus its accumulated depreciation; called the carrying amount under IFRS.","href":"learn/finance/f01/adjusting-entries/"},{"id":"t:book value of equity","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"Book value of equity","back":"Shareholders’ equity as recorded in the balance sheet: total assets minus total liabilities, measured by the accounting rules.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:box–cox transformation","kind":"term","course":"b02","lesson":"skewed-data","front":"Box–Cox transformation","back":"The power transformation (x^λ − 1) ÷ λ, or ln x when λ = 0, with λ estimated from strictly positive data to make them as close to normal as possible.","href":"learn/analytics/b02/skewed-data/"},{"id":"t:brand","kind":"term","course":"m02","lesson":"product-decisions","front":"Brand","back":"A name, term, sign, symbol or design, or a combination of them, that identifies a seller’s product and distinguishes it from competitors’.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:break-even point","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Break-even point","back":"The volume (or revenue) at which total contribution equals fixed costs, so profit is zero: fixed costs ÷ contribution margin per unit.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:break-even roa","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Break-even ROAS","back":"The ROAS at which a campaign’s contribution just covers its cost: 1 ÷ the contribution margin ratio.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:broker","kind":"term","course":"f00","lesson":"market-participants","front":"Broker","back":"A firm that arranges trades for clients as their agent, without owning the securities, and is paid a commission or fee.","href":"learn/finance/f00/market-participants/"},{"id":"t:bundling","kind":"term","course":"m02","lesson":"price-response","front":"Bundling","back":"Selling two or more products together for one price, usually less than the sum of their separate prices. Pure bundling sells only the bundle; mixed bundling also sells the items separately.","href":"learn/marketing/m02/price-response/"},{"id":"t:business key","kind":"term","course":"b02","lesson":"duplicates","front":"Business key","back":"The column or columns that identify one real-world thing in the business’s own terms, such as an order number or booking reference.","href":"learn/analytics/b02/duplicates/"},{"id":"t:capital","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Capital","back":"In finance, the money supplied to a business by investors, as debt or equity, to buy the assets it needs. The assets themselves (machines, buildings) are sometimes called physical capital.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:capital budgeting","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Capital budgeting","back":"The process a firm uses to decide which long-term investments are worth making, by comparing what they cost with the value of what they are expected to return.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:capital market","kind":"term","course":"f00","lesson":"financial-markets","front":"Capital market","back":"The market for long-term finance: debt maturing in more than a year, and shares.","href":"learn/finance/f00/financial-markets/"},{"id":"t:capital structure","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Capital structure","back":"The mix of debt and equity a business uses to finance its assets.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:case normalisation","kind":"term","course":"b02","lesson":"text-and-categories","front":"Case normalisation","back":"Converting text to a single case, usually lower case, so that values differing only in capitals compare as equal.","href":"learn/analytics/b02/text-and-categories/"},{"id":"t:cash basi","kind":"term","course":"f01","lesson":"accrual-vs-cash","front":"Cash basis","back":"A way of keeping accounts that records revenue when cash is received and expenses when cash is paid.","href":"learn/finance/f01/accrual-vs-cash/"},{"id":"t:cash flow","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Cash flow","back":"Cash received or paid out by a person or business over a period, or expected to be received or paid as a result of a decision.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:categorical encoding","kind":"term","course":"b02","lesson":"encoding-categories","front":"Categorical encoding","back":"Converting the labels of a categorical variable into numbers that a model can use.","href":"learn/analytics/b02/encoding-categories/"},{"id":"t:category consolidation","kind":"term","course":"b02","lesson":"text-and-categories","front":"Category consolidation","back":"Merging the variants of a categorical value into the values of a controlled vocabulary, which changes the counts and statistics of each category.","href":"learn/analytics/b02/text-and-categories/"},{"id":"t:cfo","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"CFO","back":"Chief financial officer: the senior executive responsible for a company’s financial decisions, including investment, financing and working capital, and for its financial reporting.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:channel conflict","kind":"term","course":"m02","lesson":"distribution-channels","front":"Channel conflict","back":"Disagreement between members of a marketing channel that gets in the way of the channel working. Vertical conflict is between levels; horizontal conflict is between members at the same level.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:channel level","kind":"term","course":"m02","lesson":"distribution-channels","front":"Channel level","back":"One layer of intermediaries between the producer and the final customer. A direct channel has zero levels.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:chart of account","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Chart of accounts","back":"The list of all the accounts a business uses, each with a name and usually a number, arranged by type.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:classified balance sheet","kind":"term","course":"f01","lesson":"financial-statements","front":"Classified balance sheet","back":"A balance sheet that groups assets and liabilities into current and noncurrent categories.","href":"learn/finance/f01/financial-statements/"},{"id":"t:cleaning log","kind":"term","course":"b02","lesson":"data-quality-report","front":"Cleaning log","back":"The ordered record of every cleaning step: what was done, to which rows and columns, by what rule, and the row count afterwards.","href":"learn/analytics/b02/data-quality-report/"},{"id":"t:closing entry","kind":"term","course":"f01","lesson":"closing-entries","front":"Closing entries","back":"Journal entries made at the end of an accounting period that transfer the balances of the revenue, expense and dividend accounts to Retained Earnings, leaving those accounts at zero.","href":"learn/finance/f01/closing-entries/"},{"id":"t:code point","kind":"term","course":"b02","lesson":"text-and-categories","front":"Code point","back":"The number the Unicode standard assigns to a character, written in the form U+00E9.","href":"learn/analytics/b02/text-and-categories/"},{"id":"t:commercial bank","kind":"term","course":"f00","lesson":"market-participants","front":"Commercial bank","back":"A bank that takes deposits, makes loans and provides payment services to households and firms.","href":"learn/finance/f00/market-participants/"},{"id":"t:commodity market","kind":"term","course":"f00","lesson":"financial-markets","front":"Commodity market","back":"The market for raw materials such as oil, metals and crops, traded for immediate delivery (spot) or through futures contracts.","href":"learn/finance/f00/financial-markets/"},{"id":"t:common stock","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Common stock","back":"The equity account that records what shareholders have paid the corporation in exchange for its common shares (share capital under IFRS). Some companies split this amount between the shares’ par value and additional paid-in capital, a detail later courses cover.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:compensating error","kind":"term","course":"f01","lesson":"trial-balance","front":"Compensating error","back":"Two or more errors whose effects on the debit and credit totals cancel out, so the trial balance still balances.","href":"learn/finance/f01/trial-balance/"},{"id":"t:competition-based pricing","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Competition-based pricing","back":"Setting a price mainly from competitors’ prices: charging the going rate in markets for similar products, or bidding against expected rival bids in sealed-bid contracts.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:competitive-parity method","kind":"term","course":"m02","lesson":"promotion-mix","front":"Competitive-parity method","back":"Setting the promotion budget to match competitors’ spending, in dollars or relative to sales.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:completeness","kind":"term","course":"b02","lesson":"profiling-and-validation","front":"Completeness","back":"The proportion of values present out of those that should be present.","href":"learn/analytics/b02/profiling-and-validation/"},{"id":"t:composite key","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Composite key","back":"A primary key made of two or more columns, such as order_id and line together in a line-item report.","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:compound entry","kind":"term","course":"f01","lesson":"journal-entries","front":"Compound entry","back":"A journal entry with more than one debit, more than one credit, or both. Its debit total still equals its credit total.","href":"learn/finance/f01/journal-entries/"},{"id":"t:compound interest","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Compound interest","back":"Interest calculated on the principal and on interest already added to the balance, so the balance grows by the same percentage each period.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:compounding","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Compounding","back":"Earning interest on interest already earned, because each period’s interest is added to the balance and earns interest in later periods.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:compounding frequency","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Compounding frequency","back":"How many times a year interest is calculated and added to the balance: annually, semi-annually, quarterly, monthly or daily.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:conceptual framework","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Conceptual framework","back":"A coherent set of concepts underlying accounting standards: the objective of financial reporting, the qualities that make information useful, and the definition, recognition and measurement of the elements of financial statements.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:consistency","kind":"term","course":"b02","lesson":"profiling-and-validation","front":"Consistency","back":"Whether the same thing is represented the same way wherever it appears, within a dataset and across datasets.","href":"learn/analytics/b02/profiling-and-validation/"},{"id":"t:consumer price index","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Consumer Price Index","back":"The best-known US price index, published by the Bureau of Labor Statistics: a measure of the average change over time in the prices urban consumers pay for a basket of goods and services. Often shortened to CPI.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:continuous variable","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Continuous variable","back":"A numerical variable that can take any value within a range, at least in principle, usually a measurement such as weight or time.","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:contra account","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Contra account","back":"An account paired with another account whose balance it reduces, such as Accumulated Depreciation—Equipment, which reduces Equipment. The two are reported together.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:contributed capital","kind":"term","course":"f01","lesson":"accounting-equation","front":"Contributed capital","back":"Equity supplied by owners in exchange for shares, recorded in Common Stock (share capital under IFRS).","href":"learn/finance/f01/accounting-equation/"},{"id":"t:contribution margin","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Contribution margin","back":"Price received minus variable cost per unit: what each unit contributes towards fixed costs and then profit. As a share of price it is the contribution margin ratio.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:control account","kind":"term","course":"f01","lesson":"general-ledger","front":"Control account","back":"A general-ledger account whose balance must equal the total of a subsidiary ledger, such as Accounts Receivable for the customer accounts.","href":"learn/finance/f01/general-ledger/"},{"id":"t:controlled vocabulary","kind":"term","course":"b02","lesson":"text-and-categories","front":"Controlled vocabulary","back":"The agreed list of allowed values for a column, usually set in the data dictionary or by an outside standard.","href":"learn/analytics/b02/text-and-categories/"},{"id":"t:controller","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Controller","back":"The manager responsible for a company’s accounting, financial reporting and internal controls.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:convenience product","kind":"term","course":"m02","lesson":"product-decisions","front":"Convenience product","back":"A consumer product bought often and quickly, with little comparison, usually at a low price and from many outlets.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:conversion rate","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Conversion rate","back":"The share of clicks (or visits) that end in the action a campaign seeks, such as an order or sign-up.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:core benefit","kind":"term","course":"m02","lesson":"product-decisions","front":"Core benefit","back":"The underlying need a customer satisfies by buying a product; what the customer is really buying.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:corporate finance","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Corporate finance","back":"The branch of finance concerned with the decisions of businesses: which investments to make, how to pay for them and how to manage day-to-day cash. Also called business finance.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:correcting entry","kind":"term","course":"f01","lesson":"accounting-cycle","front":"Correcting entry","back":"A journal entry that fixes an error in an entry already posted, by recording the difference between what was recorded and what should have been.","href":"learn/finance/f01/accounting-cycle/"},{"id":"t:cost of capital","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Cost of capital","back":"The return that the suppliers of a business’s capital expect, and so the return the business must be expected to earn to keep their money. For debt it is close to the interest rate; for equity it is the return shareholders could expect elsewhere for a similar risk.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:cost-plus pricing","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Cost-plus pricing","back":"Setting a price by adding a markup, a fixed percentage of the unit cost, to that cost.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:covenant","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Covenants","back":"Promises written into a loan or bond agreement that restrict what the borrower may do or require it to meet conditions, such as a minimum current ratio or limits on dividends and further borrowing.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:cpa","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"CPA","back":"Certified public accountant: in the United States, an accountant licensed by a state board of accountancy after passing a national exam and meeting the state’s requirements.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:cpc","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"CPC","back":"Cost per click: spend ÷ clicks.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:cpm","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"CPM","back":"Cost per thousand impressions: spend ÷ impressions × 1,000.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:credit","kind":"term","course":"f01","lesson":"debits-and-credits","front":"Credit","back":"The right side of an account, or an amount entered there (abbreviated Cr). A credit increases liabilities, equity and revenue and decreases assets, expenses and dividends.","href":"learn/finance/f01/debits-and-credits/"},{"id":"t:cross-field check","kind":"term","course":"b02","lesson":"profiling-and-validation","front":"Cross-field check","back":"A validation rule that tests a relationship between values in the same row, such as check-out falling after check-in.","href":"learn/analytics/b02/profiling-and-validation/"},{"id":"t:ctr","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"CTR","back":"Click-through rate: clicks ÷ impressions.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:current asset","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Current assets","back":"Cash and assets expected to be turned into cash or used up within a year (or within the normal operating cycle, if longer), such as receivables, inventory and prepayments.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:current liability","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Current liabilities","back":"Obligations due within a year, such as amounts owed to suppliers, wages, taxes and loan repayments due within the year.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:current ratio","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Current ratio","back":"Current assets divided by current liabilities: how many dollars of current assets a firm holds for each dollar it must pay within the year.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:customer value","kind":"term","course":"m02","lesson":"marketing-mix","front":"Customer value","back":"The customer’s judgement of the benefits of an offer relative to its total cost in money, time, effort and risk, compared with the alternatives.","href":"learn/marketing/m02/marketing-mix/"},{"id":"t:d&a","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"D&A","back":"Depreciation and amortisation: the part of the cost of long-lived physical and intangible assets charged as an expense in the period.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:data dictionary","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Data dictionary","back":"A document recording, for each column of a dataset, its meaning, level of measurement, type, unit, allowed values, rule for blanks and business rules.","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:data leakage","kind":"term","course":"b02","lesson":"scaling","front":"Data leakage","back":"Using information when building a model that would not be available when the model makes real predictions, such as test-set values used to fit a preparation step. It makes performance estimates too optimistic.","href":"learn/analytics/b02/scaling/"},{"id":"t:data lineage","kind":"term","course":"b02","lesson":"data-quality-report","front":"Data lineage","back":"The traceable path from a figure or cleaned table back through every step to the raw data and the version of the steps that produced it.","href":"learn/analytics/b02/data-quality-report/"},{"id":"t:data minimisation","kind":"term","course":"b02","lesson":"data-quality-report","front":"Data minimisation","back":"The data-protection principle that personal data should be adequate, relevant and limited to what is necessary for the purpose.","href":"learn/analytics/b02/data-quality-report/"},{"id":"t:data profiling","kind":"term","course":"b02","lesson":"profiling-and-validation","front":"Data profiling","back":"Systematically describing what a dataset contains (types, blanks, distinct values, ranges, distributions and relationships between columns) before using or changing it.","href":"learn/analytics/b02/profiling-and-validation/"},{"id":"t:data quality dimension","kind":"term","course":"b02","lesson":"profiling-and-validation","front":"Data quality dimension","back":"One aspect of data quality that can be assessed and measured on its own, such as completeness or validity.","href":"learn/analytics/b02/profiling-and-validation/"},{"id":"t:data quality report","kind":"term","course":"b02","lesson":"data-quality-report","front":"Data quality report","back":"A document that travels with a cleaned dataset and records its source, its problems, the decisions taken and why, their effect on the results, the remaining limitations and how to reproduce the cleaning.","href":"learn/analytics/b02/data-quality-report/"},{"id":"t:data type","kind":"term","course":"b02","lesson":"types-and-formats","front":"Data type","back":"The kind of value a column holds (such as number, text, date and time, or boolean), which determines the operations that make sense on it.","href":"learn/analytics/b02/types-and-formats/"},{"id":"t:dataset","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Dataset","back":"A collection of values organised so that each value describes one characteristic of one thing; usually a table of rows and columns.","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:dealer","kind":"term","course":"f00","lesson":"market-participants","front":"Dealer","back":"A firm that trades securities with clients from its own inventory, as a principal, and earns the difference between its buying and selling prices.","href":"learn/finance/f00/market-participants/"},{"id":"t:debit","kind":"term","course":"f01","lesson":"debits-and-credits","front":"Debit","back":"The left side of an account, or an amount entered there (abbreviated Dr). A debit increases assets, expenses and dividends and decreases liabilities, equity and revenue.","href":"learn/finance/f01/debits-and-credits/"},{"id":"t:debt","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Debt","back":"Money borrowed under a contract that promises the lender interest and repayment of the principal on stated dates. Lenders do not own the business and are paid before shareholders.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:debt-to-equity ratio","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Debt-to-equity ratio","back":"Debt divided by shareholders’ equity, a measure of leverage. Some analysts use interest-bearing debt in the numerator, others total liabilities.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:decline stage","kind":"term","course":"m02","lesson":"product-life-cycle","front":"Decline stage","back":"The stage in which sales and profits fall, and the firm decides whether to keep, harvest or drop the product.","href":"learn/marketing/m02/product-life-cycle/"},{"id":"t:deduplication","kind":"term","course":"b02","lesson":"duplicates","front":"Deduplication","back":"Finding records that describe the same thing and reducing each group to a single record, or merging them, according to stated rules.","href":"learn/analytics/b02/duplicates/"},{"id":"t:default","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Default","back":"Failure to make a promised interest or principal payment on time, which gives the lender the right to take legal action to recover what it is owed.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:deferral","kind":"term","course":"f01","lesson":"accrual-vs-cash","front":"Deferral","back":"A timing difference in which cash is received or paid before the revenue or expense is recognised. Meanwhile the amount is a liability (unearned revenue) or an asset (prepaid expense).","href":"learn/finance/f01/accrual-vs-cash/"},{"id":"t:demand curve","kind":"term","course":"m02","lesson":"price-response","front":"Demand curve","back":"The quantity of a product customers would buy at each price over a period, with everything else held constant. A price change moves along it; other changes shift it.","href":"learn/marketing/m02/price-response/"},{"id":"t:depreciation","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Depreciation","back":"The systematic allocation of the cost of a long-lived asset, less its residual value, over its useful life. It is an expense in the accounts but uses no cash in the period it is recorded, and it is not a measure of market value.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:derivatives market","kind":"term","course":"f00","lesson":"financial-markets","front":"Derivatives market","back":"The market for contracts (forwards, futures, options, swaps) whose value depends on the price of something else, such as a share, a rate, a currency or a commodity.","href":"learn/finance/f00/financial-markets/"},{"id":"t:derived variable","kind":"term","course":"b02","lesson":"transforming-data","front":"Derived variable","back":"A new variable calculated from other variables of the same row, such as expected total = quantity × unit price − discount, or nights = check-out date − check-in date.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:direct and digital marketing","kind":"term","course":"m02","lesson":"promotion-mix","front":"Direct and digital marketing","back":"Communication with targeted individuals that invites a direct response, through email, direct mail, websites, apps and targeted online ads.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:direct channel","kind":"term","course":"m02","lesson":"distribution-channels","front":"Direct channel","back":"A channel with no intermediaries: the producer sells to the final customer itself, for example through its own shops or website.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:direct finance","kind":"term","course":"f00","lesson":"financial-markets","front":"Direct finance","back":"Finance in which borrowers sell their own securities to savers, who then hold a claim on the borrower.","href":"learn/finance/f00/financial-markets/"},{"id":"t:discount rate","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Discount rate","back":"The rate used to discount future amounts: the return available elsewhere on an investment of similar risk. Riskier amounts are discounted at higher rates.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:discounting","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Discounting","back":"Converting an amount to be received in the future into its value today by dividing by (1 + r) for each period of waiting.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:discrete variable","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Discrete variable","back":"A numerical variable that takes separate values with gaps between them, usually a count, such as packs ordered.","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:distributor","kind":"term","course":"m02","lesson":"distribution-channels","front":"Distributor","back":"A wholesaler that works closely with the producers it represents, usually holding their stock and selling and delivering it to stores. The terms are often used interchangeably.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:diversification","kind":"term","course":"f00","lesson":"decision-principles","front":"Diversification","back":"Spreading money across investments whose results do not move in lockstep, so that losses on some are partly offset by gains on others.","href":"learn/finance/f00/decision-principles/"},{"id":"t:dividend","kind":"term","course":"f01","lesson":"accounting-equation","front":"Dividends","back":"Distributions of profit to a corporation’s shareholders. They reduce equity but are not an expense.","href":"learn/finance/f01/accounting-equation/"},{"id":"t:double-entry bookkeeping","kind":"term","course":"f01","lesson":"debits-and-credits","front":"Double-entry bookkeeping","back":"The system of recording every transaction in at least two accounts with equal debits and credits, so that the accounting equation stays in balance.","href":"learn/finance/f01/debits-and-credits/"},{"id":"t:dual aspect","kind":"term","course":"f01","lesson":"accounting-equation","front":"Dual aspect","back":"The principle that every transaction affects at least two items in the accounting equation, so it stays in balance.","href":"learn/finance/f01/accounting-equation/"},{"id":"t:dummy variable","kind":"term","course":"b02","lesson":"encoding-categories","front":"Dummy variable","back":"A 0/1 column that marks whether a row belongs to one category. With dummy coding, a variable with k categories is represented by k − 1 dummy variables plus a reference category.","href":"learn/analytics/b02/encoding-categories/"},{"id":"t:dummy-variable trap","kind":"term","course":"b02","lesson":"encoding-categories","front":"Dummy-variable trap","back":"The perfect multicollinearity that arises when all k one-hot columns of a variable are used together with an intercept, so the coefficients can’t be uniquely estimated.","href":"learn/analytics/b02/encoding-categories/"},{"id":"t:duplicate record","kind":"term","course":"b02","lesson":"duplicates","front":"Duplicate record","back":"A row that describes the same real-world entity or event as another row in the same dataset.","href":"learn/analytics/b02/duplicates/"},{"id":"t:earnings per share","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"Earnings per share","back":"Net income divided by the number of shares outstanding. Often shortened to EPS.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:ebit","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"EBIT","back":"Earnings before interest and taxes: profit before paying lenders and tax. For a company with no income or costs outside its operations, EBIT equals operating profit; otherwise the two differ.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:ebitda","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"EBITDA","back":"Earnings before interest, taxes, depreciation and amortisation: EBIT plus D&amp;A. A widely used but non-GAAP measure of operating earnings.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:economic entity assumption","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Economic entity assumption","back":"The assumption that a business is separate from its owners and from other businesses, so its records contain only its own transactions and events.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:economic profit","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Economic profit","back":"Accounting profit minus the opportunity costs that accounting does not record, such as the owner’s forgone salary and the return her money could have earned elsewhere.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:economic","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Economics","back":"The study of how people, firms and societies make decisions in the face of scarcity.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:edit distance","kind":"term","course":"b02","lesson":"duplicates","front":"Edit distance","back":"The smallest number of single-character insertions, deletions and substitutions needed to turn one string into another; also called Levenshtein distance.","href":"learn/analytics/b02/duplicates/"},{"id":"t:effective annual rate","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Effective annual rate","back":"The interest rate that, compounded once a year, gives the same result as a quoted rate with more frequent compounding: (1 + r/m)^m − 1. Often shortened to EAR.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:elastic demand","kind":"term","course":"m02","lesson":"price-response","front":"Elastic demand","back":"Demand whose elasticity has a magnitude above 1: quantity changes by a larger percentage than price, so revenue moves in the opposite direction to price.","href":"learn/marketing/m02/price-response/"},{"id":"t:emergency fund","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Emergency fund","back":"Money a person keeps in liquid form to cover unexpected costs or a loss of income, usually measured in months of essential spending.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:enterprise value","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"Enterprise value","back":"Market capitalisation plus debt minus cash: the value of a company’s operating business, claimed jointly by its lenders and shareholders. Often shortened to EV.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:equity","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Equity","back":"In finance, money invested in a business in exchange for ownership. Shareholders have a residual claim: they receive what is left after lenders and other creditors are paid, with no promised payments and no limit on the upside.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:equity market","kind":"term","course":"f00","lesson":"financial-markets","front":"Equity market","back":"The market for shares (stock), which are ownership claims on companies. Also called the stock market.","href":"learn/finance/f00/financial-markets/"},{"id":"t:error of commission","kind":"term","course":"f01","lesson":"trial-balance","front":"Error of commission","back":"An amount recorded on the correct side but in the wrong account of the same type, such as rent posted to utilities expense or an invoice posted to the wrong customer.","href":"learn/finance/f01/trial-balance/"},{"id":"t:error of omission","kind":"term","course":"f01","lesson":"trial-balance","front":"Error of omission","back":"A transaction left out of the records entirely. Both sides are missing, so the trial balance still balances.","href":"learn/finance/f01/trial-balance/"},{"id":"t:error of original entry","kind":"term","course":"f01","lesson":"trial-balance","front":"Error of original entry","back":"A wrong amount recorded in the journal and posted to both accounts, so debits still equal credits.","href":"learn/finance/f01/trial-balance/"},{"id":"t:error of principle","kind":"term","course":"f01","lesson":"trial-balance","front":"Error of principle","back":"An amount recorded on the correct side but in the wrong type of account, such as a repair (an expense) debited to equipment (an asset).","href":"learn/finance/f01/trial-balance/"},{"id":"t:ev/ebitda","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"EV/EBITDA","back":"Enterprise value divided by EBITDA: a multiple that compares differently financed companies on the same footing.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:exact duplicate","kind":"term","course":"b02","lesson":"duplicates","front":"Exact duplicate","back":"A row whose values are identical to another row’s in every column.","href":"learn/analytics/b02/duplicates/"},{"id":"t:exchange","kind":"term","course":"f00","lesson":"financial-markets","front":"Exchange","back":"An organised marketplace with published rules and standardised products, where buyers’ and sellers’ orders meet and prices are visible to all.","href":"learn/finance/f00/financial-markets/"},{"id":"t:exchange-traded fund","kind":"term","course":"f00","lesson":"market-participants","front":"Exchange-traded fund","back":"A fund whose shares trade on a stock exchange throughout the day at market prices, which may differ slightly from its NAV (ETF).","href":"learn/finance/f00/market-participants/"},{"id":"t:exclusive distribution","kind":"term","course":"m02","lesson":"distribution-channels","front":"Exclusive distribution","back":"Allowing only one or a very few outlets in each area to sell a product.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:executory contract","kind":"term","course":"f01","lesson":"accounting-equation","front":"Executory contract","back":"A contract in which neither party has yet performed. It is not recorded in the accounts until one side acts, for example by paying or delivering.","href":"learn/finance/f01/accounting-equation/"},{"id":"t:expanded accounting equation","kind":"term","course":"f01","lesson":"accounting-equation","front":"Expanded accounting equation","back":"Assets = liabilities + common stock + beginning retained earnings + revenue − expenses − dividends.","href":"learn/finance/f01/accounting-equation/"},{"id":"t:expected value","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Expected value","back":"The probability-weighted average of the possible outcomes of an uncertain event: each outcome multiplied by its probability, then added.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:expense","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Expense","back":"Decreases in assets, or increases in liabilities, from using up resources in delivering goods or services. Expenses decrease equity; distributions to owners, such as dividends, are not expenses.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:expense recognition principle","kind":"term","course":"f01","lesson":"accrual-vs-cash","front":"Expense recognition principle","back":"Expenses are recognised in the period in which they are incurred, usually the period whose revenue they helped to earn. Often called the matching principle.","href":"learn/finance/f01/accrual-vs-cash/"},{"id":"t:fad","kind":"term","course":"m02","lesson":"product-life-cycle","front":"Fad","back":"A burst of intense enthusiasm for a product that rises quickly and collapses quickly.","href":"learn/marketing/m02/product-life-cycle/"},{"id":"t:faithful representation","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Faithful representation","back":"The quality of information that depicts what it claims to depict: complete, neutral and free from error. One of the two fundamental qualitative characteristics.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:fasb","kind":"term","course":"f01","lesson":"what-is-accounting","front":"FASB","back":"The Financial Accounting Standards Board: the independent, private-sector, not-for-profit body, established in 1973, that sets US GAAP and is recognised by the SEC as the accounting standard setter for public companies.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:fashion","kind":"term","course":"m02","lesson":"product-life-cycle","front":"Fashion","back":"A style that is currently accepted or popular in a field; fashions typically rise slowly, stay popular for a while and decline slowly.","href":"learn/marketing/m02/product-life-cycle/"},{"id":"t:fdic","kind":"term","course":"f00","lesson":"market-participants","front":"FDIC","back":"The Federal Deposit Insurance Corporation: the independent US agency, established in 1933, that insures bank deposits and deals with failed banks.","href":"learn/finance/f00/market-participants/"},{"id":"t:feature scaling","kind":"term","course":"b02","lesson":"scaling","front":"Feature scaling","back":"Converting numeric variables to comparable, unitless scales before they are used together in an analysis or model.","href":"learn/analytics/b02/scaling/"},{"id":"t:federal reserve","kind":"term","course":"f00","lesson":"market-participants","front":"Federal Reserve","back":"The central bank of the United States, created in 1913, which conducts monetary policy, supervises banks and supports financial stability and the payments system.","href":"learn/finance/f00/market-participants/"},{"id":"t:finance","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Finance","back":"The study of how people, businesses and governments raise, allocate and manage money over time, under uncertainty.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:financial accounting","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Financial accounting","back":"The branch of accounting that prepares general-purpose financial statements for outside users, such as investors and lenders, following accounting standards (US GAAP or IFRS).","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:financial asset","kind":"term","course":"f00","lesson":"financial-markets","front":"Financial assets","back":"Claims whose value comes from the payments they promise or make possible, such as shares, bonds, deposits and loans, rather than from any physical use.","href":"learn/finance/f00/financial-markets/"},{"id":"t:financial intermediary","kind":"term","course":"f00","lesson":"financial-markets","front":"Financial intermediary","back":"An institution, such as a bank, insurance company, pension fund or investment fund, that gathers money from savers and provides it to borrowers or invests it, changing the kind of claim along the way.","href":"learn/finance/f00/financial-markets/"},{"id":"t:financial market","kind":"term","course":"f00","lesson":"financial-markets","front":"Financial market","back":"Any arrangement through which people with money to spare provide it to people who need it, in exchange for claims on future payments; also the place or system in which those claims are traded.","href":"learn/finance/f00/financial-markets/"},{"id":"t:financial statement","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Financial statements","back":"Structured reports of a business’s performance and cash flows for a period and its financial position at a date, prepared under accounting rules: the income statement, statement of changes in equity, balance sheet and statement of cash flows, together with their notes.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:financial system","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Financial system","back":"The banks, markets and other institutions that move money from savers to borrowers and businesses, price time and risk, and help people share risk.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:financing activity","kind":"term","course":"f01","lesson":"financial-statements","front":"Financing activities","back":"Cash flows with owners and lenders: issuing stock, borrowing, repaying loan principal and paying dividends.","href":"learn/finance/f01/financial-statements/"},{"id":"t:financing decision","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Financing decision","back":"A firm’s choice of how to pay for its investments: with owners’ money (equity), borrowed money (debt) or a mix, called its capital structure.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:fixed cost","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Fixed cost","back":"A cost whose total stays the same over a period whatever the volume, within the range of activity planned: rent, salaries, listing fees, a committed promotion budget.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:foreign-exchange market","kind":"term","course":"f00","lesson":"financial-markets","front":"Foreign-exchange market","back":"The market in which currencies are exchanged for one another. It is almost entirely over the counter.","href":"learn/finance/f00/financial-markets/"},{"id":"t:format check","kind":"term","course":"b02","lesson":"profiling-and-validation","front":"Format check","back":"A validation rule that a text value follows a pattern, such as an email address containing exactly one @.","href":"learn/analytics/b02/profiling-and-validation/"},{"id":"t:frequency","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Frequency","back":"The average number of times each person reached was exposed to the campaign: impressions ÷ reach.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:frequency encoding","kind":"term","course":"b02","lesson":"encoding-categories","front":"Frequency encoding","back":"Replacing each category with its share of the training rows.","href":"learn/analytics/b02/encoding-categories/"},{"id":"t:full disclosure principle","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Full disclosure principle","back":"The principle that the financial statements and their notes should include all the information a reader needs to understand them.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:full outer join","kind":"term","course":"b02","lesson":"transforming-data","front":"Full outer join","back":"A join that keeps every row of both tables, matched where possible.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:future value","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Future value","back":"What an amount invested today will be worth at a later date, at a given rate of return: FV = PV(1 + r)ⁿ.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:fuzzy matching","kind":"term","course":"b02","lesson":"duplicates","front":"Fuzzy matching","back":"Comparing values by how similar they are rather than whether they are exactly equal, to find records that probably refer to the same thing.","href":"learn/analytics/b02/duplicates/"},{"id":"t:gaap","kind":"term","course":"f01","lesson":"what-is-accounting","front":"GAAP","back":"Generally accepted accounting principles: the body of standards and conventions that businesses in a jurisdiction follow in financial reporting. US GAAP is set by the FASB.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:general journal","kind":"term","course":"f01","lesson":"journal-entries","front":"General journal","back":"The all-purpose journal, in which any kind of transaction can be recorded. Businesses that also keep special journals use it for entries that fit none of them, such as adjusting and closing entries.","href":"learn/finance/f01/journal-entries/"},{"id":"t:general ledger","kind":"term","course":"f01","lesson":"general-ledger","front":"General ledger","back":"The collection of all a business’s accounts, one for each account in the chart of accounts, showing every amount posted to each account and its balance.","href":"learn/finance/f01/general-ledger/"},{"id":"t:geometric mean","kind":"term","course":"b02","lesson":"skewed-data","front":"Geometric mean","back":"The nth root of the product of n positive values, equal to the back-transformed mean of their logs; never larger than the arithmetic mean.","href":"learn/analytics/b02/skewed-data/"},{"id":"t:going concern assumption","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Going concern assumption","back":"The assumption that, unless there is evidence to the contrary, a business will continue operating for the foreseeable future.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:granularity","kind":"term","course":"b02","lesson":"transforming-data","front":"Granularity","back":"The level of detail that one row of a table represents, such as one order, one customer or one region in one month.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:gross rating point","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Gross rating points","back":"A measure of the weight of a campaign: reach (as a percentage of the target audience) × average frequency, or impressions as a percentage of the audience. Abbreviated GRPs.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:growth stage","kind":"term","course":"m02","lesson":"product-life-cycle","front":"Growth stage","back":"The stage in which sales rise quickly, competitors enter and profits rise.","href":"learn/marketing/m02/product-life-cycle/"},{"id":"t:hedge fund","kind":"term","course":"f00","lesson":"market-participants","front":"Hedge fund","back":"A private, unregistered investment fund, generally open only to wealthy or sophisticated investors, free to use leverage, short selling and derivatives.","href":"learn/finance/f00/market-participants/"},{"id":"t:hedging","kind":"term","course":"f00","lesson":"financial-markets","front":"Hedging","back":"Using a financial contract, often a derivative, to reduce a risk one already faces.","href":"learn/finance/f00/financial-markets/"},{"id":"t:hierarchy-of-effects model","kind":"term","course":"m02","lesson":"promotion-mix","front":"Hierarchy-of-effects model","back":"Any model that describes buying as a sequence of mental stages, such as awareness, knowledge, liking, preference, conviction and purchase.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:high cardinality","kind":"term","course":"b02","lesson":"encoding-categories","front":"High cardinality","back":"A categorical variable with a very large number of distinct values, such as postcodes or product codes.","href":"learn/analytics/b02/encoding-categories/"},{"id":"t:historical cost principle","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Historical cost principle","back":"The principle that assets are recorded at what they cost to acquire and get ready for use, and generally kept at that amount rather than updated to current value.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:holdout group","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Holdout group","back":"A randomly chosen group deliberately not exposed to a campaign, used as the comparison for measuring its incremental effect.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:iasb","kind":"term","course":"f01","lesson":"what-is-accounting","front":"IASB","back":"The International Accounting Standards Board: the independent standard-setting body within the IFRS Foundation that develops IFRS Accounting Standards. It was set up in 2001.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:ifr","kind":"term","course":"f01","lesson":"what-is-accounting","front":"IFRS","back":"International Financial Reporting Standards (formally IFRS Accounting Standards), written by the IASB. Each jurisdiction decides whether and for which companies to require them.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:impression","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Impressions","back":"The number of times an ad is displayed. Repeat views by the same person count separately; a served impression is counted on delivery, a viewable one only if it could actually be seen.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:imputation","kind":"term","course":"b02","lesson":"missing-values","front":"Imputation","back":"Replacing a missing value with a substitute value, such as a mean, a group median, a category such as “Unknown” or a model’s prediction.","href":"learn/analytics/b02/missing-values/"},{"id":"t:incentive pay","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Incentive pay","back":"Pay that depends on results, such as bonuses tied to targets, shares that vest over time and stock options, intended to align managers’ interests with owners’.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:income statement","kind":"term","course":"f01","lesson":"financial-statements","front":"Income statement","back":"The statement of revenue, expenses and net income for a period. It measures performance on the accrual basis.","href":"learn/finance/f01/financial-statements/"},{"id":"t:income summary","kind":"term","course":"f01","lesson":"closing-entries","front":"Income Summary","back":"A temporary account used only during closing. Revenue and expenses are closed into it, so its balance equals net income or net loss; it is then closed to Retained Earnings. It never appears on a financial statement.","href":"learn/finance/f01/closing-entries/"},{"id":"t:incremental cash flow","kind":"term","course":"f00","lesson":"decision-principles","front":"Incremental cash flow","back":"The difference between the cash flows with a decision and without it; the only cash flows that should influence the decision.","href":"learn/finance/f00/decision-principles/"},{"id":"t:incrementality","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Incrementality","back":"The part of an outcome, such as sales, that was caused by the marketing and would not have happened without it.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:indirect channel","kind":"term","course":"m02","lesson":"distribution-channels","front":"Indirect channel","back":"A channel that uses one or more intermediaries between the producer and the final customer.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:indirect finance","kind":"term","course":"f00","lesson":"financial-markets","front":"Indirect finance","back":"Finance in which a financial intermediary takes savers’ money and provides it to borrowers; savers hold a claim on the intermediary, not on the borrower.","href":"learn/finance/f00/financial-markets/"},{"id":"t:inelastic demand","kind":"term","course":"m02","lesson":"price-response","front":"Inelastic demand","back":"Demand whose elasticity has a magnitude below 1: quantity changes by a smaller percentage than price, so revenue moves in the same direction as price.","href":"learn/marketing/m02/price-response/"},{"id":"t:inflation","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Inflation","back":"A sustained rise in the general level of prices, measured as the percentage change in a price index.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:initial public offering","kind":"term","course":"f00","lesson":"financial-markets","front":"Initial public offering","back":"A company’s first sale of shares to the general public (IPO).","href":"learn/finance/f00/financial-markets/"},{"id":"t:inner join","kind":"term","course":"b02","lesson":"transforming-data","front":"Inner join","back":"A join that keeps only the rows whose key appears in both tables.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:institutional investor","kind":"term","course":"f00","lesson":"market-participants","front":"Institutional investors","back":"Organisations that invest large pools of other people’s money, such as pension funds, insurance companies, mutual funds and hedge funds.","href":"learn/finance/f00/market-participants/"},{"id":"t:integrated marketing communication","kind":"term","course":"m02","lesson":"promotion-mix","front":"Integrated marketing communications","back":"Planning and coordinating all promotion tools so that they deliver one clear, consistent message about the brand. Abbreviated IMC.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:intensive distribution","kind":"term","course":"m02","lesson":"distribution-channels","front":"Intensive distribution","back":"Placing a product in as many outlets as possible.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:interest","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Interest","back":"The price of using someone else’s money: what a borrower pays a lender, usually stated as a percentage of the amount borrowed per year.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:interest rate","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Interest rate","back":"The price of using money for a period, stated as a percentage of the amount per year: received by savers and lenders, paid by borrowers.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:interest-rate spread","kind":"term","course":"f00","lesson":"financial-markets","front":"Interest-rate spread","back":"The difference between the rate an intermediary charges borrowers and the rate it pays savers, in percentage points.","href":"learn/finance/f00/financial-markets/"},{"id":"t:intermediary","kind":"term","course":"m02","lesson":"distribution-channels","front":"Intermediary","back":"A business between the producer and the final customer that buys, sells, stores, moves or promotes the product.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:internal control","kind":"term","course":"f01","lesson":"accounting-cycle","front":"Internal control","back":"The processes, carried out by an organisation’s board, managers and staff, that give reasonable assurance that its operations run well, its reporting is reliable and it complies with laws and regulations.","href":"learn/finance/f01/accounting-cycle/"},{"id":"t:interquartile range","kind":"term","course":"b02","lesson":"outliers","front":"Interquartile range","back":"The third quartile minus the first quartile: the width of the middle half of the data (IQR).","href":"learn/analytics/b02/outliers/"},{"id":"t:interval variable","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Interval variable","back":"A numerical variable on which differences are meaningful but zero is an arbitrary point, so ratios are not, such as a calendar date or a temperature in °C.","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:introduction stage","kind":"term","course":"m02","lesson":"product-life-cycle","front":"Introduction stage","back":"The first stage of the life cycle after launch: low awareness, slow sales growth, high costs and usually losses.","href":"learn/marketing/m02/product-life-cycle/"},{"id":"t:investing activity","kind":"term","course":"f01","lesson":"financial-statements","front":"Investing activities","back":"Cash flows from buying and selling long-term assets, such as equipment, and investments.","href":"learn/finance/f01/financial-statements/"},{"id":"t:investment bank","kind":"term","course":"f00","lesson":"market-participants","front":"Investment bank","back":"A firm that helps companies and governments raise money by underwriting new securities, advises on mergers and acquisitions, and often trades securities.","href":"learn/finance/f00/market-participants/"},{"id":"t:investment decision","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Investment decision","back":"A firm’s choice of which long-term assets and projects to put money into. The analysis behind it is capital budgeting.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:investment finance","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Investment finance","back":"The branch of finance concerned with the decisions of investors: which securities to buy, how to combine them and what they are worth. Also called investments.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:iso 8601","kind":"term","course":"b02","lesson":"types-and-formats","front":"ISO 8601","back":"The international standard for representing dates and times, with units from largest to smallest; dates are usually written YYYY-MM-DD (its extended format) or YYYYMMDD (its basic format).","href":"learn/analytics/b02/types-and-formats/"},{"id":"t:issuer","kind":"term","course":"f00","lesson":"financial-markets","front":"Issuer","back":"The company, government or other body that creates a security and receives the money when it is first sold.","href":"learn/finance/f00/financial-markets/"},{"id":"t:join","kind":"term","course":"b02","lesson":"transforming-data","front":"Join","back":"Combining two tables by matching the values of a key column, so that each row gains the matching columns of the other table.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:journal","kind":"term","course":"f01","lesson":"journal-entries","front":"Journal","back":"A record of transactions in date order, each written as a complete entry with its debits, credits and explanation. Also called the book of original entry.","href":"learn/finance/f01/journal-entries/"},{"id":"t:journal entry","kind":"term","course":"f01","lesson":"journal-entries","front":"Journal entry","back":"The record of one transaction in a journal: the date, the accounts and amounts debited and credited, and a short explanation.","href":"learn/finance/f01/journal-entries/"},{"id":"t:journalising","kind":"term","course":"f01","lesson":"journal-entries","front":"Journalising","back":"Recording transactions in a journal.","href":"learn/finance/f01/journal-entries/"},{"id":"t:label encoding","kind":"term","course":"b02","lesson":"encoding-categories","front":"Label encoding","back":"Giving each category an arbitrary integer code, often in alphabetical order. Misleading for nominal input variables in linear and distance-based models.","href":"learn/analytics/b02/encoding-categories/"},{"id":"t:law of one price","kind":"term","course":"f00","lesson":"decision-principles","front":"Law of one price","back":"The principle that identical goods or assets, producing identical cash flows, should sell for the same price, because otherwise traders could profit by buying the cheaper and selling the dearer.","href":"learn/finance/f00/decision-principles/"},{"id":"t:leading zero","kind":"term","course":"b02","lesson":"types-and-formats","front":"Leading zero","back":"A zero at the start of a code, such as the first two digits of 004517. It carries no numerical value but is part of the identifier, and is lost if the code is stored as a number.","href":"learn/analytics/b02/types-and-formats/"},{"id":"t:left join","kind":"term","course":"b02","lesson":"transforming-data","front":"Left join","back":"A join that keeps every row of the left table, leaving the right table’s columns missing where there is no match.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:left-skewed","kind":"term","course":"b02","lesson":"skewed-data","front":"Left-skewed","back":"Having a long tail of small values; the mean is usually below the median. Also called negatively skewed.","href":"learn/analytics/b02/skewed-data/"},{"id":"t:leverage","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Leverage","back":"The use of debt to finance part of a business. Because interest is set by the loan contract and does not rise when the business does well, leverage magnifies shareholders’ gains and losses. Also called gearing.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:liability","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Liability","back":"A present obligation of the business to transfer an economic resource to others, arising from past events.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:line extension","kind":"term","course":"m02","lesson":"product-decisions","front":"Line extension","back":"A new variant (flavour, size, format) added under an existing brand in a category where the brand already sells. Taking a brand into a new category is a brand extension.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:liquidity","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Liquidity","back":"For an asset, how quickly it can be turned into cash with little loss of value. For a firm or person, the ability to meet obligations as they fall due.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:listwise deletion","kind":"term","course":"b02","lesson":"missing-values","front":"Listwise deletion","back":"Dropping every row that has a missing value in any variable an analysis uses; also called complete-case analysis.","href":"learn/analytics/b02/missing-values/"},{"id":"t:locale","kind":"term","course":"b02","lesson":"types-and-formats","front":"Locale","back":"The conventions of a language and region for writing numbers, dates, times and currency, such as the decimal mark, the thousands separator and the order of day and month.","href":"learn/analytics/b02/types-and-formats/"},{"id":"t:lock-up","kind":"term","course":"f00","lesson":"market-participants","front":"Lock-up","back":"An agreement by a company’s existing shareholders not to sell their shares for a period after an IPO, typically 180 days.","href":"learn/finance/f00/market-participants/"},{"id":"t:log transformation","kind":"term","course":"b02","lesson":"skewed-data","front":"Log transformation","back":"Replacing each value x with ln x (or a log to another base); it needs positive values and turns equal ratios into equal differences.","href":"learn/analytics/b02/skewed-data/"},{"id":"t:log1p transformation","kind":"term","course":"b02","lesson":"skewed-data","front":"Log1p transformation","back":"Replacing each value x with ln(1 + x), so that zeros become 0; its effect depends on the units of x.","href":"learn/analytics/b02/skewed-data/"},{"id":"t:logistic","kind":"term","course":"m02","lesson":"distribution-channels","front":"Logistics","back":"Planning and controlling the physical flow of goods, including inventory, storage and transport, from the producer to the customer.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:long format","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Long format","back":"A layout in which that variable has a column of its own and each combination of values has its own row.","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:macroeconomic","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Macroeconomics","back":"The part of economics that studies the economy as a whole: total output and growth, unemployment, inflation, interest rates and government and central bank policy.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:managerial accounting","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Managerial accounting","back":"The branch of accounting that prepares internal reports, such as budgets, cost reports and forecasts, to help managers plan, control and decide. It follows no externally imposed rules and often uses nonfinancial measures. Also called management accounting.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:mapping table","kind":"term","course":"b02","lesson":"text-and-categories","front":"Mapping table","back":"A table that lists each variant of a value and the value it should become, kept as reviewed and versioned data rather than as one-off edits.","href":"learn/analytics/b02/text-and-categories/"},{"id":"t:mar","kind":"term","course":"b02","lesson":"missing-values","front":"MAR","back":"Missing at random: whether a value is missing depends only on recorded variables; within groups defined by them it is unrelated to the missing value itself.","href":"learn/analytics/b02/missing-values/"},{"id":"t:margin","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Margin","back":"Profit per unit as a percentage of price: (price − cost) ÷ price. Also called margin on price or, in some texts, markup on selling price.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:market capitalisation","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"Market capitalisation","back":"Share price multiplied by the number of shares outstanding: the market value of a company’s equity. Often shortened to market cap.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:market maker","kind":"term","course":"f00","lesson":"market-participants","front":"Market maker","back":"A dealer that stands ready at all times to buy a security at its bid and sell it at its ask, providing liquidity.","href":"learn/finance/f00/market-participants/"},{"id":"t:market value","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"Market value","back":"What buyers and sellers are paying for something now. For a listed company’s equity it is the market capitalisation.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:market-to-book ratio","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"Market-to-book ratio","back":"Market capitalisation divided by the book value of equity (or price per share divided by book value per share). Also called price-to-book.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:marketing","kind":"term","course":"m02","lesson":"marketing-mix","front":"Marketing","back":"The activity of creating, communicating, delivering and exchanging offerings that have value for customers, clients, partners and society (a paraphrase of the American Marketing Association’s definition).","href":"learn/marketing/m02/marketing-mix/"},{"id":"t:marketing channel","kind":"term","course":"m02","lesson":"distribution-channels","front":"Marketing channel","back":"The set of organisations that work together to make a product available to the people who use it; also called a distribution channel.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:marketing mix","kind":"term","course":"m02","lesson":"marketing-mix","front":"Marketing mix","back":"The set of controllable decisions a business combines to create, communicate, deliver and capture value for its target market.","href":"learn/marketing/m02/marketing-mix/"},{"id":"t:marketing roi","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Marketing ROI","back":"Return on marketing investment: (incremental contribution − marketing cost) ÷ marketing cost. Variants use gross profit or lifetime value.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:markup","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Markup","back":"Profit per unit as a percentage of cost: (price − cost) ÷ cost.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:masking","kind":"term","course":"b02","lesson":"outliers","front":"Masking","back":"The effect in which outliers inflate the mean and standard deviation used to detect them, so that they, or other outliers, no longer look extreme.","href":"learn/analytics/b02/outliers/"},{"id":"t:materiality","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Materiality","back":"Information is material if omitting or misstating it could influence the decisions of the people relying on the report. It depends on the size and nature of the item in a particular business; there is no universal threshold.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:maturity stage","kind":"term","course":"m02","lesson":"product-life-cycle","front":"Maturity stage","back":"The stage in which sales growth slows and flattens, competition is intense and one brand’s gains come mainly from others. Usually the longest stage.","href":"learn/marketing/m02/product-life-cycle/"},{"id":"t:mcar","kind":"term","course":"b02","lesson":"missing-values","front":"MCAR","back":"Missing completely at random: whether a value is missing is unrelated to any data, recorded or not.","href":"learn/analytics/b02/missing-values/"},{"id":"t:mean imputation","kind":"term","course":"b02","lesson":"missing-values","front":"Mean imputation","back":"Filling every missing value in a column with the mean of the observed values; it keeps the mean, shrinks the spread and weakens relationships.","href":"learn/analytics/b02/missing-values/"},{"id":"t:median absolute deviation","kind":"term","course":"b02","lesson":"outliers","front":"Median absolute deviation","back":"The median of the absolute distances of the values from their median (MAD); a robust measure of spread.","href":"learn/analytics/b02/outliers/"},{"id":"t:melt","kind":"term","course":"b02","lesson":"transforming-data","front":"Melt","back":"Reshaping from wide to long format, also called unpivoting: several columns become one column of former headers and one column of values.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:microeconomic","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Microeconomics","back":"The part of economics that studies the decisions of individual households and firms and how they interact in particular markets.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:midpoint formula","kind":"term","course":"m02","lesson":"price-response","front":"Midpoint formula","back":"A way of calculating elasticity between two observed points that divides each change by the average of the two values, so the answer is the same in either direction. Also called arc elasticity.","href":"learn/marketing/m02/price-response/"},{"id":"t:min–max normalisation","kind":"term","course":"b02","lesson":"scaling","front":"Min–max normalisation","back":"Rescaling a variable as (x − minimum) ÷ (maximum − minimum), so the training data run from 0 to 1.","href":"learn/analytics/b02/scaling/"},{"id":"t:missing value","kind":"term","course":"b02","lesson":"missing-values","front":"Missing value","back":"A cell where a value should exist but was not recorded, whether it appears as a blank, a code such as NA or −999, a text stand-in such as “unknown”, or an impossible value.","href":"learn/analytics/b02/missing-values/"},{"id":"t:missing-value indicator","kind":"term","course":"b02","lesson":"missing-values","front":"Missing-value indicator","back":"A 0/1 column that records which values were missing before imputation, kept for auditing and as a possible model input.","href":"learn/analytics/b02/missing-values/"},{"id":"t:mnar","kind":"term","course":"b02","lesson":"missing-values","front":"MNAR","back":"Missing not at random: whether a value is missing depends on the missing value itself, even after allowing for the recorded variables.","href":"learn/analytics/b02/missing-values/"},{"id":"t:modified z-score","kind":"term","course":"b02","lesson":"outliers","front":"Modified z-score","back":"A robust z-score, 0.6745 × (x − median) ÷ MAD; absolute values above 3.5 are flagged as potential outliers.","href":"learn/analytics/b02/outliers/"},{"id":"t:monetary unit assumption","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Monetary unit assumption","back":"The assumption that only events measurable in money are recorded, in a currency treated as a stable unit, so changes in its purchasing power are ignored.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:money market","kind":"term","course":"f00","lesson":"financial-markets","front":"Money market","back":"The market for short-term debt maturing in less than a year, such as Treasury bills and commercial paper.","href":"learn/finance/f00/financial-markets/"},{"id":"t:multichannel distribution","kind":"term","course":"m02","lesson":"distribution-channels","front":"Multichannel distribution","back":"Selling the same product through more than one channel at the same time.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:multiple imputation","kind":"term","course":"b02","lesson":"missing-values","front":"Multiple imputation","back":"Creating several completed copies of a dataset with different plausible fills, analysing each, and pooling the results so that the uncertainty about the missing values is reflected in the answer.","href":"learn/analytics/b02/missing-values/"},{"id":"t:mutual fund","kind":"term","course":"f00","lesson":"market-participants","front":"Mutual fund","back":"An SEC-registered investment company that pools money from many investors; investors buy shares from and sell them back to the fund at the NAV calculated once each business day.","href":"learn/finance/f00/market-participants/"},{"id":"t:near duplicate","kind":"term","course":"b02","lesson":"duplicates","front":"Near duplicate","back":"A record that describes the same entity as another but whose values differ slightly, for example in case, spacing, spelling or a second email address.","href":"learn/analytics/b02/duplicates/"},{"id":"t:net asset value","kind":"term","course":"f00","lesson":"market-participants","front":"Net asset value","back":"A fund’s assets minus its liabilities; per share, divided by the number of fund shares outstanding (NAV).","href":"learn/finance/f00/market-participants/"},{"id":"t:net asset","kind":"term","course":"f01","lesson":"accounting-equation","front":"Net assets","back":"Assets minus liabilities; another name for equity.","href":"learn/finance/f01/accounting-equation/"},{"id":"t:net debt","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"Net debt","back":"Debt minus cash. Enterprise value equals market capitalisation plus net debt.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:net income","kind":"term","course":"f01","lesson":"accounting-equation","front":"Net income","back":"Revenue minus expenses for a period. A negative result is a net loss.","href":"learn/finance/f01/accounting-equation/"},{"id":"t:net proceed","kind":"term","course":"f00","lesson":"market-participants","front":"Net proceeds","back":"What the issuer receives from an offering after the underwriting spread: shares sold × offer price × (1 − spread).","href":"learn/finance/f00/market-participants/"},{"id":"t:nominal return","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Nominal return","back":"The percentage change in the number of dollars an investment is worth, before allowing for inflation.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:nominal variable","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Nominal variable","back":"A categorical variable whose categories have no natural order, such as region or product. Supports equality, counts and the mode.","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:non-breaking space","kind":"term","course":"b02","lesson":"text-and-categories","front":"Non-breaking space","back":"A space character (Unicode U+00A0) that looks like an ordinary space but is a different character, often left behind by web pages and documents, and not removed by some trim functions.","href":"learn/analytics/b02/text-and-categories/"},{"id":"t:noncurrent asset","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Noncurrent asset","back":"Any asset that is not current, typically one the business expects to use for more than a year, such as equipment, vehicles, buildings and land.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:noncurrent liability","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Noncurrent liability","back":"An obligation not due for settlement within one year or the operating cycle, such as the later instalments of a long-term loan.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:normal balance","kind":"term","course":"f01","lesson":"debits-and-credits","front":"Normal balance","back":"The side on which an account records increases, and so the side on which its balance usually sits: debit for assets, expenses and dividends; credit for liabilities, equity, revenue and contra-asset accounts.","href":"learn/finance/f01/debits-and-credits/"},{"id":"t:objective-and-task method","kind":"term","course":"m02","lesson":"promotion-mix","front":"Objective-and-task method","back":"Setting the promotion budget by defining specific objectives, listing the tasks needed to achieve them and adding up the cost of those tasks.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:observation","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Observation","back":"One row of a dataset: all the values recorded for one instance of the unit of observation. Also called a record.","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:omnichannel","kind":"term","course":"m02","lesson":"distribution-channels","front":"Omnichannel","back":"Managing several channels as one system from the customer’s point of view, with consistent prices, promotions, stock information and service across them.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:one-hot encoding","kind":"term","course":"b02","lesson":"encoding-categories","front":"One-hot encoding","back":"Encoding a categorical variable with k categories as k columns of 0s and 1s, with a 1 in the column of each row’s category.","href":"learn/analytics/b02/encoding-categories/"},{"id":"t:operating activity","kind":"term","course":"f01","lesson":"financial-statements","front":"Operating activities","back":"Cash flows from running the business: receipts from customers and payments to suppliers, employees and others; under US GAAP also interest paid and received.","href":"learn/finance/f01/financial-statements/"},{"id":"t:operating cash flow","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Operating cash flow","back":"The cash brought in by a business’s day-to-day activities minus the cash those activities paid out, over a period.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:operating cycle","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Operating cycle","back":"The average time between acquiring the materials or services a business works with and collecting cash from the customers it sells to.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:opportunity cost","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Opportunity cost","back":"The value of the best alternative given up when a choice is made, such as the salary an owner forgoes to run her own business.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:ordinal encoding","kind":"term","course":"b02","lesson":"encoding-categories","front":"Ordinal encoding","back":"Encoding an ordered categorical variable as integers that follow its order, in one column. It assumes equal steps between levels.","href":"learn/analytics/b02/encoding-categories/"},{"id":"t:ordinal variable","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Ordinal variable","back":"A categorical variable whose categories have a meaningful order but no fixed distance between them, such as a 1–5 rating. Also supports the median and percentiles.","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:outlier","kind":"term","course":"b02","lesson":"outliers","front":"Outlier","back":"An observation that lies an abnormal distance from the other values in a dataset; it may be an error or a genuine extreme.","href":"learn/analytics/b02/outliers/"},{"id":"t:over-the-counter market","kind":"term","course":"f00","lesson":"financial-markets","front":"Over-the-counter market","back":"A market without a central marketplace, in which trades are negotiated between two parties, usually with a dealer (OTC).","href":"learn/finance/f00/financial-markets/"},{"id":"t:ownership category","kind":"term","course":"f00","lesson":"market-participants","front":"Ownership category","back":"For FDIC insurance, the capacity in which deposits are held (single, joint, certain retirement, trust, business, and others); each category at each bank is insured separately.","href":"learn/finance/f00/market-participants/"},{"id":"t:p/e ratio","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"P/E ratio","back":"Price-to-earnings ratio: share price divided by earnings per share, or market capitalisation divided by net income.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:packaging","kind":"term","course":"m02","lesson":"product-decisions","front":"Packaging","back":"The container and wrapping of a product, which protects it, makes it convenient, informs the buyer and promotes it at the point of choice.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:pairwise deletion","kind":"term","course":"b02","lesson":"missing-values","front":"Pairwise deletion","back":"Computing each statistic from all rows that have the values it needs, so different statistics use different rows; also called available-case analysis.","href":"learn/analytics/b02/missing-values/"},{"id":"t:penetration pricing","kind":"term","course":"m02","lesson":"price-response","front":"Penetration pricing","back":"Launching a new product at a low price to win many buyers quickly, accepting a low margin per unit in exchange for volume.","href":"learn/marketing/m02/price-response/"},{"id":"t:pension fund","kind":"term","course":"f00","lesson":"market-participants","front":"Pension fund","back":"A fund that invests contributions from employers and employees to pay retirement income.","href":"learn/finance/f00/market-participants/"},{"id":"t:percentage point","kind":"term","course":"b02","lesson":"data-quality-report","front":"Percentage point","back":"The unit for the difference between two percentages: a change from 8% to 5% is a fall of 3 percentage points (and a relative fall of 37.5%).","href":"learn/analytics/b02/data-quality-report/"},{"id":"t:percentage-of-sales method","kind":"term","course":"m02","lesson":"promotion-mix","front":"Percentage-of-sales method","back":"Setting the promotion budget as a fixed percentage of past or forecast sales.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:performance obligation","kind":"term","course":"f01","lesson":"accrual-vs-cash","front":"Performance obligation","back":"A promise in a contract to transfer a distinct good or service to a customer. Revenue is recognised as each one is satisfied, at a point in time or over time.","href":"learn/finance/f01/accrual-vs-cash/"},{"id":"t:permanent account","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Permanent account","back":"An account whose balance carries forward from one period to the next: every asset, liability and equity account, including contra-asset accounts. Also called a real account.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:personal finance","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Personal finance","back":"The branch of finance concerned with the decisions of individuals and households: budgeting, saving, borrowing, insurance and retirement.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:personal selling","kind":"term","course":"m02","lesson":"promotion-mix","front":"Personal selling","back":"Person-to-person communication by a salesperson aimed at making sales and building customer relationships.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:pivot","kind":"term","course":"b02","lesson":"transforming-data","front":"Pivot","back":"Reshaping from long to wide format: the values of one column become column headers. It needs exactly one value for each pair of row label and column label.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:positioning","kind":"term","course":"m02","lesson":"marketing-mix","front":"Positioning","back":"The place a business wants its offer to occupy in target customers’ minds, relative to competing offers.","href":"learn/marketing/m02/marketing-mix/"},{"id":"t:post-closing trial balance","kind":"term","course":"f01","lesson":"closing-entries","front":"Post-closing trial balance","back":"A trial balance prepared after the closing entries are posted. It contains only permanent accounts and confirms that debits equal credits as the next period begins.","href":"learn/finance/f01/closing-entries/"},{"id":"t:posting","kind":"term","course":"f01","lesson":"general-ledger","front":"Posting","back":"Copying each line of a journal entry to the ledger account it names, on the same side, with the same date and amount.","href":"learn/finance/f01/general-ledger/"},{"id":"t:posting reference","kind":"term","course":"f01","lesson":"general-ledger","front":"Posting reference","back":"A cross-reference written during posting: the journal page in the ledger account, and the account number in the journal, so any amount can be traced in both directions.","href":"learn/finance/f01/general-ledger/"},{"id":"t:prepaid expense","kind":"term","course":"f01","lesson":"adjusting-entries","front":"Prepaid expense","back":"A cost paid in advance for benefits to be received in later periods, such as insurance or rent. It is an asset until it is used up.","href":"learn/finance/f01/adjusting-entries/"},{"id":"t:present value","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Present value","back":"What an amount to be received in the future is worth today, at a given discount rate: PV = FV ÷ (1 + r)ⁿ.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:price build-up","kind":"term","course":"m02","lesson":"distribution-channels","front":"Price build-up","back":"A calculation that traces a product’s price through each level of the channel, from what the producer receives to what the final customer pays.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:price ceiling","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Price ceiling","back":"The highest price customers would pay, set by the value they place on the product compared with their alternatives.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:price discovery","kind":"term","course":"f00","lesson":"financial-markets","front":"Price discovery","back":"The process by which trading among many buyers and sellers produces a price that reflects their combined information and expectations.","href":"learn/finance/f00/financial-markets/"},{"id":"t:price discrimination","kind":"term","course":"m02","lesson":"price-response","front":"Price discrimination","back":"Charging different customers different prices for the same product when the difference does not reflect a difference in cost. Also called segmented pricing.","href":"learn/marketing/m02/price-response/"},{"id":"t:price elasticity of demand","kind":"term","course":"m02","lesson":"price-response","front":"Price elasticity of demand","back":"The percentage change in quantity demanded divided by the percentage change in price. Usually negative; this course keeps the sign, while many texts report the absolute value.","href":"learn/marketing/m02/price-response/"},{"id":"t:price floor","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Price floor","back":"The lowest price worth accepting, set by costs: in the short run the variable cost per unit; in the long run a price that covers all costs at a realistic volume.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:price index","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Price index","back":"A number tracking the cost of a fixed basket of goods and services over time, set to 100 in a base period.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:price skimming","kind":"term","course":"m02","lesson":"price-response","front":"Price skimming","back":"Launching a new product at a high price to sell first to the buyers who value it most, then lowering the price in steps to reach more buyers.","href":"learn/marketing/m02/price-response/"},{"id":"t:primary key","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Primary key","back":"A column, or set of columns, whose values identify each row uniquely: no two rows share a value and none is blank.","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:primary market","kind":"term","course":"f00","lesson":"financial-markets","front":"Primary market","back":"The market in which new securities are sold for the first time, with the money going to the issuer.","href":"learn/finance/f00/financial-markets/"},{"id":"t:principal","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Principal","back":"The amount originally borrowed or invested, on which interest is calculated.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:product","kind":"term","course":"m02","lesson":"product-decisions","front":"Product","back":"Anything offered to a market to satisfy a want or need: physical goods, services, experiences, places, organisations or ideas.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:product life cycle","kind":"term","course":"m02","lesson":"product-life-cycle","front":"Product life cycle","back":"The typical pattern of a product’s sales and profits over time, from introduction through growth and maturity to decline.","href":"learn/marketing/m02/product-life-cycle/"},{"id":"t:product line","kind":"term","course":"m02","lesson":"product-decisions","front":"Product line","back":"A group of closely related products that meet similar needs, are sold to similar customers or go through similar channels.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:product line depth","kind":"term","course":"m02","lesson":"product-decisions","front":"Product line depth","back":"The number of versions offered of each item in a line, such as sizes, flavours or colours (in Kotler’s convention).","href":"learn/marketing/m02/product-decisions/"},{"id":"t:product line length","kind":"term","course":"m02","lesson":"product-decisions","front":"Product line length","back":"The number of items in a product line (in Kotler’s convention; OpenStax calls this depth).","href":"learn/marketing/m02/product-decisions/"},{"id":"t:product mix","kind":"term","course":"m02","lesson":"product-decisions","front":"Product mix","back":"All the product lines and items a company sells; also called the product portfolio.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:product mix consistency","kind":"term","course":"m02","lesson":"product-decisions","front":"Product mix consistency","back":"How closely a company’s product lines are related in end use, production, distribution channels or customers.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:product mix width","kind":"term","course":"m02","lesson":"product-decisions","front":"Product mix width","back":"The number of different product lines a company carries.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:promotion mix","kind":"term","course":"m02","lesson":"promotion-mix","front":"Promotion mix","back":"The combination of communication tools (advertising, sales promotion, personal selling, public relations, and direct and digital marketing) a business uses to communicate with its audiences.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:pseudonymised","kind":"term","course":"b02","lesson":"data-quality-report","front":"Pseudonymised","back":"Describes data in which direct identifiers such as names or e-mail addresses are replaced by codes, so that records can still be linked but people can’t be identified without separately held information.","href":"learn/analytics/b02/data-quality-report/"},{"id":"t:psychological pricing","kind":"term","course":"m02","lesson":"price-response","front":"Psychological pricing","back":"Setting prices with regard to how buyers perceive numbers, for example charm prices just below a round number, or round prices that suggest quality.","href":"learn/marketing/m02/price-response/"},{"id":"t:public finance","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Public finance","back":"The branch of finance (often treated as part of economics) concerned with how governments tax, spend and borrow.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:public relation","kind":"term","course":"m02","lesson":"promotion-mix","front":"Public relations","back":"Building good relationships with a company’s publics and earning favourable coverage, for example through press releases, events and sponsorships.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:pull strategy","kind":"term","course":"m02","lesson":"promotion-mix","front":"Pull strategy","back":"Directing promotion at final customers to create demand that draws the product through the channel.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:purchasing power","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Purchasing power","back":"What a given amount of money can buy. Inflation reduces it.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:push strategy","kind":"term","course":"m02","lesson":"promotion-mix","front":"Push strategy","back":"Directing promotion at channel members, through personal selling and trade promotions, so that they stock, support and sell the product.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:quick ratio","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Quick ratio","back":"Cash, short-term investments and receivables divided by current liabilities. It leaves out inventory and prepayments. Also called the acid-test ratio.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:range check","kind":"term","course":"b02","lesson":"profiling-and-validation","front":"Range check","back":"A validation rule that a value lies between a minimum and a maximum.","href":"learn/analytics/b02/profiling-and-validation/"},{"id":"t:ratio variable","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Ratio variable","back":"A numerical variable with a true zero meaning “none”, so differences and ratios are both meaningful, such as quantity, price or nights stayed.","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:raw data","kind":"term","course":"b02","lesson":"data-quality-report","front":"Raw data","back":"Data exactly as received from their source, before any cleaning or transformation. Kept read-only so that every cleaned version can be rebuilt from them.","href":"learn/analytics/b02/data-quality-report/"},{"id":"t:reach","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Reach","back":"The number or percentage of different people in the target audience exposed to a campaign at least once.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:real interest rate","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Real interest rate","back":"An interest rate adjusted for inflation: what borrowing really costs, or lending really earns, in purchasing power.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:real return","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Real return","back":"The percentage change in the purchasing power of an investment: (1 + nominal return) ÷ (1 + inflation) − 1.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:reference category","kind":"term","course":"b02","lesson":"encoding-categories","front":"Reference category","back":"The category left without a dummy variable. The intercept describes it, and each dummy coefficient is a difference from it. Also called the baseline.","href":"learn/analytics/b02/encoding-categories/"},{"id":"t:reference price","kind":"term","course":"m02","lesson":"price-response","front":"Reference price","back":"The price a buyer expects or regards as normal for a product, formed largely from past prices, against which an actual price is judged as a gain or a loss.","href":"learn/marketing/m02/price-response/"},{"id":"t:referential integrity","kind":"term","course":"b02","lesson":"profiling-and-validation","front":"Referential integrity","back":"The condition that every reference from one table to another (a foreign key) points to a row that exists.","href":"learn/analytics/b02/profiling-and-validation/"},{"id":"t:regular expression","kind":"term","course":"b02","lesson":"text-and-categories","front":"Regular expression","back":"A pattern that describes a set of text strings, used to find, check, extract or replace text.","href":"learn/analytics/b02/text-and-categories/"},{"id":"t:relevance","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Relevance","back":"The quality of information that is capable of making a difference to users’ decisions, through predictive value, confirmatory value or both. One of the two fundamental qualitative characteristics.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:reproducibility","kind":"term","course":"b02","lesson":"data-quality-report","front":"Reproducibility","back":"The property that running the same steps on the same data gives the same result every time.","href":"learn/analytics/b02/data-quality-report/"},{"id":"t:reshaping","kind":"term","course":"b02","lesson":"transforming-data","front":"Reshaping","back":"Changing the layout of a table between wide and long format without changing its values.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:residual value","kind":"term","course":"f01","lesson":"adjusting-entries","front":"Residual value","back":"The amount a business expects to receive for an asset at the end of its useful life. Also called salvage value.","href":"learn/finance/f01/adjusting-entries/"},{"id":"t:retailer","kind":"term","course":"m02","lesson":"distribution-channels","front":"Retailer","back":"An intermediary that sells goods to final consumers.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:retained earning","kind":"term","course":"f01","lesson":"accounting-equation","front":"Retained earnings","back":"Cumulative net income kept in the business since it began, after dividends.","href":"learn/finance/f01/accounting-equation/"},{"id":"t:revenue","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Revenue","back":"Increases in assets, or decreases in liabilities, from delivering goods or services to customers in the business’s ordinary activities. Revenue increases equity.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:revenue recognition principle","kind":"term","course":"f01","lesson":"accrual-vs-cash","front":"Revenue recognition principle","back":"Revenue is recognised when, or as, the business satisfies a performance obligation by transferring control of a promised good or service to the customer, at the amount it expects to be entitled to (ASC 606, IFRS 15).","href":"learn/finance/f01/accrual-vs-cash/"},{"id":"t:reversal of entry","kind":"term","course":"f01","lesson":"trial-balance","front":"Reversal of entries","back":"An error in which the correct accounts and amount are used but the debit and credit are swapped.","href":"learn/finance/f01/trial-balance/"},{"id":"t:reversing entry","kind":"term","course":"f01","lesson":"accounting-cycle","front":"Reversing entry","back":"An optional entry made on the first day of a new period that is the exact opposite of an accrual adjustment made at the end of the previous period, so that the later payment or receipt can be recorded in the routine way.","href":"learn/finance/f01/accounting-cycle/"},{"id":"t:right-skewed","kind":"term","course":"b02","lesson":"skewed-data","front":"Right-skewed","back":"Having a long tail of large values; the mean is usually above the median. Also called positively skewed.","href":"learn/analytics/b02/skewed-data/"},{"id":"t:risk","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Risk","back":"In finance, the possibility that an outcome will differ from what is expected, for better or for worse.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:risk aversion","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Risk aversion","back":"Preferring a certain amount to a gamble with the same expected value. Most savers and investors are assumed to be risk averse.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:risk premium","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Risk premium","back":"The extra expected return that investors demand for bearing risk: the expected return on a risky investment minus the risk-free rate.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:risk shifting","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Risk shifting","back":"Switching to riskier projects after borrowing, which can raise the expected payoff to shareholders while lowering the expected payoff to lenders. Also called asset substitution.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:risk-free rate","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Risk-free rate","back":"The return on an investment whose payoff is certain, such as an insured short-term deposit or a short-term loan to a government that is almost sure to repay.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:roa","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"ROAS","back":"Return on ad spend: revenue attributed to a campaign ÷ the campaign’s ad spend. It ignores costs and whether the revenue was caused by the ads.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:robust scaling","kind":"term","course":"b02","lesson":"scaling","front":"Robust scaling","back":"Rescaling a variable as (x − median) ÷ interquartile range, so that extreme values have little influence on the scale.","href":"learn/analytics/b02/scaling/"},{"id":"t:robust statistic","kind":"term","course":"b02","lesson":"outliers","front":"Robust statistic","back":"A summary that a few extreme values can’t move far, such as the median, the interquartile range or the median absolute deviation.","href":"learn/analytics/b02/outliers/"},{"id":"t:row explosion","kind":"term","course":"b02","lesson":"transforming-data","front":"Row explosion","back":"The multiplication of rows in a join when a key value appears more than once in the other table. Totals computed from the joined table are inflated.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:sales promotion","kind":"term","course":"m02","lesson":"promotion-mix","front":"Sales promotion","back":"Short-term incentives to encourage buying or selling now, aimed at consumers (coupons, samples, price cuts) or at the trade (allowances, display payments).","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:scarcity","kind":"term","course":"f00","lesson":"finance-accounting-economics","front":"Scarcity","back":"The condition that resources such as time, money, labour and materials are limited relative to what people want, so every use of a resource means giving up another.","href":"learn/finance/f00/finance-accounting-economics/"},{"id":"t:sec","kind":"term","course":"f00","lesson":"market-participants","front":"SEC","back":"The Securities and Exchange Commission: the US federal agency, founded in 1934, that protects investors, keeps securities markets fair, orderly and efficient, and facilitates capital formation.","href":"learn/finance/f00/market-participants/"},{"id":"t:secondary market","kind":"term","course":"f00","lesson":"financial-markets","front":"Secondary market","back":"The market in which existing securities are resold between investors; the issuer receives none of the money.","href":"learn/finance/f00/financial-markets/"},{"id":"t:security","kind":"term","course":"f00","lesson":"financial-markets","front":"Security","back":"A financial asset that can be bought and sold, such as a share or a bond.","href":"learn/finance/f00/financial-markets/"},{"id":"t:segregation of duty","kind":"term","course":"f01","lesson":"accounting-cycle","front":"Segregation of duties","back":"An internal control that divides the authorisation, recording and custody of assets for a transaction among different people, so that no one person can both commit and conceal an error or a theft.","href":"learn/finance/f01/accounting-cycle/"},{"id":"t:selective distribution","kind":"term","course":"m02","lesson":"distribution-channels","front":"Selective distribution","back":"Placing a product in more than one but fewer than all of the outlets that would stock it, chosen for their fit with the product.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:separation of ownership and control","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Separation of ownership and control","back":"The situation in most large companies, in which the shareholders who own the company hire professional managers to run it.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:serial date","kind":"term","course":"b02","lesson":"types-and-formats","front":"Serial date","back":"A date stored as a count of days from a fixed starting point, as spreadsheets do. In Excel’s 1900 date system, 1 January 1900 is serial number 1.","href":"learn/analytics/b02/types-and-formats/"},{"id":"t:shareholder view","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Shareholder view","back":"The view that managers, as agents of the owners, should run the company to maximise its value for shareholders, within the law and ethical custom.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:shopping product","kind":"term","course":"m02","lesson":"product-decisions","front":"Shopping product","back":"A consumer product bought less often, after comparing quality, price and style across a few outlets.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:short selling","kind":"term","course":"f00","lesson":"market-participants","front":"Short selling","back":"Selling borrowed securities in the hope of buying them back later at a lower price and returning them.","href":"learn/finance/f00/market-participants/"},{"id":"t:simple interest","kind":"term","course":"f00","lesson":"interest-and-inflation","front":"Simple interest","back":"Interest calculated on the original principal only, so it is the same every period: principal × rate × time.","href":"learn/finance/f00/interest-and-inflation/"},{"id":"t:skewness","kind":"term","course":"b02","lesson":"skewed-data","front":"Skewness","back":"A measure of the asymmetry of a distribution: positive for a long right tail, negative for a long left tail, near 0 for symmetric data.","href":"learn/analytics/b02/skewed-data/"},{"id":"t:slide error","kind":"term","course":"f01","lesson":"trial-balance","front":"Slide error","back":"An error in which the decimal point is misplaced, so every digit shifts, such as $350 written as $35. When it makes the totals differ, the difference is a multiple of 9.","href":"learn/finance/f01/trial-balance/"},{"id":"t:slotting fee","kind":"term","course":"m02","lesson":"distribution-channels","front":"Slotting fee","back":"A payment from a supplier to a retailer to have a new product placed on its shelves or in its warehouse; also called a slotting allowance. Listing fees are similar charges for being stocked.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:solvency","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Solvency","back":"The ability to meet all obligations over the long run, because assets are worth more than everything owed.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:source document","kind":"term","course":"f01","lesson":"journal-entries","front":"Source document","back":"The original record of a business event, such as an invoice, receipt, bank statement, contract or payroll record, that provides the evidence for a journal entry. Also called an original source.","href":"learn/finance/f01/journal-entries/"},{"id":"t:specialty product","kind":"term","course":"m02","lesson":"product-decisions","front":"Specialty product","back":"A consumer product with unique features or a brand identity for which buyers make a special effort and compare little.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:square-root transformation","kind":"term","course":"b02","lesson":"skewed-data","front":"Square-root transformation","back":"Replacing each value x with √x; a milder correction for right skew that handles zeros.","href":"learn/analytics/b02/skewed-data/"},{"id":"t:stakeholder view","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Stakeholder view","back":"The view that a company should be run for the benefit of all who have a stake in it (customers, employees, suppliers, communities and shareholders).","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:standardisation","kind":"term","course":"b02","lesson":"scaling","front":"Standardisation","back":"Rescaling a variable as (x − mean) ÷ standard deviation, so the training data have mean 0 and standard deviation 1. The result is a z-score.","href":"learn/analytics/b02/scaling/"},{"id":"t:statement of cash flow","kind":"term","course":"f01","lesson":"financial-statements","front":"Statement of cash flows","back":"The statement of cash received and paid during a period, classified as operating, investing or financing activities, reconciling beginning to ending cash.","href":"learn/finance/f01/financial-statements/"},{"id":"t:statement of changes in equity","kind":"term","course":"f01","lesson":"financial-statements","front":"Statement of changes in equity","back":"The statement showing how each component of equity (such as common stock and retained earnings) changed during a period. Often called the statement of stockholders’ equity in the United States.","href":"learn/finance/f01/financial-statements/"},{"id":"t:statement of retained earning","kind":"term","course":"f01","lesson":"financial-statements","front":"Statement of retained earnings","back":"A simpler statement, common in introductory texts, showing beginning retained earnings plus net income minus dividends equals ending retained earnings.","href":"learn/finance/f01/financial-statements/"},{"id":"t:stock option","kind":"term","course":"f00","lesson":"governance-and-agency","front":"Stock options","back":"Rights to buy a company’s shares at a fixed price (the exercise price) during a set period; valuable to the holder only if the share price rises above that price.","href":"learn/finance/f00/governance-and-agency/"},{"id":"t:straight-line method","kind":"term","course":"f01","lesson":"adjusting-entries","front":"Straight-line method","back":"A depreciation method that charges the same amount in every full period: (cost − residual value) ÷ useful life.","href":"learn/finance/f01/adjusting-entries/"},{"id":"t:style","kind":"term","course":"m02","lesson":"product-life-cycle","front":"Style","back":"A basic and distinctive mode of expression, such as casual or formal dress, that can last for generations, going in and out of favour.","href":"learn/marketing/m02/product-life-cycle/"},{"id":"t:subsidiary ledger","kind":"term","course":"f01","lesson":"general-ledger","front":"Subsidiary ledger","back":"A separate ledger giving the detail behind one general-ledger account, such as one account for each customer or each supplier.","href":"learn/finance/f01/general-ledger/"},{"id":"t:sunk cost","kind":"term","course":"f00","lesson":"decision-principles","front":"Sunk cost","back":"Money already spent that cannot be recovered whatever is decided now. It is not an incremental cash flow and should be ignored.","href":"learn/finance/f00/decision-principles/"},{"id":"t:sunk cost fallacy","kind":"term","course":"f00","lesson":"decision-principles","front":"Sunk cost fallacy","back":"Letting money already spent influence a decision, typically by continuing a failing project so that past spending is not “wasted”.","href":"learn/finance/f00/decision-principles/"},{"id":"t:survivorship rule","kind":"term","course":"b02","lesson":"duplicates","front":"Survivorship rule","back":"The rule that decides which record in a group of duplicates is kept, or how their fields are combined: for example first, latest update, most complete or merge.","href":"learn/analytics/b02/duplicates/"},{"id":"t:systematic risk","kind":"term","course":"f00","lesson":"decision-principles","front":"Systematic risk","back":"Risk that affects nearly all investments at once, such as a recession or a change in interest rates, and cannot be removed by diversification. Also called market or non-diversifiable risk.","href":"learn/finance/f00/decision-principles/"},{"id":"t:t-account","kind":"term","course":"f01","lesson":"debits-and-credits","front":"T-account","back":"A sketch of an account shaped like a letter T, with debits to the left of the vertical line and credits to the right. Used for teaching and analysis; ledgers kept in practice use columns.","href":"learn/finance/f01/debits-and-credits/"},{"id":"t:target encoding","kind":"term","course":"b02","lesson":"encoding-categories","front":"Target encoding","back":"Replacing each category with the average value of the target variable for that category in the training data, ideally smoothed and computed out-of-fold.","href":"learn/analytics/b02/encoding-categories/"},{"id":"t:target market","kind":"term","course":"m02","lesson":"marketing-mix","front":"Target market","back":"The group of customers a business chooses to serve with a particular offer.","href":"learn/marketing/m02/marketing-mix/"},{"id":"t:target-return pricing","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Target-return pricing","back":"Setting the price that earns a chosen rate of return on the capital invested, at a forecast volume: unit cost + (target return × capital invested) ÷ forecast units.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:tax accounting","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Tax accounting","back":"The branch of accounting that applies tax law to work out a business’s taxable income and the tax it owes.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:temporary account","kind":"term","course":"f01","lesson":"accounts-and-classifications","front":"Temporary account","back":"An account that collects one period’s activity and is closed to retained earnings at the end of the period: revenue, expense and dividends accounts. Also called a nominal account.","href":"learn/finance/f01/accounts-and-classifications/"},{"id":"t:test market","kind":"term","course":"m02","lesson":"measuring-the-mix","front":"Test market","back":"Launching a product or marketing plan in a limited area to measure results before a full roll-out.","href":"learn/marketing/m02/measuring-the-mix/"},{"id":"t:test set","kind":"term","course":"b02","lesson":"scaling","front":"Test set","back":"Data held back from all fitting and used only to estimate how a model will perform on data it has not seen.","href":"learn/analytics/b02/scaling/"},{"id":"t:tidy data","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Tidy data","back":"A layout in which each variable forms a column, each observation forms a row and each type of observational unit forms a table (Wickham, 2014).","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:time period assumption","kind":"term","course":"f01","lesson":"what-is-accounting","front":"Time period assumption","back":"The assumption that a business’s life can be divided into periods, such as months, quarters and years, for which reports are prepared.","href":"learn/finance/f01/what-is-accounting/"},{"id":"t:time value of money","kind":"term","course":"f00","lesson":"finance-time-and-risk","front":"Time value of money","back":"The principle that a dollar available today is worth more than a dollar available later, because today’s dollar can earn a return in the meantime.","href":"learn/finance/f00/finance-time-and-risk/"},{"id":"t:timeliness","kind":"term","course":"b02","lesson":"profiling-and-validation","front":"Timeliness","back":"Whether data represents reality at the point in time it is needed and is up to date.","href":"learn/analytics/b02/profiling-and-validation/"},{"id":"t:trade margin","kind":"term","course":"m02","lesson":"distribution-channels","front":"Trade margin","back":"The share of the final selling price kept by the intermediaries, usually quoted as a percentage of that price.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:trade promotion","kind":"term","course":"m02","lesson":"promotion-mix","front":"Trade promotion","back":"A sales promotion aimed at intermediaries, such as funding for a retailer’s temporary price cut or a payment for a display.","href":"learn/marketing/m02/promotion-mix/"},{"id":"t:training set","kind":"term","course":"b02","lesson":"scaling","front":"Training set","back":"The part of the data used to fit a model and every data-dependent preparation step, such as scaling parameters and encodings.","href":"learn/analytics/b02/scaling/"},{"id":"t:transaction analysi","kind":"term","course":"f01","lesson":"journal-entries","front":"Transaction analysis","back":"Working out from a source document which accounts a transaction affects, whether each increases or decreases, by how much and on which side, and checking that debits equal credits.","href":"learn/finance/f01/journal-entries/"},{"id":"t:transposition error","kind":"term","course":"f01","lesson":"trial-balance","front":"Transposition error","back":"An error in which two digits of an amount are swapped, such as 1,600 written as 1,060. When it makes the totals differ, the difference is a multiple of 9.","href":"learn/finance/f01/trial-balance/"},{"id":"t:trial balance","kind":"term","course":"f01","lesson":"trial-balance","front":"Trial balance","back":"A list of every general-ledger account with a balance at a given date, each balance in its debit or credit column, with both columns totalled to check that they agree.","href":"learn/finance/f01/trial-balance/"},{"id":"t:tukey fence","kind":"term","course":"b02","lesson":"outliers","front":"Tukey fences","back":"Limits at Q1 − 1.5 × IQR and Q3 + 1.5 × IQR; values outside them are flagged as potential outliers. Outer fences use 3 × IQR.","href":"learn/analytics/b02/outliers/"},{"id":"t:type conversion","kind":"term","course":"b02","lesson":"types-and-formats","front":"Type conversion","back":"Turning a value of one data type into another, for example the text “14.50” into the number 14.5. Deliberate when the format is stated, automatic when software guesses.","href":"learn/analytics/b02/types-and-formats/"},{"id":"t:unadjusted trial balance","kind":"term","course":"f01","lesson":"trial-balance","front":"Unadjusted trial balance","back":"A trial balance prepared after the period’s transactions are posted and before the end-of-period adjusting entries.","href":"learn/finance/f01/trial-balance/"},{"id":"t:underwriting","kind":"term","course":"f00","lesson":"market-participants","front":"Underwriting","back":"Managing and selling a new issue of securities for an issuer, including setting the price and finding the buyers.","href":"learn/finance/f00/market-participants/"},{"id":"t:underwriting spread","kind":"term","course":"f00","lesson":"market-participants","front":"Underwriting spread","back":"The difference between the price investors pay for a new issue and the amount per share the issuer receives: the underwriters’ pay.","href":"learn/finance/f00/market-participants/"},{"id":"t:unearned revenue","kind":"term","course":"f01","lesson":"accounting-equation","front":"Unearned revenue","back":"Cash received for goods or services not yet delivered. It is a liability until the business delivers them.","href":"learn/finance/f01/accounting-equation/"},{"id":"t:unicode normalisation","kind":"term","course":"b02","lesson":"text-and-categories","front":"Unicode normalisation","back":"Converting text to one of the standard forms defined in Unicode Standard Annex #15 (NFC, NFD, NFKC, NFKD), so that equivalent characters are stored the same way.","href":"learn/analytics/b02/text-and-categories/"},{"id":"t:uniqueness","kind":"term","course":"b02","lesson":"profiling-and-validation","front":"Uniqueness","back":"Whether each real-world thing is recorded only once.","href":"learn/analytics/b02/profiling-and-validation/"},{"id":"t:unit of observation","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Unit of observation","back":"The kind of thing one row describes, such as an order, an order line, a booking or a student.","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:unsought product","kind":"term","course":"m02","lesson":"product-decisions","front":"Unsought product","back":"A consumer product that people don’t know about or don’t think about buying until a need arises, such as funeral plans or emergency repairs.","href":"learn/marketing/m02/product-decisions/"},{"id":"t:unsystematic risk","kind":"term","course":"f00","lesson":"decision-principles","front":"Unsystematic risk","back":"Risk specific to one company or industry, such as a product recall or a lost customer, which can be largely removed by diversification. Also called specific or diversifiable risk.","href":"learn/finance/f00/decision-principles/"},{"id":"t:useful life","kind":"term","course":"f01","lesson":"adjusting-entries","front":"Useful life","back":"The period over which a business expects to use an asset, in years or units of output.","href":"learn/finance/f01/adjusting-entries/"},{"id":"t:utc","kind":"term","course":"b02","lesson":"types-and-formats","front":"UTC","back":"Coordinated Universal Time, the reference time scale against which time zones are defined by their offsets, such as −05:00.","href":"learn/analytics/b02/types-and-formats/"},{"id":"t:validation rule","kind":"term","course":"b02","lesson":"profiling-and-validation","front":"Validation rule","back":"A precisely stated condition that a value, a row or a set of rows must satisfy, written so that a computer can test it.","href":"learn/analytics/b02/profiling-and-validation/"},{"id":"t:validity","kind":"term","course":"b02","lesson":"profiling-and-validation","front":"Validity","back":"Whether values conform to their definition: the right type, format and range, and a member of the allowed set.","href":"learn/analytics/b02/profiling-and-validation/"},{"id":"t:valuation","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"Valuation","back":"An estimate of what an asset, share or business is worth, made with stated methods and assumptions.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:valuation multiple","kind":"term","course":"f00","lesson":"value-and-valuation-words","front":"Valuation multiple","back":"A ratio of a measure of value (such as enterprise value or market capitalisation) to a measure of earnings or size (such as EBITDA or net income), used to compare companies.","href":"learn/finance/f00/value-and-valuation-words/"},{"id":"t:value proposition","kind":"term","course":"m02","lesson":"marketing-mix","front":"Value proposition","back":"The promise of benefits that gives target customers a reason to choose an offer over the alternatives.","href":"learn/marketing/m02/marketing-mix/"},{"id":"t:value-based pricing","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Value-based pricing","back":"Setting a price from the customer’s economic value: the price of the next-best alternative plus the value, positive or negative, of the differences from it.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:variable","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Variable","back":"One column of a dataset: a characteristic recorded for every observation. Also called a field or an attribute, and in machine learning a feature.","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:variable cost","kind":"term","course":"m02","lesson":"pricing-approaches","front":"Variable cost","back":"A cost incurred for each unit made or sold, so its total rises in proportion to volume: materials, packaging, per-unit fees, delivery.","href":"learn/marketing/m02/pricing-approaches/"},{"id":"t:weighted average","kind":"term","course":"b02","lesson":"transforming-data","front":"Weighted average","back":"An average in which each value counts in proportion to a weight. The mean of all rows equals the average of the group means weighted by group size.","href":"learn/analytics/b02/transforming-data/"},{"id":"t:whitespace","kind":"term","course":"b02","lesson":"text-and-categories","front":"Whitespace","back":"Characters that display as blank space, including the ordinary space, tabs, line breaks and special spaces such as the non-breaking space.","href":"learn/analytics/b02/text-and-categories/"},{"id":"t:wholesaler","kind":"term","course":"m02","lesson":"distribution-channels","front":"Wholesaler","back":"An intermediary that buys goods in bulk and resells them to retailers and other businesses rather than to consumers.","href":"learn/marketing/m02/distribution-channels/"},{"id":"t:wide format","kind":"term","course":"b02","lesson":"datasets-and-variables","front":"Wide format","back":"A layout in which the values of one variable, such as the month, are spread across several columns.","href":"learn/analytics/b02/datasets-and-variables/"},{"id":"t:winsorising","kind":"term","course":"b02","lesson":"outliers","front":"Winsorising","back":"Replacing values beyond a chosen limit, such as a fence or a percentile, with the limit itself, so that extreme values keep their rows but lose most of their pull.","href":"learn/analytics/b02/outliers/"},{"id":"t:working capital","kind":"term","course":"f00","lesson":"capital-and-liquidity","front":"Working capital","back":"Current assets minus current liabilities: the short-term cushion in a firm’s balance sheet. It is a measure, not a source of capital.","href":"learn/finance/f00/capital-and-liquidity/"},{"id":"t:worksheet","kind":"term","course":"f01","lesson":"accounting-cycle","front":"Worksheet","back":"An optional internal working paper, usually a spreadsheet, that carries each account from the trial balance through the adjustments to the income statement and balance sheet. It is not a financial statement.","href":"learn/finance/f01/accounting-cycle/"},{"id":"t:z-score","kind":"term","course":"b02","lesson":"outliers","front":"Z-score","back":"The number of standard deviations a value lies from the mean: (x − mean) ÷ s.","href":"learn/analytics/b02/outliers/"},{"id":"f:f00:future-value","kind":"formula","course":"f00","lesson":"finance-time-and-risk","front":"Future value of a single amount (annual compounding)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mrow><mi>F</mi><mi>V</mi></mrow><mo>=</mo><mrow><mi>P</mi><mi>V</mi></mrow><mtext> </mtext><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mi>n</mi></msup></mrow><annotation encoding=\"application/x-tex\">\\mathit{FV} = \\mathit{PV}\\,(1 + r)^n</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">\\mathit{FV}</annotation></semantics></math></span>","Future value: what the amount will be worth after n years ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">\\mathit{PV}</annotation></semantics></math></span>","Present value: the amount invested today ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interest rate per year, as a decimal (1.5% is 0.015) (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of years (years)"]],"href":"learn/finance/f00/finance-time-and-risk/"},{"id":"f:f00:present-value","kind":"formula","course":"f00","lesson":"finance-time-and-risk","front":"Present value of a single amount (annual discounting)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mrow><mi>P</mi><mi>V</mi></mrow><mo>=</mo><mfrac><mrow><mi>F</mi><mi>V</mi></mrow><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\"false\">)</mo><mi>n</mi></msup></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\mathit{PV} = \\dfrac{\\mathit{FV}}{(1 + r)^n}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">\\mathit{PV}</annotation></semantics></math></span>","Present value: what the future amount is worth today ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">\\mathit{FV}</annotation></semantics></math></span>","The amount to be received in the future ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Discount rate per year, as a decimal: the return available elsewhere at similar risk (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of years until the amount is received (years)"]],"href":"learn/finance/f00/finance-time-and-risk/"},{"id":"f:f00:expected-value","kind":"formula","course":"f00","lesson":"finance-time-and-risk","front":"Expected value of an uncertain outcome","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>E</mi><mo stretchy=\"false\">[</mo><mi>X</mi><mo stretchy=\"false\">]</mo><mo>=</mo><msub><mi>p</mi><mn>1</mn></msub><msub><mi>x</mi><mn>1</mn></msub><mo>+</mo><msub><mi>p</mi><mn>2</mn></msub><msub><mi>x</mi><mn>2</mn></msub><mo>+</mo><mo>⋯</mo><mo>+</mo><msub><mi>p</mi><mi>k</mi></msub><msub><mi>x</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">E[X] = p_1 x_1 + p_2 x_2 + \\cdots + p_k x_k</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E</mi><mo stretchy=\"false\">[</mo><mi>X</mi><mo stretchy=\"false\">]</mo></mrow><annotation encoding=\"application/x-tex\">E[X]</annotation></semantics></math></span>","Expected value of the uncertain outcome X (same unit as the outcomes)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">x_i</annotation></semantics></math></span>","The i-th possible outcome (e.g. $)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">p_i</annotation></semantics></math></span>","The probability of the i-th outcome; the probabilities add up to 1"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","The number of possible outcomes"]],"href":"learn/finance/f00/finance-time-and-risk/"},{"id":"f:f00:risk-premium","kind":"formula","course":"f00","lesson":"finance-time-and-risk","front":"Risk premium","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Risk premium</mtext><mo>=</mo><mi>E</mi><mo stretchy=\"false\">[</mo><mi>R</mi><mo stretchy=\"false\">]</mo><mo>−</mo><msub><mi>r</mi><mi>f</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Risk premium} = E[R] - r_f</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E</mi><mo stretchy=\"false\">[</mo><mi>R</mi><mo stretchy=\"false\">]</mo></mrow><annotation encoding=\"application/x-tex\">E[R]</annotation></semantics></math></span>","Expected return on the risky investment (% per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mi>f</mi></msub></mrow><annotation encoding=\"application/x-tex\">r_f</annotation></semantics></math></span>","Risk-free rate: the return on an investment whose payoff is certain (% per year)"]],"href":"learn/finance/f00/finance-time-and-risk/"},{"id":"f:f00:economic-profit","kind":"formula","course":"f00","lesson":"finance-accounting-economics","front":"Economic profit","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Economic profit</mtext><mo>=</mo><mtext>Accounting profit</mtext><mo>−</mo><mtext>Opportunity costs not recorded</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Economic profit} = \\text{Accounting profit} - \\text{Opportunity costs not recorded}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Accounting profit</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Accounting profit}</annotation></semantics></math></span>","Revenue minus expenses as recorded under the accounting rules (net income) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Opportunity costs not recorded</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Opportunity costs not recorded}</annotation></semantics></math></span>","The value of alternatives given up that involve no transaction, such as the owner’s forgone salary and the return her money could earn elsewhere ($)"]],"href":"learn/finance/f00/finance-accounting-economics/"},{"id":"f:f00:operating-cash-flow-simple","kind":"formula","course":"f00","lesson":"finance-accounting-economics","front":"Operating cash flow (simplified)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Operating cash flow</mtext><mo>=</mo><mtext>Accounting profit</mtext><mo>+</mo><mtext>Non-cash expenses</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Operating cash flow} = \\text{Accounting profit} + \\text{Non-cash expenses}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Accounting profit</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Accounting profit}</annotation></semantics></math></span>","Net income for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Non-cash expenses</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Non-cash expenses}</annotation></semantics></math></span>","Expenses that used no cash in the period, chiefly depreciation ($)"]],"href":"learn/finance/f00/finance-accounting-economics/"},{"id":"f:f00:incremental-cash-flow","kind":"formula","course":"f00","lesson":"decision-principles","front":"Incremental cash flow of a decision","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Incremental cash flow</mtext><mo>=</mo><msub><mrow><mi>C</mi><mi>F</mi></mrow><mtext>with</mtext></msub><mo>−</mo><msub><mrow><mi>C</mi><mi>F</mi></mrow><mtext>without</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Incremental cash flow} = \\mathit{CF}_{\\text{with}} - \\mathit{CF}_{\\text{without}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mrow><mi>C</mi><mi>F</mi></mrow><mtext>with</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\mathit{CF}_{\\text{with}}</annotation></semantics></math></span>","Cash flows of the business (or person) if the decision is taken, in a given period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mrow><mi>C</mi><mi>F</mi></mrow><mtext>without</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\mathit{CF}_{\\text{without}}</annotation></semantics></math></span>","Cash flows in the same period if it is not taken ($)"]],"href":"learn/finance/f00/decision-principles/"},{"id":"f:f00:portfolio-return","kind":"formula","course":"f00","lesson":"decision-principles","front":"Return on a portfolio of two investments","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>R</mi><mi>p</mi></msub><mo>=</mo><mi>w</mi><mtext> </mtext><msub><mi>R</mi><mi>A</mi></msub><mo>+</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><mi>w</mi><mo stretchy=\"false\">)</mo><mtext> </mtext><msub><mi>R</mi><mi>B</mi></msub></mrow><annotation encoding=\"application/x-tex\">R_p = w\\,R_A + (1 - w)\\,R_B</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R</mi><mi>p</mi></msub></mrow><annotation encoding=\"application/x-tex\">R_p</annotation></semantics></math></span>","Return on the whole portfolio (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>w</mi></mrow><annotation encoding=\"application/x-tex\">w</annotation></semantics></math></span>","Share of the money invested in A, as a decimal (the rest is in B)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R</mi><mi>A</mi></msub></mrow><annotation encoding=\"application/x-tex\">R_A</annotation></semantics></math></span>","Return on investment A (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R</mi><mi>B</mi></msub></mrow><annotation encoding=\"application/x-tex\">R_B</annotation></semantics></math></span>","Return on investment B (%)"]],"href":"learn/finance/f00/decision-principles/"},{"id":"f:f00:no-arbitrage-price","kind":"formula","course":"f00","lesson":"decision-principles","front":"No-arbitrage price of a safe future payment","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>P</mi><mo>=</mo><mfrac><mi>X</mi><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><msub><mi>r</mi><mi>f</mi></msub><msup><mo stretchy=\"false\">)</mo><mi>n</mi></msup></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">P = \\dfrac{X}{(1 + r_f)^n}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Today’s price of the promise ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>X</mi></mrow><annotation encoding=\"application/x-tex\">X</annotation></semantics></math></span>","The certain amount to be paid ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mi>f</mi></msub></mrow><annotation encoding=\"application/x-tex\">r_f</annotation></semantics></math></span>","Risk-free rate at which money can be borrowed and lent, as a decimal (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Years until payment (years)"]],"href":"learn/finance/f00/decision-principles/"},{"id":"f:f00:working-capital","kind":"formula","course":"f00","lesson":"capital-and-liquidity","front":"Working capital","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Working capital</mtext><mo>=</mo><mtext>Current assets</mtext><mo>−</mo><mtext>Current liabilities</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Working capital} = \\text{Current assets} - \\text{Current liabilities}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Current assets</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Current assets}</annotation></semantics></math></span>","Cash and assets expected to become cash or be used up within a year: receivables, inventory, prepayments ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Current liabilities</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Current liabilities}</annotation></semantics></math></span>","Obligations due within a year: amounts owed to suppliers, wages and taxes due, loan repayments due within the year ($)"]],"href":"learn/finance/f00/capital-and-liquidity/"},{"id":"f:f00:current-ratio","kind":"formula","course":"f00","lesson":"capital-and-liquidity","front":"Current ratio","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Current ratio</mtext><mo>=</mo><mfrac><mtext>Current assets</mtext><mtext>Current liabilities</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Current ratio} = \\dfrac{\\text{Current assets}}{\\text{Current liabilities}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Current assets</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Current assets}</annotation></semantics></math></span>","As above ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Current liabilities</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Current liabilities}</annotation></semantics></math></span>","As above; must be greater than zero ($)"]],"href":"learn/finance/f00/capital-and-liquidity/"},{"id":"f:f00:quick-ratio","kind":"formula","course":"f00","lesson":"capital-and-liquidity","front":"Quick (acid-test) ratio","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Quick ratio</mtext><mo>=</mo><mfrac><mrow><mtext>Cash</mtext><mo>+</mo><mtext>Short-term investments</mtext><mo>+</mo><mtext>Receivables</mtext></mrow><mtext>Current liabilities</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Quick ratio} = \\dfrac{\\text{Cash} + \\text{Short-term investments} + \\text{Receivables}}{\\text{Current liabilities}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Cash</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Cash}</annotation></semantics></math></span>","Cash and bank balances ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Short-term investments</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Short-term investments}</annotation></semantics></math></span>","Investments that can be sold quickly at close to their value ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Receivables</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Receivables}</annotation></semantics></math></span>","Amounts customers owe for goods or services already delivered ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Current liabilities</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Current liabilities}</annotation></semantics></math></span>","Obligations due within a year ($)"]],"href":"learn/finance/f00/capital-and-liquidity/"},{"id":"f:f00:debt-to-equity","kind":"formula","course":"f00","lesson":"capital-and-liquidity","front":"Debt-to-equity ratio","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Debt-to-equity</mtext><mo>=</mo><mfrac><mtext>Debt</mtext><mtext>Equity</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Debt-to-equity} = \\dfrac{\\text{Debt}}{\\text{Equity}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Debt</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Debt}</annotation></semantics></math></span>","Interest-bearing borrowing (loans and bonds); some analysts use total liabilities instead ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Equity</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Equity}</annotation></semantics></math></span>","Shareholders’ equity as recorded in the balance sheet (book value) ($)"]],"href":"learn/finance/f00/capital-and-liquidity/"},{"id":"f:f00:emergency-months","kind":"formula","course":"f00","lesson":"capital-and-liquidity","front":"Emergency-fund cover (months)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Months covered</mtext><mo>=</mo><mfrac><mtext>Liquid savings</mtext><mtext>Essential spending per month</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Months covered} = \\dfrac{\\text{Liquid savings}}{\\text{Essential spending per month}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Liquid savings</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Liquid savings}</annotation></semantics></math></span>","Money that can be reached quickly at full value, such as cash and bank deposits ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Essential spending per month</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Essential spending per month}</annotation></semantics></math></span>","Costs that cannot easily be cut: housing, food, insurance, transport, loan payments ($ per month)"]],"href":"learn/finance/f00/capital-and-liquidity/"},{"id":"f:f00:market-cap","kind":"formula","course":"f00","lesson":"value-and-valuation-words","front":"Market capitalisation","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Market cap</mtext><mo>=</mo><mi>P</mi><mo>×</mo><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">\\text{Market cap} = P \\times N</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Current share price ($ per share)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Number of shares outstanding (shares)"]],"href":"learn/finance/f00/value-and-valuation-words/"},{"id":"f:f00:enterprise-value","kind":"formula","course":"f00","lesson":"value-and-valuation-words","front":"Enterprise value","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>EV</mtext><mo>=</mo><mtext>Market cap</mtext><mo>+</mo><mtext>Debt</mtext><mo>−</mo><mtext>Cash</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EV} = \\text{Market cap} + \\text{Debt} - \\text{Cash}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Market cap</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Market cap}</annotation></semantics></math></span>","Market value of the equity ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Debt</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Debt}</annotation></semantics></math></span>","Interest-bearing debt: loans and bonds ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Cash</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Cash}</annotation></semantics></math></span>","Cash and short-term investments not needed to run the business; this course subtracts all cash ($)"]],"href":"learn/finance/f00/value-and-valuation-words/"},{"id":"f:f00:ebitda","kind":"formula","course":"f00","lesson":"value-and-valuation-words","front":"EBITDA","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>EBITDA</mtext><mo>=</mo><mtext>EBIT</mtext><mo>+</mo><mtext>D&amp;A</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EBITDA} = \\text{EBIT} + \\text{D\\&amp;A}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>EBIT</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EBIT}</annotation></semantics></math></span>","Earnings before interest and taxes: net income + interest + taxes (equal to operating profit when, as at Harbourline, there is no income or cost outside operations) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>D&amp;A</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{D\\&amp;A}</annotation></semantics></math></span>","Depreciation and amortisation for the period ($)"]],"href":"learn/finance/f00/value-and-valuation-words/"},{"id":"f:f00:ev-ebitda","kind":"formula","course":"f00","lesson":"value-and-valuation-words","front":"EV/EBITDA multiple","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>EV/EBITDA</mtext><mo>=</mo><mfrac><mtext>EV</mtext><mtext>EBITDA</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{EV/EBITDA} = \\dfrac{\\text{EV}}{\\text{EBITDA}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>EV</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EV}</annotation></semantics></math></span>","Enterprise value ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>EBITDA</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EBITDA}</annotation></semantics></math></span>","Usually the last twelve months or the next year’s forecast; must be positive to be meaningful ($)"]],"href":"learn/finance/f00/value-and-valuation-words/"},{"id":"f:f00:pe-ratio","kind":"formula","course":"f00","lesson":"value-and-valuation-words","front":"Price-to-earnings (P/E) ratio","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>P/E</mtext><mo>=</mo><mfrac><mtext>Market cap</mtext><mtext>Net income</mtext></mfrac><mo>=</mo><mfrac><mi>P</mi><mtext>EPS</mtext></mfrac><mo separator=\"true\">,</mo><mspace width=\"1em\"/><mtext>EPS</mtext><mo>=</mo><mfrac><mtext>Net income</mtext><mi>N</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{P/E} = \\dfrac{\\text{Market cap}}{\\text{Net income}} = \\dfrac{P}{\\text{EPS}}, \\quad \\text{EPS} = \\dfrac{\\text{Net income}}{N}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Share price ($ per share)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>EPS</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EPS}</annotation></semantics></math></span>","Earnings per share ($ per share)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Shares outstanding (shares)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Market cap</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Market cap}</annotation></semantics></math></span>","Share price × shares outstanding ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Net income</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Net income}</annotation></semantics></math></span>","Profit after interest and tax; must be positive for a meaningful P/E ($)"]],"href":"learn/finance/f00/value-and-valuation-words/"},{"id":"f:f00:market-to-book","kind":"formula","course":"f00","lesson":"value-and-valuation-words","front":"Market-to-book ratio","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Market-to-book</mtext><mo>=</mo><mfrac><mtext>Market cap</mtext><mtext>Book value of equity</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Market-to-book} = \\dfrac{\\text{Market cap}}{\\text{Book value of equity}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Market cap</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Market cap}</annotation></semantics></math></span>","Market value of the equity ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Book value of equity</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Book value of equity}</annotation></semantics></math></span>","Total assets minus total liabilities, as recorded ($)"]],"href":"learn/finance/f00/value-and-valuation-words/"},{"id":"f:f00:simple-interest","kind":"formula","course":"f00","lesson":"interest-and-inflation","front":"Simple interest","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>I</mi><mo>=</mo><mi>P</mi><mo>×</mo><mi>r</mi><mo>×</mo><mi>t</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>F</mi><mi>V</mi><mo>=</mo><mi>P</mi><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><mi>t</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">I = P \\times r \\times t, \\qquad FV = P(1 + rt)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">I</annotation></semantics></math></span>","Total interest earned or paid ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Principal: the amount lent or borrowed ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Annual interest rate, as a decimal (6% = 0.06) (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Time (years)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">FV</annotation></semantics></math></span>","Balance at the end, if the interest is added to it rather than paid out ($)"]],"href":"learn/finance/f00/interest-and-inflation/"},{"id":"f:f00:compound-m","kind":"formula","course":"f00","lesson":"interest-and-inflation","front":"Compound interest with m periods a year","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>F</mi><mi>V</mi><mo>=</mo><mi>P</mi><msup><mrow><mo fence=\"true\">(</mo><mn>1</mn><mo>+</mo><mfrac><mi>r</mi><mi>m</mi></mfrac><mo fence=\"true\">)</mo></mrow><mrow><mi>m</mi><mi>n</mi></mrow></msup></mrow><annotation encoding=\"application/x-tex\">FV = P\\left(1 + \\frac{r}{m}\\right)^{m n}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">FV</annotation></semantics></math></span>","Future value: the balance after n years ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Principal ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Quoted (nominal) annual rate, as a decimal (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Compounding periods per year (1 annual, 4 quarterly, 12 monthly, 365 daily)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of years (years)"]],"href":"learn/finance/f00/interest-and-inflation/"},{"id":"f:f00:ear","kind":"formula","course":"f00","lesson":"interest-and-inflation","front":"Effective annual rate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>EAR</mtext><mo>=</mo><msup><mrow><mo fence=\"true\">(</mo><mn>1</mn><mo>+</mo><mfrac><mi>r</mi><mi>m</mi></mfrac><mo fence=\"true\">)</mo></mrow><mi>m</mi></msup><mo>−</mo><mn>1</mn></mrow><annotation encoding=\"application/x-tex\">\\text{EAR} = \\left(1 + \\frac{r}{m}\\right)^{m} - 1</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>EAR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EAR}</annotation></semantics></math></span>","The equivalent rate compounded once a year (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Quoted (nominal) annual rate, such as an APR in its simple sense (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Compounding periods per year"]],"href":"learn/finance/f00/interest-and-inflation/"},{"id":"f:f00:inflation-rate","kind":"formula","course":"f00","lesson":"interest-and-inflation","front":"Inflation rate from a price index","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>i</mi><mo>=</mo><mfrac><mrow><msub><mtext>Index</mtext><mn>1</mn></msub><mo>−</mo><msub><mtext>Index</mtext><mn>0</mn></msub></mrow><msub><mtext>Index</mtext><mn>0</mn></msub></mfrac></mrow><annotation encoding=\"application/x-tex\">i = \\frac{\\text{Index}_1 - \\text{Index}_0}{\\text{Index}_0}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i</mi></mrow><annotation encoding=\"application/x-tex\">i</annotation></semantics></math></span>","Inflation rate over the period (per period)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>Index</mtext><mn>0</mn></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Index}_0</annotation></semantics></math></span>","Price index at the start (index points)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>Index</mtext><mn>1</mn></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Index}_1</annotation></semantics></math></span>","Price index at the end (index points)"]],"href":"learn/finance/f00/interest-and-inflation/"},{"id":"f:f00:purchasing-power","kind":"formula","course":"f00","lesson":"interest-and-inflation","front":"Purchasing power in today’s dollars","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Real value</mtext><mo>=</mo><mfrac><mtext>Future dollars</mtext><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>i</mi><msup><mo stretchy=\"false\">)</mo><mi>n</mi></msup></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Real value} = \\frac{\\text{Future dollars}}{(1 + i)^{n}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Future dollars</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Future dollars}</annotation></semantics></math></span>","An amount of money n years from now ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i</mi></mrow><annotation encoding=\"application/x-tex\">i</annotation></semantics></math></span>","Annual inflation rate, as a decimal (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of years (years)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Real value</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Real value}</annotation></semantics></math></span>","What that amount will buy, measured in today’s prices ($ of today)"]],"href":"learn/finance/f00/interest-and-inflation/"},{"id":"f:f00:real-return","kind":"formula","course":"f00","lesson":"interest-and-inflation","front":"Real return (Fisher relation)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>r</mi><mtext>real</mtext></msub><mo>=</mo><mfrac><mrow><mn>1</mn><mo>+</mo><msub><mi>r</mi><mtext>nom</mtext></msub></mrow><mrow><mn>1</mn><mo>+</mo><mi>i</mi></mrow></mfrac><mo>−</mo><mn>1</mn><mtext>  </mtext><mo>≈</mo><mtext>  </mtext><msub><mi>r</mi><mtext>nom</mtext></msub><mo>−</mo><mi>i</mi></mrow><annotation encoding=\"application/x-tex\">r_{\\text{real}} = \\frac{1 + r_{\\text{nom}}}{1 + i} - 1 \\;\\approx\\; r_{\\text{nom}} - i</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mtext>real</mtext></msub></mrow><annotation encoding=\"application/x-tex\">r_{\\text{real}}</annotation></semantics></math></span>","Real return: growth in purchasing power (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mtext>nom</mtext></msub></mrow><annotation encoding=\"application/x-tex\">r_{\\text{nom}}</annotation></semantics></math></span>","Nominal return: growth in dollars (use the effective annual rate) (per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i</mi></mrow><annotation encoding=\"application/x-tex\">i</annotation></semantics></math></span>","Inflation rate (per year)"]],"href":"learn/finance/f00/interest-and-inflation/"},{"id":"f:f00:interest-spread","kind":"formula","course":"f00","lesson":"financial-markets","front":"Intermediary’s interest-rate spread","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>s</mi><mo>=</mo><msub><mi>r</mi><mi>L</mi></msub><mo>−</mo><msub><mi>r</mi><mi>D</mi></msub></mrow><annotation encoding=\"application/x-tex\">s = r_L - r_D</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">s</annotation></semantics></math></span>","The spread: the gap between the lending rate and the deposit rate (percentage points)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mi>L</mi></msub></mrow><annotation encoding=\"application/x-tex\">r_L</annotation></semantics></math></span>","The rate the intermediary charges borrowers (% a year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mi>D</mi></msub></mrow><annotation encoding=\"application/x-tex\">r_D</annotation></semantics></math></span>","The rate the intermediary pays savers (% a year)"]],"href":"learn/finance/f00/financial-markets/"},{"id":"f:f00:currency-conversion","kind":"formula","course":"f00","lesson":"financial-markets","front":"Converting between currencies","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>A</mi><mi mathvariant=\"normal\">$</mi></msub><mo>=</mo><msub><mi>A</mi><mi>F</mi></msub><mo>×</mo><mi>S</mi></mrow><annotation encoding=\"application/x-tex\">A_{\\$} = A_{F} \\times S</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>A</mi><mi mathvariant=\"normal\">$</mi></msub></mrow><annotation encoding=\"application/x-tex\">A_{\\$}</annotation></semantics></math></span>","The amount in US dollars ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>A</mi><mi>F</mi></msub></mrow><annotation encoding=\"application/x-tex\">A_{F}</annotation></semantics></math></span>","The amount in the foreign currency (units of foreign currency)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S</mi></mrow><annotation encoding=\"application/x-tex\">S</annotation></semantics></math></span>","The exchange rate quoted as dollars per one unit of the foreign currency ($ per unit)"]],"href":"learn/finance/f00/financial-markets/"},{"id":"f:f00:bid-ask-spread","kind":"formula","course":"f00","lesson":"market-participants","front":"Bid-ask spread and relative spread","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Spread</mtext><mo>=</mo><msub><mi>P</mi><mtext>ask</mtext></msub><mo>−</mo><msub><mi>P</mi><mtext>bid</mtext></msub><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>Relative spread</mtext><mo>=</mo><mfrac><mrow><msub><mi>P</mi><mtext>ask</mtext></msub><mo>−</mo><msub><mi>P</mi><mtext>bid</mtext></msub></mrow><mrow><mo stretchy=\"false\">(</mo><msub><mi>P</mi><mtext>ask</mtext></msub><mo>+</mo><msub><mi>P</mi><mtext>bid</mtext></msub><mo stretchy=\"false\">)</mo><mo>÷</mo><mn>2</mn></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Spread} = P_{\\text{ask}} - P_{\\text{bid}}, \\qquad \\text{Relative spread} = \\dfrac{P_{\\text{ask}} - P_{\\text{bid}}}{(P_{\\text{ask}} + P_{\\text{bid}}) \\div 2}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P</mi><mtext>ask</mtext></msub></mrow><annotation encoding=\"application/x-tex\">P_{\\text{ask}}</annotation></semantics></math></span>","The price at which the dealer will sell to you ($ per share)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P</mi><mtext>bid</mtext></msub></mrow><annotation encoding=\"application/x-tex\">P_{\\text{bid}}</annotation></semantics></math></span>","The price at which the dealer will buy from you ($ per share)"]],"href":"learn/finance/f00/market-participants/"},{"id":"f:f00:net-proceeds","kind":"formula","course":"f00","lesson":"market-participants","front":"Net proceeds of an underwritten offering","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Net proceeds</mtext><mo>=</mo><mi>N</mi><mo>×</mo><mi>P</mi><mo>×</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><mi>g</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\text{Net proceeds} = N \\times P \\times (1 - g)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Number of new shares sold (shares)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Offer price paid by investors ($ per share)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","Underwriting spread as a fraction of the offer price"]],"href":"learn/finance/f00/market-participants/"},{"id":"f:f00:nav","kind":"formula","course":"f00","lesson":"market-participants","front":"Net asset value per fund share","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>NAV per share</mtext><mo>=</mo><mfrac><mrow><mtext>Assets</mtext><mo>−</mo><mtext>Liabilities</mtext></mrow><mi>N</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{NAV per share} = \\dfrac{\\text{Assets} - \\text{Liabilities}}{N}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Assets</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Assets}</annotation></semantics></math></span>","Market value of everything the fund owns ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Liabilities</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Liabilities}</annotation></semantics></math></span>","Everything the fund owes, such as fees due ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Number of fund shares outstanding (shares)"]],"href":"learn/finance/f00/market-participants/"},{"id":"f:f00:fdic-insured","kind":"formula","course":"f00","lesson":"market-participants","front":"FDIC-insured amount in one ownership category at one bank","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Insured</mtext><mo>=</mo><mi>min</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mi>B</mi><mo separator=\"true\">,</mo><mtext> </mtext><mn>250,000</mn><mo stretchy=\"false\">)</mo><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>Uninsured</mtext><mo>=</mo><mi>B</mi><mo>−</mo><mtext>Insured</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Insured} = \\min(B,\\ 250{,}000), \\qquad \\text{Uninsured} = B - \\text{Insured}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B</mi></mrow><annotation encoding=\"application/x-tex\">B</annotation></semantics></math></span>","The depositor’s combined deposits in that ownership category at that bank ($)"]],"href":"learn/finance/f00/market-participants/"},{"id":"f:f00:agency-costs","kind":"formula","course":"f00","lesson":"governance-and-agency","front":"Agency costs (Jensen and Meckling)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Agency costs</mtext><mo>=</mo><mi>M</mi><mo>+</mo><mi>B</mi><mo>+</mo><mi>L</mi></mrow><annotation encoding=\"application/x-tex\">\\text{Agency costs} = M + B + L</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>M</mi></mrow><annotation encoding=\"application/x-tex\">M</annotation></semantics></math></span>","Monitoring costs paid by principals (audits, boards, reporting systems) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B</mi></mrow><annotation encoding=\"application/x-tex\">B</annotation></semantics></math></span>","Bonding costs paid by agents to assure principals (detailed reports, penalty clauses) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi></mrow><annotation encoding=\"application/x-tex\">L</annotation></semantics></math></span>","Residual loss: value still lost because the agent’s decisions differ from the principal’s ideal ($)"]],"href":"learn/finance/f00/governance-and-agency/"},{"id":"f:f00:perk-split","kind":"formula","course":"f00","lesson":"governance-and-agency","front":"Who bears the cost of a perk","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>C</mi><mtext>manager</mtext></msub><mo>=</mo><mi>α</mi><mo>×</mo><mi>P</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>C</mi><mtext>others</mtext></msub><mo>=</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><mi>α</mi><mo stretchy=\"false\">)</mo><mo>×</mo><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">C_{\\text{manager}} = \\alpha \\times P, \\qquad C_{\\text{others}} = (1 - \\alpha) \\times P</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>α</mi></mrow><annotation encoding=\"application/x-tex\">\\alpha</annotation></semantics></math></span>","The fraction of the company’s shares the manager owns (between 0 and 1)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","The cost of a perk that adds nothing to the company’s value ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C</mi><mtext>manager</mtext></msub></mrow><annotation encoding=\"application/x-tex\">C_{\\text{manager}}</annotation></semantics></math></span>","The fall in the value of the manager’s own shares ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C</mi><mtext>others</mtext></msub></mrow><annotation encoding=\"application/x-tex\">C_{\\text{others}}</annotation></semantics></math></span>","The cost borne by the other shareholders ($)"]],"href":"learn/finance/f00/governance-and-agency/"},{"id":"f:f00:claims-payoff","kind":"formula","course":"f00","lesson":"governance-and-agency","front":"Payoffs to shareholders and lenders when debt is due","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Shareholders</mtext><mo>=</mo><mi>max</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mi>V</mi><mo>−</mo><mi>D</mi><mo separator=\"true\">,</mo><mtext> </mtext><mn>0</mn><mo stretchy=\"false\">)</mo><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>Lenders</mtext><mo>=</mo><mi>min</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mi>V</mi><mo separator=\"true\">,</mo><mtext> </mtext><mi>D</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\text{Shareholders} = \\max(V - D,\\ 0), \\qquad \\text{Lenders} = \\min(V,\\ D)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">V</annotation></semantics></math></span>","Value of the company’s assets when the debt falls due ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D</mi></mrow><annotation encoding=\"application/x-tex\">D</annotation></semantics></math></span>","Amount owed to lenders (principal plus interest due) ($)"]],"href":"learn/finance/f00/governance-and-agency/"},{"id":"f:f01:accounting-equation","kind":"formula","course":"f01","lesson":"accounting-equation","front":"The accounting equation","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Assets</mtext><mo>=</mo><mtext>Liabilities</mtext><mo>+</mo><mtext>Equity</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Assets} = \\text{Liabilities} + \\text{Equity}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Assets</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Assets}</annotation></semantics></math></span>","Resources the business controls that are expected to bring economic benefits ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Liabilities</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Liabilities}</annotation></semantics></math></span>","Present obligations to transfer resources to outsiders ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Equity</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Equity}</annotation></semantics></math></span>","The owners’ residual claim on the assets ($)"]],"href":"learn/finance/f01/accounting-equation/"},{"id":"f:f01:net-assets","kind":"formula","course":"f01","lesson":"accounting-equation","front":"Equity as net assets","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Equity</mtext><mo>=</mo><mtext>Assets</mtext><mo>−</mo><mtext>Liabilities</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Equity} = \\text{Assets} - \\text{Liabilities}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Equity</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Equity}</annotation></semantics></math></span>","The residual claim: what would be left for owners after every liability is settled at book amounts ($)"]],"href":"learn/finance/f01/accounting-equation/"},{"id":"f:f01:expanded-equation","kind":"formula","course":"f01","lesson":"accounting-equation","front":"The expanded accounting equation","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>A</mi><mo>=</mo><mi>L</mi><mo>+</mo><mi>C</mi><mi>S</mi><mo>+</mo><mi>R</mi><msub><mi>E</mi><mtext>beg</mtext></msub><mo>+</mo><mi>R</mi><mo>−</mo><mi>E</mi><mo>−</mo><mi>D</mi></mrow><annotation encoding=\"application/x-tex\">A = L + CS + RE_{\\text{beg}} + R - E - D</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A</mi><mo separator=\"true\">,</mo><mtext> </mtext><mi>L</mi></mrow><annotation encoding=\"application/x-tex\">A,\\ L</annotation></semantics></math></span>","Assets and liabilities at the end of the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi><mi>S</mi></mrow><annotation encoding=\"application/x-tex\">CS</annotation></semantics></math></span>","Common stock: capital contributed by owners ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><msub><mi>E</mi><mtext>beg</mtext></msub></mrow><annotation encoding=\"application/x-tex\">RE_{\\text{beg}}</annotation></semantics></math></span>","Retained earnings at the start of the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><mo separator=\"true\">,</mo><mtext> </mtext><mi>E</mi></mrow><annotation encoding=\"application/x-tex\">R,\\ E</annotation></semantics></math></span>","Revenue and expenses for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D</mi></mrow><annotation encoding=\"application/x-tex\">D</annotation></semantics></math></span>","Dividends declared in the period ($)"]],"href":"learn/finance/f01/accounting-equation/"},{"id":"f:f01:net-income","kind":"formula","course":"f01","lesson":"accounting-equation","front":"Net income","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Net income</mtext><mo>=</mo><mtext>Revenue</mtext><mo>−</mo><mtext>Expenses</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Net income} = \\text{Revenue} - \\text{Expenses}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Net income</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Net income}</annotation></semantics></math></span>","Profit for the period; negative means a net loss ($)"]],"href":"learn/finance/f01/accounting-equation/"},{"id":"f:f01:retained-earnings","kind":"formula","course":"f01","lesson":"accounting-equation","front":"Retained earnings at the end of a period","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>R</mi><msub><mi>E</mi><mtext>end</mtext></msub><mo>=</mo><mi>R</mi><msub><mi>E</mi><mtext>beg</mtext></msub><mo>+</mo><mtext>Net income</mtext><mo>−</mo><mtext>Dividends</mtext></mrow><annotation encoding=\"application/x-tex\">RE_{\\text{end}} = RE_{\\text{beg}} + \\text{Net income} - \\text{Dividends}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><msub><mi>E</mi><mtext>end</mtext></msub></mrow><annotation encoding=\"application/x-tex\">RE_{\\text{end}}</annotation></semantics></math></span>","Profit kept in the business since it began, at the end of the period ($)"]],"href":"learn/finance/f01/accounting-equation/"},{"id":"f:f01:debit-normal-balance","kind":"formula","course":"f01","lesson":"debits-and-credits","front":"Balance of an account with a normal debit balance","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Ending balance</mtext><mo>=</mo><mtext>Beginning balance</mtext><mo>+</mo><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mo>∑</mo><mtext>Debits</mtext><mo>−</mo><mo>∑</mo><mtext>Credits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\text{Ending balance} = \\text{Beginning balance} + \\textstyle\\sum \\text{Debits} - \\sum \\text{Credits}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Beginning balance</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Beginning balance}</annotation></semantics></math></span>","The balance brought forward from the previous period (zero for a new account) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mo>∑</mo><mtext>Debits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\textstyle\\sum \\text{Debits}</annotation></semantics></math></span>","Total of the amounts entered on the left side during the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mo>∑</mo><mtext>Credits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\textstyle\\sum \\text{Credits}</annotation></semantics></math></span>","Total of the amounts entered on the right side during the period ($)"]],"href":"learn/finance/f01/debits-and-credits/"},{"id":"f:f01:credit-normal-balance","kind":"formula","course":"f01","lesson":"debits-and-credits","front":"Balance of an account with a normal credit balance","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Ending balance</mtext><mo>=</mo><mtext>Beginning balance</mtext><mo>+</mo><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mo>∑</mo><mtext>Credits</mtext><mo>−</mo><mo>∑</mo><mtext>Debits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\text{Ending balance} = \\text{Beginning balance} + \\textstyle\\sum \\text{Credits} - \\sum \\text{Debits}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Beginning balance</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Beginning balance}</annotation></semantics></math></span>","The credit balance brought forward from the previous period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mo>∑</mo><mtext>Credits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\textstyle\\sum \\text{Credits}</annotation></semantics></math></span>","Total amounts entered on the right side (increases) during the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mo>∑</mo><mtext>Debits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\textstyle\\sum \\text{Debits}</annotation></semantics></math></span>","Total amounts entered on the left side (decreases) during the period ($)"]],"href":"learn/finance/f01/debits-and-credits/"},{"id":"f:f01:double-entry-rule","kind":"formula","course":"f01","lesson":"debits-and-credits","front":"The double-entry rule","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mo>∑</mo><mtext>Debits</mtext><mo>=</mo><mo>∑</mo><mtext>Credits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\textstyle\\sum \\text{Debits} = \\sum \\text{Credits}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mo>∑</mo><mtext>Debits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\textstyle\\sum \\text{Debits}</annotation></semantics></math></span>","Total of the amounts debited in an entry ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mo>∑</mo><mtext>Credits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\textstyle\\sum \\text{Credits}</annotation></semantics></math></span>","Total of the amounts credited in the same entry ($)"]],"href":"learn/finance/f01/debits-and-credits/"},{"id":"f:f01:journal-entry-balance","kind":"formula","course":"f01","lesson":"journal-entries","front":"A journal entry balances","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"false\"><msub><mo>∑</mo><mtext>lines</mtext></msub><mtext>Debits</mtext><mo>=</mo><msub><mo>∑</mo><mtext>lines</mtext></msub><mtext>Credits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\textstyle\\sum_{\\text{lines}} \\text{Debits} = \\sum_{\\text{lines}} \\text{Credits}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"false\"><msub><mo>∑</mo><mtext>lines</mtext></msub><mtext>Debits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\textstyle\\sum_{\\text{lines}} \\text{Debits}</annotation></semantics></math></span>","Total of the debit amounts on all lines of the entry ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"false\"><msub><mo>∑</mo><mtext>lines</mtext></msub><mtext>Credits</mtext></mstyle></mrow><annotation encoding=\"application/x-tex\">\\textstyle\\sum_{\\text{lines}} \\text{Credits}</annotation></semantics></math></span>","Total of the credit amounts on all lines of the entry ($)"]],"href":"learn/finance/f01/journal-entries/"},{"id":"f:f01:balance-debit-normal","kind":"formula","course":"f01","lesson":"general-ledger","front":"Balance of a debit-normal account","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Balance</mtext><mo>=</mo><mo>∑</mo><mtext>Debits</mtext><mo>−</mo><mo>∑</mo><mtext>Credits</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Balance} = \\sum \\text{Debits} - \\sum \\text{Credits}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo><mtext>Debits</mtext></mrow><annotation encoding=\"application/x-tex\">\\sum \\text{Debits}</annotation></semantics></math></span>","Total of all amounts posted to the debit side, including any opening debit balance ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo><mtext>Credits</mtext></mrow><annotation encoding=\"application/x-tex\">\\sum \\text{Credits}</annotation></semantics></math></span>","Total of all amounts posted to the credit side ($)"]],"href":"learn/finance/f01/general-ledger/"},{"id":"f:f01:balance-credit-normal","kind":"formula","course":"f01","lesson":"general-ledger","front":"Balance of a credit-normal account","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Balance</mtext><mo>=</mo><mo>∑</mo><mtext>Credits</mtext><mo>−</mo><mo>∑</mo><mtext>Debits</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Balance} = \\sum \\text{Credits} - \\sum \\text{Debits}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo><mtext>Credits</mtext></mrow><annotation encoding=\"application/x-tex\">\\sum \\text{Credits}</annotation></semantics></math></span>","Total of all amounts posted to the credit side, including any opening credit balance ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo><mtext>Debits</mtext></mrow><annotation encoding=\"application/x-tex\">\\sum \\text{Debits}</annotation></semantics></math></span>","Total of all amounts posted to the debit side ($)"]],"href":"learn/finance/f01/general-ledger/"},{"id":"f:f01:running-balance","kind":"formula","course":"f01","lesson":"general-ledger","front":"Running balance after a posting (debit-normal account)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>B</mi><mi>n</mi></msub><mo>=</mo><msub><mi>B</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msub><mo>+</mo><msub><mtext>Dr</mtext><mi>n</mi></msub><mo>−</mo><msub><mtext>Cr</mtext><mi>n</mi></msub></mrow><annotation encoding=\"application/x-tex\">B_n = B_{n-1} + \\text{Dr}_n - \\text{Cr}_n</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B</mi><mi>n</mi></msub></mrow><annotation encoding=\"application/x-tex\">B_n</annotation></semantics></math></span>","Balance after the n-th posting ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msub></mrow><annotation encoding=\"application/x-tex\">B_{n-1}</annotation></semantics></math></span>","Balance before it (zero for a new account) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>Dr</mtext><mi>n</mi></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mtext>Cr</mtext><mi>n</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Dr}_n,\\ \\text{Cr}_n</annotation></semantics></math></span>","The debit or credit posted (one of them is zero) ($)"]],"href":"learn/finance/f01/general-ledger/"},{"id":"f:f01:control-account","kind":"formula","course":"f01","lesson":"general-ledger","front":"Control account check","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Control account balance</mtext><mo>=</mo><munder><mo>∑</mo><mi>i</mi></munder><msub><mtext>Subsidiary balance</mtext><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Control account balance} = \\sum_{i} \\text{Subsidiary balance}_i</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mtext>Subsidiary balance</mtext><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Subsidiary balance}_i</annotation></semantics></math></span>","Balance of customer (or supplier) account i in the subsidiary ledger ($)"]],"href":"learn/finance/f01/general-ledger/"},{"id":"f:f01:trial-balance-check","kind":"formula","course":"f01","lesson":"trial-balance","front":"Trial balance check","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mo>∑</mo><mtext>Debit balances</mtext><mo>=</mo><mo>∑</mo><mtext>Credit balances</mtext></mrow><annotation encoding=\"application/x-tex\">\\sum \\text{Debit balances} = \\sum \\text{Credit balances}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo><mtext>Debit balances</mtext></mrow><annotation encoding=\"application/x-tex\">\\sum \\text{Debit balances}</annotation></semantics></math></span>","Total of the debit column: every account whose debits exceed its credits ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo><mtext>Credit balances</mtext></mrow><annotation encoding=\"application/x-tex\">\\sum \\text{Credit balances}</annotation></semantics></math></span>","Total of the credit column: every account whose credits exceed its debits ($)"]],"href":"learn/finance/f01/trial-balance/"},{"id":"f:f01:tb-difference","kind":"formula","course":"f01","lesson":"trial-balance","front":"Difference between the totals","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>d</mi><mo>=</mo><mrow><mo fence=\"true\">∣</mo><mtext> </mtext><mo>∑</mo><mtext>Debit balances</mtext><mo>−</mo><mo>∑</mo><mtext>Credit balances</mtext><mtext> </mtext><mo fence=\"true\">∣</mo></mrow></mrow><annotation encoding=\"application/x-tex\">d = \\left|\\, \\sum \\text{Debit balances} - \\sum \\text{Credit balances} \\,\\right|</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span>","The amount to be explained ($)"]],"href":"learn/finance/f01/trial-balance/"},{"id":"f:f01:wrong-side","kind":"formula","course":"f01","lesson":"trial-balance","front":"Amount on the wrong side","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>x</mi><mo>=</mo><mfrac><mi>d</mi><mn>2</mn></mfrac></mrow><annotation encoding=\"application/x-tex\">x = \\dfrac{d}{2}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x</mi></mrow><annotation encoding=\"application/x-tex\">x</annotation></semantics></math></span>","The amount posted to the wrong side, or the balance listed in the wrong column ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span>","Difference between the totals ($)"]],"href":"learn/finance/f01/trial-balance/"},{"id":"f:f01:transposition","kind":"formula","course":"f01","lesson":"trial-balance","front":"Difference left by swapping two neighbouring digits","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>d</mi><mo>=</mo><mn>9</mn><mtext> </mtext><mi mathvariant=\"normal\">∣</mi><mi>a</mi><mo>−</mo><mi>b</mi><mi mathvariant=\"normal\">∣</mi><mo>×</mo><msup><mn>10</mn><mi>k</mi></msup></mrow><annotation encoding=\"application/x-tex\">d = 9\\,|a - b| \\times 10^{k}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a</mi><mo separator=\"true\">,</mo><mtext> </mtext><mi>b</mi></mrow><annotation encoding=\"application/x-tex\">a,\\ b</annotation></semantics></math></span>","The two digits that were swapped"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","Place of the lower digit: 0 for units and tens, 1 for tens and hundreds, and so on"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span>","Difference the transposition leaves ($)"]],"href":"learn/finance/f01/trial-balance/"},{"id":"f:f01:slide","kind":"formula","course":"f01","lesson":"trial-balance","front":"Difference left by a slide","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>d</mi><mo>=</mo><mo stretchy=\"false\">(</mo><msup><mn>10</mn><mi>n</mi></msup><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mtext> </mtext><mi>y</mi></mrow><annotation encoding=\"application/x-tex\">d = (10^{n} - 1)\\, y</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span>","Difference the slide leaves ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y</mi></mrow><annotation encoding=\"application/x-tex\">y</annotation></semantics></math></span>","The smaller of the correct and the recorded amounts ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of places the decimal point moved"]],"href":"learn/finance/f01/trial-balance/"},{"id":"f:f01:cash-basis-profit","kind":"formula","course":"f01","lesson":"accrual-vs-cash","front":"Cash-basis profit","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Cash-basis profit</mtext><mo>=</mo><mtext>Operating receipts</mtext><mo>−</mo><mtext>Operating payments</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Cash-basis profit} = \\text{Operating receipts} - \\text{Operating payments}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Operating receipts</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Operating receipts}</annotation></semantics></math></span>","Cash received from customers in the period, whatever period the work belongs to ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Operating payments</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Operating payments}</annotation></semantics></math></span>","Cash paid in the period for running costs (wages, rent, supplies, insurance…) ($)"]],"href":"learn/finance/f01/accrual-vs-cash/"},{"id":"f:f01:accrual-net-income","kind":"formula","course":"f01","lesson":"accrual-vs-cash","front":"Accrual-basis net income","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Net income</mtext><mo>=</mo><mtext>Revenue earned</mtext><mo>−</mo><mtext>Expenses incurred</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Net income} = \\text{Revenue earned} - \\text{Expenses incurred}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Revenue earned</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Revenue earned}</annotation></semantics></math></span>","Revenue for performance obligations satisfied in the period, received or not ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Expenses incurred</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Expenses incurred}</annotation></semantics></math></span>","Resources used up and obligations incurred in the period’s operations, paid or not ($)"]],"href":"learn/finance/f01/accrual-vs-cash/"},{"id":"f:f01:cash-to-accrual","kind":"formula","course":"f01","lesson":"accrual-vs-cash","front":"From cash-basis profit to accrual net income","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>N</mi><mi>I</mi><mo>=</mo><mi>C</mi><mi>P</mi><mo>+</mo><msub><mi>A</mi><mi>R</mi></msub><mo>−</mo><msub><mi>D</mi><mi>R</mi></msub><mo>+</mo><msub><mi>D</mi><mi>E</mi></msub><mo>−</mo><msub><mi>A</mi><mi>E</mi></msub></mrow><annotation encoding=\"application/x-tex\">NI = CP + A_R - D_R + D_E - A_E</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">NI</annotation></semantics></math></span>","Accrual-basis net income for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">CP</annotation></semantics></math></span>","Cash-basis profit for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>A</mi><mi>R</mi></msub></mrow><annotation encoding=\"application/x-tex\">A_R</annotation></semantics></math></span>","Revenue earned this period but not yet received (accrued revenue, unpaid invoices) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>D</mi><mi>R</mi></msub></mrow><annotation encoding=\"application/x-tex\">D_R</annotation></semantics></math></span>","Cash received this period for revenue of later periods (unearned revenue) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>D</mi><mi>E</mi></msub></mrow><annotation encoding=\"application/x-tex\">D_E</annotation></semantics></math></span>","Cash paid this period for costs of later periods (prepayments, paid-for supplies still on hand) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>A</mi><mi>E</mi></msub></mrow><annotation encoding=\"application/x-tex\">A_E</annotation></semantics></math></span>","Expenses of this period not paid from this period’s operating cash (unpaid bills, wages and interest owed, depreciation) ($)"]],"href":"learn/finance/f01/accrual-vs-cash/"},{"id":"f:f01:straight-line","kind":"formula","course":"f01","lesson":"adjusting-entries","front":"Straight-line depreciation (per year)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Depreciation per year</mtext><mo>=</mo><mfrac><mrow><mtext>Cost</mtext><mo>−</mo><mtext>Residual value</mtext></mrow><mtext>Useful life</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Depreciation per year} = \\dfrac{\\text{Cost} - \\text{Residual value}}{\\text{Useful life}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Cost</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Cost}</annotation></semantics></math></span>","What the asset cost to buy and get ready for use ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Residual value</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Residual value}</annotation></semantics></math></span>","What the business expects to get for the asset at the end of its useful life ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Useful life</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Useful life}</annotation></semantics></math></span>","How long the business expects to use the asset (years)"]],"href":"learn/finance/f01/adjusting-entries/"},{"id":"f:f01:partial-period-depreciation","kind":"formula","course":"f01","lesson":"adjusting-entries","front":"Straight-line depreciation for part of a year","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Depreciation</mtext><mo>=</mo><mfrac><mrow><mtext>Cost</mtext><mo>−</mo><mtext>Residual value</mtext></mrow><mtext>Useful life</mtext></mfrac><mo>×</mo><mfrac><mi>m</mi><mn>12</mn></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Depreciation} = \\dfrac{\\text{Cost} - \\text{Residual value}}{\\text{Useful life}} \\times \\dfrac{m}{12}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Months the asset is in use during the period, counted by the business’s convention (months)"]],"href":"learn/finance/f01/adjusting-entries/"},{"id":"f:f01:book-value","kind":"formula","course":"f01","lesson":"adjusting-entries","front":"Book value (carrying amount)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Book value</mtext><mo>=</mo><mtext>Cost</mtext><mo>−</mo><mtext>Accumulated depreciation</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Book value} = \\text{Cost} - \\text{Accumulated depreciation}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Accumulated depreciation</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Accumulated depreciation}</annotation></semantics></math></span>","All depreciation recorded on the asset since it was bought ($)"]],"href":"learn/finance/f01/adjusting-entries/"},{"id":"f:f01:simple-interest","kind":"formula","course":"f01","lesson":"adjusting-entries","front":"Simple interest for a period","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>I</mi><mo>=</mo><mi>P</mi><mo>×</mo><mi>r</mi><mo>×</mo><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">I = P \\times r \\times t</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">I</annotation></semantics></math></span>","Interest for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Principal: the amount borrowed or lent ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Annual interest rate, as a decimal (6% = 0.06)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi></mrow><annotation encoding=\"application/x-tex\">t</annotation></semantics></math></span>","Time in years (one month = 1/12) (years)"]],"href":"learn/finance/f01/adjusting-entries/"},{"id":"f:f01:supplies-used","kind":"formula","course":"f01","lesson":"adjusting-entries","front":"Supplies used in a period","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Supplies used</mtext><mo>=</mo><mtext>Supplies at start</mtext><mo>+</mo><mtext>Purchases</mtext><mo>−</mo><mtext>Supplies on hand</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Supplies used} = \\text{Supplies at start} + \\text{Purchases} - \\text{Supplies on hand}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Supplies at start</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Supplies at start}</annotation></semantics></math></span>","Balance of the Supplies account at the start of the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Purchases</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Purchases}</annotation></semantics></math></span>","Supplies bought during the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Supplies on hand</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Supplies on hand}</annotation></semantics></math></span>","Cost of supplies counted at the end of the period ($)"]],"href":"learn/finance/f01/adjusting-entries/"},{"id":"f:f01:net-income-statement","kind":"formula","course":"f01","lesson":"financial-statements","front":"Net income (single-step income statement)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Net income</mtext><mo>=</mo><mo>∑</mo><mtext>Revenues</mtext><mo>−</mo><mo>∑</mo><mtext>Expenses</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Net income} = \\sum \\text{Revenues} - \\sum \\text{Expenses}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo></mrow><annotation encoding=\"application/x-tex\">\\sum</annotation></semantics></math></span>","The total of every account of that type in the adjusted trial balance"]],"href":"learn/finance/f01/financial-statements/"},{"id":"f:f01:ending-retained-earnings","kind":"formula","course":"f01","lesson":"financial-statements","front":"Ending retained earnings","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>R</mi><msub><mi>E</mi><mtext>end</mtext></msub><mo>=</mo><mi>R</mi><msub><mi>E</mi><mtext>beg</mtext></msub><mo>+</mo><mtext>Net income</mtext><mo>−</mo><mtext>Dividends</mtext></mrow><annotation encoding=\"application/x-tex\">RE_{\\text{end}} = RE_{\\text{beg}} + \\text{Net income} - \\text{Dividends}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><msub><mi>E</mi><mtext>beg</mtext></msub></mrow><annotation encoding=\"application/x-tex\">RE_{\\text{beg}}</annotation></semantics></math></span>","Retained earnings at the start of the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><msub><mi>E</mi><mtext>end</mtext></msub></mrow><annotation encoding=\"application/x-tex\">RE_{\\text{end}}</annotation></semantics></math></span>","Retained earnings at the end of the period, reported on the balance sheet ($)"]],"href":"learn/finance/f01/financial-statements/"},{"id":"f:f01:net-change-in-cash","kind":"formula","course":"f01","lesson":"financial-statements","front":"Net change in cash","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mtext>Cash</mtext><mo>=</mo><msub><mtext>CF</mtext><mtext>operating</mtext></msub><mo>+</mo><msub><mtext>CF</mtext><mtext>investing</mtext></msub><mo>+</mo><msub><mtext>CF</mtext><mtext>financing</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\Delta \\text{Cash} = \\text{CF}_{\\text{operating}} + \\text{CF}_{\\text{investing}} + \\text{CF}_{\\text{financing}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mtext>Cash</mtext></mrow><annotation encoding=\"application/x-tex\">\\Delta \\text{Cash}</annotation></semantics></math></span>","Ending cash minus beginning cash ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>CF</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{CF}</annotation></semantics></math></span>","Net cash flow from each kind of activity (negative when cash is used) ($)"]],"href":"learn/finance/f01/financial-statements/"},{"id":"f:f01:income-summary-balance","kind":"formula","course":"f01","lesson":"closing-entries","front":"Income Summary after closing revenue and expenses","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Income Summary balance</mtext><mo>=</mo><mo>∑</mo><mtext>Revenue</mtext><mo>−</mo><mo>∑</mo><mtext>Expenses</mtext><mo>=</mo><mtext>Net income</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Income Summary balance} = \\sum \\text{Revenue} - \\sum \\text{Expenses} = \\text{Net income}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo><mtext>Revenue</mtext></mrow><annotation encoding=\"application/x-tex\">\\sum \\text{Revenue}</annotation></semantics></math></span>","Total of the revenue account balances for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo><mtext>Expenses</mtext></mrow><annotation encoding=\"application/x-tex\">\\sum \\text{Expenses}</annotation></semantics></math></span>","Total of the expense account balances for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Net income</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Net income}</annotation></semantics></math></span>","Profit for the period; a negative result is a net loss ($)"]],"href":"learn/finance/f01/closing-entries/"},{"id":"f:f01:retained-earnings-after-closing","kind":"formula","course":"f01","lesson":"closing-entries","front":"Retained Earnings after closing","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>R</mi><msub><mi>E</mi><mtext>after</mtext></msub><mo>=</mo><mi>R</mi><msub><mi>E</mi><mtext>before</mtext></msub><mo>+</mo><mtext>Net income</mtext><mo>−</mo><mtext>Dividends</mtext></mrow><annotation encoding=\"application/x-tex\">RE_{\\text{after}} = RE_{\\text{before}} + \\text{Net income} - \\text{Dividends}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><msub><mi>E</mi><mtext>before</mtext></msub></mrow><annotation encoding=\"application/x-tex\">RE_{\\text{before}}</annotation></semantics></math></span>","Retained Earnings balance before the closing entries, which is its balance at the start of the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><msub><mi>E</mi><mtext>after</mtext></msub></mrow><annotation encoding=\"application/x-tex\">RE_{\\text{after}}</annotation></semantics></math></span>","Retained Earnings balance after the closing entries are posted ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Dividends</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Dividends}</annotation></semantics></math></span>","Dividends declared in the period ($)"]],"href":"learn/finance/f01/closing-entries/"},{"id":"f:f01:post-closing-total","kind":"formula","course":"f01","lesson":"closing-entries","front":"Post-closing trial balance and the balance sheet","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Total debits</mtext><mo>=</mo><mtext>Total assets</mtext><mo>+</mo><mtext>Contra-asset balances</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Total debits} = \\text{Total assets} + \\text{Contra-asset balances}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Total assets</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Total assets}</annotation></semantics></math></span>","Total assets on the balance sheet, after contra-assets are deducted ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Contra-asset balances</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Contra-asset balances}</annotation></semantics></math></span>","Credit balances such as accumulated depreciation, which a trial balance lists on the credit side ($)"]],"href":"learn/finance/f01/closing-entries/"},{"id":"f:f01:correcting-entry","kind":"formula","course":"f01","lesson":"accounting-cycle","front":"Correcting entry","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Correcting entry</mtext><mo>=</mo><mtext>Correct entry</mtext><mo>−</mo><mtext>Entry made</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Correcting entry} = \\text{Correct entry} - \\text{Entry made}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Correct entry</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Correct entry}</annotation></semantics></math></span>","The entry that should have been recorded ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Entry made</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Entry made}</annotation></semantics></math></span>","The entry that was actually recorded and posted ($)"]],"href":"learn/finance/f01/accounting-cycle/"},{"id":"f:f01:payroll-accrual-split","kind":"formula","course":"f01","lesson":"accounting-cycle","front":"Wages accrued at the end of a period","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Accrued wages</mtext><mo>=</mo><mtext>Pay for the pay period</mtext><mo>×</mo><mfrac><mtext>Days worked by the period end</mtext><mtext>Days in the pay period</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Accrued wages} = \\text{Pay for the pay period} \\times \\dfrac{\\text{Days worked by the period end}}{\\text{Days in the pay period}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Pay for the pay period</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Pay for the pay period}</annotation></semantics></math></span>","The total that will be paid for the whole pay period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Days worked by the period end</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Days worked by the period end}</annotation></semantics></math></span>","Days of the pay period that fall in the period being closed (days)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Days in the pay period</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Days in the pay period}</annotation></semantics></math></span>","Length of the pay period (days)"]],"href":"learn/finance/f01/accounting-cycle/"},{"id":"f:b02:mean-per-unit","kind":"formula","course":"b02","lesson":"datasets-and-variables","front":"Average per unit","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mtext>unit</mtext></msub><mo>=</mo><mfrac><mtext>Sum of the values over all rows</mtext><mtext>Number of distinct units</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\bar{x}_{\\text{unit}} = \\dfrac{\\text{Sum of the values over all rows}}{\\text{Number of distinct units}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mtext>unit</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\bar{x}_{\\text{unit}}</annotation></semantics></math></span>","The average per unit you are asking about: per order, per customer, per booking (unit of the values)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Sum of the values over all rows</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Sum of the values over all rows}</annotation></semantics></math></span>","The column total, for example of line_total (unit of the values)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Number of distinct units</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Number of distinct units}</annotation></semantics></math></span>","The number of distinct values of the unit’s identifier, such as distinct order_id (units)"]],"href":"learn/analytics/b02/datasets-and-variables/"},{"id":"f:b02:key-test","kind":"formula","course":"b02","lesson":"datasets-and-variables","front":"Primary key test","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Distinct key values</mtext><mo>=</mo><mi>n</mi><mspace width=\"1em\"/><mtext>and</mtext><mspace width=\"1em\"/><mtext>Rows with a blank key</mtext><mo>=</mo><mn>0</mn></mrow><annotation encoding=\"application/x-tex\">\\text{Distinct key values} = n \\quad \\text{and} \\quad \\text{Rows with a blank key} = 0</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of rows in the table (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Distinct key values</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Distinct key values}</annotation></semantics></math></span>","Distinct values of the candidate key, or distinct combinations for a composite key (rows)"]],"href":"learn/analytics/b02/datasets-and-variables/"},{"id":"f:b02:completeness","kind":"formula","course":"b02","lesson":"profiling-and-validation","front":"Completeness of a column","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Completeness</mtext><mo>=</mo><mfrac><mtext>Values present</mtext><mtext>Values required</mtext></mfrac><mo>×</mo><mn>100</mn><mi mathvariant=\"normal\">%</mi></mrow><annotation encoding=\"application/x-tex\">\\text{Completeness} = \\dfrac{\\text{Values present}}{\\text{Values required}} \\times 100\\%</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Values present</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Values present}</annotation></semantics></math></span>","Non-blank values on the rows that require one; placeholder codes known to mean “missing” count as blank (count)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Values required</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Values required}</annotation></semantics></math></span>","Rows on which the data dictionary requires a value (count)"]],"href":"learn/analytics/b02/profiling-and-validation/"},{"id":"f:b02:rule-failure-rate","kind":"formula","course":"b02","lesson":"profiling-and-validation","front":"Failure rate of a validation rule","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Failure rate</mtext><mo>=</mo><mfrac><mtext>Rows that fail the rule</mtext><mtext>Rows the rule checks</mtext></mfrac><mo>×</mo><mn>100</mn><mi mathvariant=\"normal\">%</mi></mrow><annotation encoding=\"application/x-tex\">\\text{Failure rate} = \\dfrac{\\text{Rows that fail the rule}}{\\text{Rows the rule checks}} \\times 100\\%</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Rows the rule checks</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Rows the rule checks}</annotation></semantics></math></span>","Rows the rule applies to; blanks in an optional column are left out (rows)"]],"href":"learn/analytics/b02/profiling-and-validation/"},{"id":"f:b02:share-failing","kind":"formula","course":"b02","lesson":"profiling-and-validation","front":"Share of rows failing at least one rule","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Share failing</mtext><mo>=</mo><mfrac><mtext>Rows failing at least one rule</mtext><mtext>Rows checked</mtext></mfrac><mo>×</mo><mn>100</mn><mi mathvariant=\"normal\">%</mi></mrow><annotation encoding=\"application/x-tex\">\\text{Share failing} = \\dfrac{\\text{Rows failing at least one rule}}{\\text{Rows checked}} \\times 100\\%</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Rows failing at least one rule</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Rows failing at least one rule}</annotation></semantics></math></span>","Each row counted once, however many rules it fails (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Rows checked</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Rows checked}</annotation></semantics></math></span>","All rows in the table (rows)"]],"href":"learn/analytics/b02/profiling-and-validation/"},{"id":"f:b02:uniqueness","kind":"formula","course":"b02","lesson":"profiling-and-validation","front":"Uniqueness of a key","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Uniqueness</mtext><mo>=</mo><mfrac><mtext>Distinct key values</mtext><mtext>Rows</mtext></mfrac><mo>×</mo><mn>100</mn><mi mathvariant=\"normal\">%</mi></mrow><annotation encoding=\"application/x-tex\">\\text{Uniqueness} = \\dfrac{\\text{Distinct key values}}{\\text{Rows}} \\times 100\\%</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Distinct key values</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Distinct key values}</annotation></semantics></math></span>","Distinct values of the primary key (count)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Rows</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Rows}</annotation></semantics></math></span>","Rows in the table (count)"]],"href":"learn/analytics/b02/profiling-and-validation/"},{"id":"f:b02:surplus-rows","kind":"formula","course":"b02","lesson":"duplicates","front":"Surplus (duplicate) rows","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Surplus rows</mtext><mo>=</mo><mi>n</mi><mo>−</mo><msub><mi>n</mi><mtext>distinct</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\text{Surplus rows} = n - n_{\\text{distinct}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of rows in the table (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mtext>distinct</mtext></msub></mrow><annotation encoding=\"application/x-tex\">n_{\\text{distinct}}</annotation></semantics></math></span>","Number of distinct values of the business key (or of whole rows, when counting exact copies) (rows)"]],"href":"learn/analytics/b02/duplicates/"},{"id":"f:b02:duplicate-rate","kind":"formula","course":"b02","lesson":"duplicates","front":"Duplicate rate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Duplicate rate</mtext><mo>=</mo><mfrac><mrow><mi>n</mi><mo>−</mo><msub><mi>n</mi><mtext>distinct</mtext></msub></mrow><mi>n</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Duplicate rate} = \\dfrac{n - n_{\\text{distinct}}}{n}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>n</mi><mtext>distinct</mtext></msub></mrow><annotation encoding=\"application/x-tex\">n,\\ n_{\\text{distinct}}</annotation></semantics></math></span>","As above (rows)"]],"href":"learn/analytics/b02/duplicates/"},{"id":"f:b02:mean-with-duplicates","kind":"formula","course":"b02","lesson":"duplicates","front":"Mean reported when duplicates are left in","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mtext>reported</mtext></msub><mo>=</mo><mfrac><mrow><mi>n</mi><mtext> </mtext><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mo>+</mo><mi>k</mi><mtext> </mtext><mover accent=\"true\"><mi>d</mi><mo>ˉ</mo></mover></mrow><mrow><mi>n</mi><mo>+</mo><mi>k</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\bar{x}_{\\text{reported}} = \\dfrac{n\\,\\bar{x} + k\\,\\bar{d}}{n + k}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of genuine records (records)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{x}</annotation></semantics></math></span>","True mean of the genuine records (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","Number of surplus duplicate rows (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>d</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{d}</annotation></semantics></math></span>","Mean of the variable in the surplus rows (units of the variable)"]],"href":"learn/analytics/b02/duplicates/"},{"id":"f:b02:levenshtein","kind":"formula","course":"b02","lesson":"duplicates","front":"Edit (Levenshtein) distance, filled in as a table","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>d</mi><mrow><mi>i</mi><mo separator=\"true\">,</mo><mi>j</mi></mrow></msub><mo>=</mo><mi>min</mi><mo>⁡</mo><mrow><mo fence=\"true\">{</mo><mtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\"><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mrow><msub><mi>d</mi><mrow><mi>i</mi><mo>−</mo><mn>1</mn><mo separator=\"true\">,</mo><mi>j</mi></mrow></msub><mo>+</mo><mn>1</mn></mrow></mstyle></mtd></mtr><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mrow><msub><mi>d</mi><mrow><mi>i</mi><mo separator=\"true\">,</mo><mi>j</mi><mo>−</mo><mn>1</mn></mrow></msub><mo>+</mo><mn>1</mn></mrow></mstyle></mtd></mtr><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mrow><msub><mi>d</mi><mrow><mi>i</mi><mo>−</mo><mn>1</mn><mo separator=\"true\">,</mo><mi>j</mi><mo>−</mo><mn>1</mn></mrow></msub><mo>+</mo><msub><mi>c</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub></mrow></mstyle></mtd></mtr></mtable></mrow><mspace width=\"2em\"/><msub><mi>d</mi><mrow><mi>i</mi><mo separator=\"true\">,</mo><mn>0</mn></mrow></msub><mo>=</mo><mi>i</mi><mo separator=\"true\">,</mo><mspace width=\"1em\"/><msub><mi>d</mi><mrow><mn>0</mn><mo separator=\"true\">,</mo><mi>j</mi></mrow></msub><mo>=</mo><mi>j</mi></mrow><annotation encoding=\"application/x-tex\">d_{i,j} = \\min\\begin{cases} d_{i-1,j} + 1 \\\\ d_{i,j-1} + 1 \\\\ d_{i-1,j-1} + c_{ij} \\end{cases} \\qquad d_{i,0} = i,\\quad d_{0,j} = j</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>d</mi><mrow><mi>i</mi><mo separator=\"true\">,</mo><mi>j</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">d_{i,j}</annotation></semantics></math></span>","Distance between the first i characters of string a and the first j characters of string b (edits)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>c</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">c_{ij}</annotation></semantics></math></span>","Substitution cost: 0 if the i-th character of a equals the j-th character of b, otherwise 1 (edits)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>d</mi><mrow><mi>i</mi><mo separator=\"true\">,</mo><mn>0</mn></mrow></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>d</mi><mrow><mn>0</mn><mo separator=\"true\">,</mo><mi>j</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">d_{i,0},\\ d_{0,j}</annotation></semantics></math></span>","Turning i (or j) characters into an empty string takes one edit per character (edits)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i</mi><mo separator=\"true\">,</mo><mtext> </mtext><mi>j</mi></mrow><annotation encoding=\"application/x-tex\">i,\\ j</annotation></semantics></math></span>","Number of characters taken from the start of a and of b (characters)"]],"href":"learn/analytics/b02/duplicates/"},{"id":"f:b02:edit-similarity","kind":"formula","course":"b02","lesson":"duplicates","front":"Normalised edit similarity","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Similarity</mtext><mo>=</mo><mn>1</mn><mo>−</mo><mfrac><mrow><mi>d</mi><mo stretchy=\"false\">(</mo><mi>a</mi><mo separator=\"true\">,</mo><mi>b</mi><mo stretchy=\"false\">)</mo></mrow><mrow><mi>max</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mi mathvariant=\"normal\">∣</mi><mi>a</mi><mi mathvariant=\"normal\">∣</mi><mo separator=\"true\">,</mo><mtext> </mtext><mi mathvariant=\"normal\">∣</mi><mi>b</mi><mi mathvariant=\"normal\">∣</mi><mo stretchy=\"false\">)</mo></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Similarity} = 1 - \\dfrac{d(a,b)}{\\max(|a|,\\,|b|)}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi><mo stretchy=\"false\">(</mo><mi>a</mi><mo separator=\"true\">,</mo><mi>b</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">d(a,b)</annotation></semantics></math></span>","Edit distance between strings a and b (edits)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">∣</mi><mi>a</mi><mi mathvariant=\"normal\">∣</mi><mo separator=\"true\">,</mo><mtext> </mtext><mi mathvariant=\"normal\">∣</mi><mi>b</mi><mi mathvariant=\"normal\">∣</mi></mrow><annotation encoding=\"application/x-tex\">|a|,\\ |b|</annotation></semantics></math></span>","Lengths of the two strings (characters)"]],"href":"learn/analytics/b02/duplicates/"},{"id":"f:b02:serial-1900","kind":"formula","course":"b02","lesson":"types-and-formats","front":"Spreadsheet serial number (1900 date system)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>S</mi><mn>1900</mn></msub><mo>=</mo><mtext>date</mtext><mo>−</mo><mtext>30 December 1899</mtext></mrow><annotation encoding=\"application/x-tex\">S_{1900} = \\text{date} - \\text{30 December 1899}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mn>1900</mn></msub></mrow><annotation encoding=\"application/x-tex\">S_{1900}</annotation></semantics></math></span>","The serial number Excel’s 1900 date system stores for the date (days)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>date</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{date}</annotation></semantics></math></span>","The calendar date, on or after 1 March 1900 (date)"]],"href":"learn/analytics/b02/types-and-formats/"},{"id":"f:b02:serial-1904","kind":"formula","course":"b02","lesson":"types-and-formats","front":"Converting between the 1904 and 1900 date systems","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>S</mi><mn>1900</mn></msub><mo>=</mo><msub><mi>S</mi><mn>1904</mn></msub><mo>+</mo><mn>1,462</mn></mrow><annotation encoding=\"application/x-tex\">S_{1900} = S_{1904} + 1{,}462</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mn>1904</mn></msub></mrow><annotation encoding=\"application/x-tex\">S_{1904}</annotation></semantics></math></span>","Serial number in the 1904 date system, which counts 1 January 1904 as day 0 (days)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1,462</mn></mrow><annotation encoding=\"application/x-tex\">1{,}462</annotation></semantics></math></span>","Days between the two starting points: four years and one leap day (days)"]],"href":"learn/analytics/b02/types-and-formats/"},{"id":"f:b02:combined-mean","kind":"formula","course":"b02","lesson":"text-and-categories","front":"Mean of a consolidated category","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mtext>category</mtext></msub><mo>=</mo><mfrac><mrow><munder><mo>∑</mo><mi>v</mi></munder><msub><mi>n</mi><mi>v</mi></msub><mtext> </mtext><msub><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mi>v</mi></msub></mrow><mrow><munder><mo>∑</mo><mi>v</mi></munder><msub><mi>n</mi><mi>v</mi></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\bar{x}_{\\text{category}} = \\dfrac{\\sum_{v} n_v\\, \\bar{x}_v}{\\sum_{v} n_v}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v</mi></mrow><annotation encoding=\"application/x-tex\">v</annotation></semantics></math></span>","Each variant that maps to the category (for example “North”, “north”, “N.”)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mi>v</mi></msub></mrow><annotation encoding=\"application/x-tex\">n_v</annotation></semantics></math></span>","Number of rows with variant v (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mi>v</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\bar{x}_v</annotation></semantics></math></span>","Mean of the variable among rows with variant v (units of the variable)"]],"href":"learn/analytics/b02/text-and-categories/"},{"id":"f:b02:vocabulary-coverage","kind":"formula","course":"b02","lesson":"text-and-categories","front":"Vocabulary coverage","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Coverage</mtext><mo>=</mo><mfrac><mtext>rows whose cleaned value is in the controlled vocabulary</mtext><mtext>all rows</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Coverage} = \\dfrac{\\text{rows whose cleaned value is in the controlled vocabulary}}{\\text{all rows}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Coverage</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Coverage}</annotation></semantics></math></span>","Share of rows the cleaning rules have placed in an allowed category (proportion (0–1))"]],"href":"learn/analytics/b02/text-and-categories/"},{"id":"f:b02:sd-after-mean-imputation","kind":"formula","course":"b02","lesson":"missing-values","front":"Standard deviation after mean imputation","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>s</mi><mtext>after</mtext></msub><mo>=</mo><mi>s</mi><msqrt><mfrac><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow><mrow><mi>n</mi><mo>+</mo><mi>m</mi><mo>−</mo><mn>1</mn></mrow></mfrac></msqrt></mrow><annotation encoding=\"application/x-tex\">s_{\\text{after}} = s\\sqrt{\\dfrac{n - 1}{n + m - 1}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">s</annotation></semantics></math></span>","Sample standard deviation of the observed values (dividing by n − 1) (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of observed values"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Number of missing values filled with the observed mean"]],"href":"learn/analytics/b02/missing-values/"},{"id":"f:b02:group-weighted-mean","kind":"formula","course":"b02","lesson":"missing-values","front":"Group-weighted mean (group-wise imputation)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mover accent=\"true\"><mi>μ</mi><mo>^</mo></mover><mo>=</mo><mfrac><mrow><munder><mo>∑</mo><mi>g</mi></munder><msub><mi>N</mi><mi>g</mi></msub><mtext> </mtext><msub><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mi>g</mi></msub></mrow><mrow><munder><mo>∑</mo><mi>g</mi></munder><msub><mi>N</mi><mi>g</mi></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\hat{\\mu} = \\dfrac{\\sum_g N_g\\,\\bar{y}_g}{\\sum_g N_g}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N</mi><mi>g</mi></msub></mrow><annotation encoding=\"application/x-tex\">N_g</annotation></semantics></math></span>","Number of rows in group g, including those with a missing value (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mi>g</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\bar{y}_g</annotation></semantics></math></span>","Mean of the observed values in group g (units of the variable)"]],"href":"learn/analytics/b02/missing-values/"},{"id":"f:b02:rubins-rules","kind":"formula","course":"b02","lesson":"missing-values","front":"Pooling multiple imputations (Rubin’s rules)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mover accent=\"true\"><mi>Q</mi><mo>ˉ</mo></mover><mo>=</mo><mfrac><mn>1</mn><mi>m</mi></mfrac><munderover><mo>∑</mo><mrow><mi>j</mi><mo>=</mo><mn>1</mn></mrow><mi>m</mi></munderover><msub><mi>Q</mi><mi>j</mi></msub><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>T</mi><mo>=</mo><mover accent=\"true\"><mi>U</mi><mo>ˉ</mo></mover><mo>+</mo><mrow><mo fence=\"true\">(</mo><mn>1</mn><mo>+</mo><mfrac><mn>1</mn><mi>m</mi></mfrac><mo fence=\"true\">)</mo></mrow><mi>B</mi></mrow><annotation encoding=\"application/x-tex\">\\bar{Q} = \\dfrac{1}{m}\\sum_{j=1}^{m} Q_j, \\qquad T = \\bar{U} + \\left(1 + \\dfrac{1}{m}\\right)B</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q</mi><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">Q_j</annotation></semantics></math></span>","The estimate (for example a mean or a coefficient) from completed dataset j (units of the estimate)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Number of completed datasets"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>U</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{U}</annotation></semantics></math></span>","Average of the squared standard errors across the m analyses (within-imputation variance) (squared units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B</mi></mrow><annotation encoding=\"application/x-tex\">B</annotation></semantics></math></span>","Sample variance of the m estimates (between-imputation variance) (squared units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T</mi></mrow><annotation encoding=\"application/x-tex\">T</annotation></semantics></math></span>","Total variance of the pooled estimate; its square root is the standard error (squared units)"]],"href":"learn/analytics/b02/missing-values/"},{"id":"f:b02:quantile-position","kind":"formula","course":"b02","lesson":"outliers","front":"Quantile by linear interpolation","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>position</mtext><mo>=</mo><mn>1</mn><mo>+</mo><mo stretchy=\"false\">(</mo><mi>n</mi><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mi>p</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>Q</mi><mi>p</mi></msub><mo>=</mo><msub><mi>x</mi><mrow><mo stretchy=\"false\">(</mo><mi>k</mi><mo stretchy=\"false\">)</mo></mrow></msub><mo>+</mo><mi>f</mi><mtext> </mtext><mo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">(</mo><msub><mi>x</mi><mrow><mo stretchy=\"false\">(</mo><mi>k</mi><mo>+</mo><mn>1</mn><mo stretchy=\"false\">)</mo></mrow></msub><mo>−</mo><msub><mi>x</mi><mrow><mo stretchy=\"false\">(</mo><mi>k</mi><mo stretchy=\"false\">)</mo></mrow></msub><mo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\text{position} = 1 + (n - 1)p, \\qquad Q_p = x_{(k)} + f\\,\\bigl(x_{(k+1)} - x_{(k)}\\bigr)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of values"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p</mi></mrow><annotation encoding=\"application/x-tex\">p</annotation></semantics></math></span>","The proportion wanted: 0.25 for Q1, 0.5 for the median, 0.75 for Q3"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mrow><mo stretchy=\"false\">(</mo><mi>k</mi><mo stretchy=\"false\">)</mo></mrow></msub></mrow><annotation encoding=\"application/x-tex\">x_{(k)}</annotation></semantics></math></span>","The k-th smallest value, where k is the whole-number part of the position (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f</mi></mrow><annotation encoding=\"application/x-tex\">f</annotation></semantics></math></span>","The fractional part of the position"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q</mi><mi>p</mi></msub></mrow><annotation encoding=\"application/x-tex\">Q_p</annotation></semantics></math></span>","The p-th quantile of the sorted values (units of the variable)"]],"href":"learn/analytics/b02/outliers/"},{"id":"f:b02:tukey-fences","kind":"formula","course":"b02","lesson":"outliers","front":"Interquartile range and Tukey fences","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>IQR</mtext><mo>=</mo><msub><mi>Q</mi><mn>3</mn></msub><mo>−</mo><msub><mi>Q</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>Q</mi><mn>1</mn></msub><mo>−</mo><mn>1.5</mn><mtext> </mtext><mtext>IQR</mtext><mo separator=\"true\">,</mo><mspace width=\"1em\"/><msub><mi>Q</mi><mn>3</mn></msub><mo>+</mo><mn>1.5</mn><mtext> </mtext><mtext>IQR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{IQR} = Q_3 - Q_1, \\qquad Q_1 - 1.5\\,\\text{IQR}, \\quad Q_3 + 1.5\\,\\text{IQR}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>Q</mi><mn>3</mn></msub></mrow><annotation encoding=\"application/x-tex\">Q_1,\\ Q_3</annotation></semantics></math></span>","First and third quartiles (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>IQR</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{IQR}</annotation></semantics></math></span>","Interquartile range: the width of the middle half of the data (units of the variable)"]],"href":"learn/analytics/b02/outliers/"},{"id":"f:b02:z-score","kind":"formula","course":"b02","lesson":"outliers","front":"Z-score","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>z</mi><mi>i</mi></msub><mo>=</mo><mfrac><mrow><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover></mrow><mi>s</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">z_i = \\dfrac{x_i - \\bar{x}}{s}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">x_i</annotation></semantics></math></span>","The value being scored (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{x}</annotation></semantics></math></span>","Mean of all values, including x_i (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">s</annotation></semantics></math></span>","Sample standard deviation (dividing by n − 1) (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>z</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">z_i</annotation></semantics></math></span>","Z-score: standard deviations x_i lies above (+) or below (−) the mean"]],"href":"learn/analytics/b02/outliers/"},{"id":"f:b02:modified-z","kind":"formula","course":"b02","lesson":"outliers","front":"Modified z-score","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>M</mi><mi>i</mi></msub><mo>=</mo><mfrac><mrow><mn>0.6745</mn><mtext> </mtext><mo stretchy=\"false\">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><mover accent=\"true\"><mi>x</mi><mo>~</mo></mover><mo stretchy=\"false\">)</mo></mrow><mtext>MAD</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">M_i = \\dfrac{0.6745\\,(x_i - \\tilde{x})}{\\text{MAD}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">x_i</annotation></semantics></math></span>","The value being scored (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>~</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\tilde{x}</annotation></semantics></math></span>","Median of the values (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>MAD</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{MAD}</annotation></semantics></math></span>","Median absolute deviation: the median of |x_i − median| (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0.6745</mn></mrow><annotation encoding=\"application/x-tex\">0.6745</annotation></semantics></math></span>","Makes M comparable with a z-score for normal data"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>M</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">M_i</annotation></semantics></math></span>","Modified z-score: distance from the median in robust standard-deviation units"]],"href":"learn/analytics/b02/outliers/"},{"id":"f:b02:skewness-g1","kind":"formula","course":"b02","lesson":"skewed-data","front":"Sample skewness (adjusted Fisher–Pearson coefficient)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>G</mi><mn>1</mn></msub><mo>=</mo><mfrac><msqrt><mrow><mi>n</mi><mo stretchy=\"false\">(</mo><mi>n</mi><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo></mrow></msqrt><mrow><mi>n</mi><mo>−</mo><mn>2</mn></mrow></mfrac><mo>⋅</mo><mfrac><msub><mi>m</mi><mn>3</mn></msub><msubsup><mi>m</mi><mn>2</mn><mrow><mn>3</mn><mi mathvariant=\"normal\">/</mi><mn>2</mn></mrow></msubsup></mfrac></mrow><annotation encoding=\"application/x-tex\">G_1 = \\dfrac{\\sqrt{n(n-1)}}{n-2}\\cdot\\dfrac{m_3}{m_2^{3/2}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>G</mi><mn>1</mn></msub></mrow><annotation encoding=\"application/x-tex\">G_1</annotation></semantics></math></span>","Sample skewness: positive for a long right tail, negative for a long left tail"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of values (at least 3)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>m</mi><mn>2</mn></msub></mrow><annotation encoding=\"application/x-tex\">m_2</annotation></semantics></math></span>","Mean squared deviation from the mean, dividing by n (squared units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>m</mi><mn>3</mn></msub></mrow><annotation encoding=\"application/x-tex\">m_3</annotation></semantics></math></span>","Mean cubed deviation from the mean, dividing by n (cubed units)"]],"href":"learn/analytics/b02/skewed-data/"},{"id":"f:b02:log-transforms","kind":"formula","course":"b02","lesson":"skewed-data","front":"Log and log(1 + x) transformations","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>y</mi><mo>=</mo><mi>ln</mi><mo>⁡</mo><mi>x</mi><mspace width=\"1em\"/><mo stretchy=\"false\">(</mo><mi>x</mi><mo>&gt;</mo><mn>0</mn><mo stretchy=\"false\">)</mo><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>y</mi><mo>=</mo><mi>ln</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>x</mi><mo stretchy=\"false\">)</mo><mspace width=\"1em\"/><mo stretchy=\"false\">(</mo><mi>x</mi><mo>&gt;</mo><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">y = \\ln x \\quad (x &gt; 0), \\qquad y = \\ln(1 + x) \\quad (x &gt; -1)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x</mi></mrow><annotation encoding=\"application/x-tex\">x</annotation></semantics></math></span>","The original value (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y</mi></mrow><annotation encoding=\"application/x-tex\">y</annotation></semantics></math></span>","The transformed value (log units)"]],"href":"learn/analytics/b02/skewed-data/"},{"id":"f:b02:box-cox","kind":"formula","course":"b02","lesson":"skewed-data","front":"Box–Cox transformation","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msup><mi>x</mi><mrow><mo stretchy=\"false\">(</mo><mi>λ</mi><mo stretchy=\"false\">)</mo></mrow></msup><mo>=</mo><mfrac><mrow><msup><mi>x</mi><mi>λ</mi></msup><mo>−</mo><mn>1</mn></mrow><mi>λ</mi></mfrac><mtext> </mtext><mo stretchy=\"false\">(</mo><mi>λ</mi><mo mathvariant=\"normal\">≠</mo><mn>0</mn><mo stretchy=\"false\">)</mo><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msup><mi>x</mi><mrow><mo stretchy=\"false\">(</mo><mn>0</mn><mo stretchy=\"false\">)</mo></mrow></msup><mo>=</mo><mi>ln</mi><mo>⁡</mo><mi>x</mi></mrow><annotation encoding=\"application/x-tex\">x^{(\\lambda)} = \\dfrac{x^{\\lambda} - 1}{\\lambda}\\ (\\lambda \\neq 0), \\qquad x^{(0)} = \\ln x</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x</mi></mrow><annotation encoding=\"application/x-tex\">x</annotation></semantics></math></span>","The original value, strictly positive (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi></mrow><annotation encoding=\"application/x-tex\">\\lambda</annotation></semantics></math></span>","The power, estimated from the (training) data"]],"href":"learn/analytics/b02/skewed-data/"},{"id":"f:b02:geometric-mean","kind":"formula","course":"b02","lesson":"skewed-data","front":"Geometric mean","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>GM</mtext><mo>=</mo><msup><mrow><mo fence=\"true\">(</mo><munderover><mo>∏</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><msub><mi>x</mi><mi>i</mi></msub><mo fence=\"true\">)</mo></mrow><mrow><mn>1</mn><mi mathvariant=\"normal\">/</mi><mi>n</mi></mrow></msup><mo>=</mo><mi>exp</mi><mo>⁡</mo><mtext> ⁣</mtext><mrow><mo fence=\"true\">(</mo><mfrac><mn>1</mn><mi>n</mi></mfrac><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><mi>ln</mi><mo>⁡</mo><msub><mi>x</mi><mi>i</mi></msub><mo fence=\"true\">)</mo></mrow></mrow><annotation encoding=\"application/x-tex\">\\text{GM} = \\left(\\prod_{i=1}^{n} x_i\\right)^{1/n} = \\exp\\!\\left(\\dfrac{1}{n}\\sum_{i=1}^{n}\\ln x_i\\right)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">x_i</annotation></semantics></math></span>","Positive values (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>GM</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{GM}</annotation></semantics></math></span>","Geometric mean: the back-transformed mean of the logs (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of values"]],"href":"learn/analytics/b02/skewed-data/"},{"id":"f:b02:log-difference","kind":"formula","course":"b02","lesson":"skewed-data","front":"Log difference and percentage change","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>d</mi><mo>=</mo><mi>ln</mi><mo>⁡</mo><mfrac><msub><mi>x</mi><mtext>new</mtext></msub><msub><mi>x</mi><mtext>old</mtext></msub></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mtext>percentage change</mtext><mo>=</mo><mo stretchy=\"false\">(</mo><msup><mi>e</mi><mi>d</mi></msup><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mo>×</mo><mn>100</mn><mi mathvariant=\"normal\">%</mi></mrow><annotation encoding=\"application/x-tex\">d = \\ln\\dfrac{x_{\\text{new}}}{x_{\\text{old}}}, \\qquad \\text{percentage change} = (e^{d} - 1) \\times 100\\%</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mtext>new</mtext></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>x</mi><mtext>old</mtext></msub></mrow><annotation encoding=\"application/x-tex\">x_{\\text{new}},\\ x_{\\text{old}}</annotation></semantics></math></span>","The new and old values (units of the variable)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span>","Difference between the logs of the new and old values (log units)"]],"href":"learn/analytics/b02/skewed-data/"},{"id":"f:b02:euclidean-distance","kind":"formula","course":"b02","lesson":"scaling","front":"Euclidean distance between two observations","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>d</mi><mo stretchy=\"false\">(</mo><mi mathvariant=\"bold\">p</mi><mo separator=\"true\">,</mo><mi mathvariant=\"bold\">q</mi><mo stretchy=\"false\">)</mo><mo>=</mo><msqrt><mrow><munderover><mo>∑</mo><mrow><mi>j</mi><mo>=</mo><mn>1</mn></mrow><mi>k</mi></munderover><mo stretchy=\"false\">(</mo><msub><mi>p</mi><mi>j</mi></msub><mo>−</mo><msub><mi>q</mi><mi>j</mi></msub><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup></mrow></msqrt></mrow><annotation encoding=\"application/x-tex\">d(\\mathbf{p}, \\mathbf{q}) = \\sqrt{\\sum_{j=1}^{k} (p_j - q_j)^2}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi><mo stretchy=\"false\">(</mo><mi mathvariant=\"bold\">p</mi><mo separator=\"true\">,</mo><mi mathvariant=\"bold\">q</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">d(\\mathbf{p}, \\mathbf{q})</annotation></semantics></math></span>","Straight-line distance between observations p and q"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p</mi><mi>j</mi></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>q</mi><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">p_j,\\ q_j</annotation></semantics></math></span>","The two observations’ values on variable j (units of variable j)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","The number of variables"]],"href":"learn/analytics/b02/scaling/"},{"id":"f:b02:min-max","kind":"formula","course":"b02","lesson":"scaling","front":"Min–max normalisation","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msup><mi>x</mi><mo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′</mo></msup><mo>=</mo><mfrac><mrow><mi>x</mi><mo>−</mo><msub><mi>x</mi><mi>min</mi><mo>⁡</mo></msub></mrow><mrow><msub><mi>x</mi><mi>max</mi><mo>⁡</mo></msub><mo>−</mo><msub><mi>x</mi><mi>min</mi><mo>⁡</mo></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">x&#x27; = \\dfrac{x - x_{\\min}}{x_{\\max} - x_{\\min}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x</mi></mrow><annotation encoding=\"application/x-tex\">x</annotation></semantics></math></span>","The value to scale (original units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>min</mi><mo>⁡</mo></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>x</mi><mi>max</mi><mo>⁡</mo></msub></mrow><annotation encoding=\"application/x-tex\">x_{\\min},\\ x_{\\max}</annotation></semantics></math></span>","Smallest and largest values in the training data (original units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>x</mi><mo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′</mo></msup></mrow><annotation encoding=\"application/x-tex\">x&#x27;</annotation></semantics></math></span>","The scaled value: 0 at the training minimum, 1 at the training maximum"]],"href":"learn/analytics/b02/scaling/"},{"id":"f:b02:standardise","kind":"formula","course":"b02","lesson":"scaling","front":"Standardisation (z-score)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>z</mi><mo>=</mo><mfrac><mrow><mi>x</mi><mo>−</mo><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover></mrow><mi>s</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">z = \\dfrac{x - \\bar{x}}{s}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{x}</annotation></semantics></math></span>","Mean of the training data (original units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">s</annotation></semantics></math></span>","Standard deviation of the training data (sample formula, n − 1, in this course) (original units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>z</mi></mrow><annotation encoding=\"application/x-tex\">z</annotation></semantics></math></span>","Standard deviations above (+) or below (−) the training mean"]],"href":"learn/analytics/b02/scaling/"},{"id":"f:b02:robust-scale","kind":"formula","course":"b02","lesson":"scaling","front":"Robust scaling","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>r</mi><mo>=</mo><mfrac><mrow><mi>x</mi><mo>−</mo><mover accent=\"true\"><mi>x</mi><mo>~</mo></mover></mrow><mrow><msub><mi>Q</mi><mn>3</mn></msub><mo>−</mo><msub><mi>Q</mi><mn>1</mn></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">r = \\dfrac{x - \\tilde{x}}{Q_3 - Q_1}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>~</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\tilde{x}</annotation></semantics></math></span>","Median of the training data (original units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>Q</mi><mn>3</mn></msub></mrow><annotation encoding=\"application/x-tex\">Q_1,\\ Q_3</annotation></semantics></math></span>","First and third quartiles of the training data (linear interpolation in this course) (original units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Interquartile ranges above (+) or below (−) the training median"]],"href":"learn/analytics/b02/scaling/"},{"id":"f:b02:inverse-scaling","kind":"formula","course":"b02","lesson":"scaling","front":"Converting scaled values back","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>x</mi><mo>=</mo><msub><mi>x</mi><mi>min</mi><mo>⁡</mo></msub><mo>+</mo><msup><mi>x</mi><mo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′</mo></msup><mo stretchy=\"false\">(</mo><msub><mi>x</mi><mi>max</mi><mo>⁡</mo></msub><mo>−</mo><msub><mi>x</mi><mi>min</mi><mo>⁡</mo></msub><mo stretchy=\"false\">)</mo><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>x</mi><mo>=</mo><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mo>+</mo><mi>z</mi><mtext> </mtext><mi>s</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>x</mi><mo>=</mo><mover accent=\"true\"><mi>x</mi><mo>~</mo></mover><mo>+</mo><mi>r</mi><mtext> </mtext><mo stretchy=\"false\">(</mo><msub><mi>Q</mi><mn>3</mn></msub><mo>−</mo><msub><mi>Q</mi><mn>1</mn></msub><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">x = x_{\\min} + x&#x27;(x_{\\max} - x_{\\min}), \\qquad x = \\bar{x} + z\\,s, \\qquad x = \\tilde{x} + r\\,(Q_3 - Q_1)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x</mi></mrow><annotation encoding=\"application/x-tex\">x</annotation></semantics></math></span>","The value in the original units (original units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>x</mi><mo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′</mo></msup><mo separator=\"true\">,</mo><mtext> </mtext><mi>z</mi><mo separator=\"true\">,</mo><mtext> </mtext><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">x&#x27;,\\ z,\\ r</annotation></semantics></math></span>","A min–max, standardised or robust-scaled value, with the parameters it was fitted with"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>min</mi><mo>⁡</mo></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>x</mi><mi>max</mi><mo>⁡</mo></msub></mrow><annotation encoding=\"application/x-tex\">x_{\\min},\\ x_{\\max}</annotation></semantics></math></span>","Training minimum and maximum (min–max) (original units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mo separator=\"true\">,</mo><mtext> </mtext><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">\\bar{x},\\ s</annotation></semantics></math></span>","Training mean and standard deviation (standardisation) (original units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>~</mo></mover><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>Q</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>Q</mi><mn>3</mn></msub></mrow><annotation encoding=\"application/x-tex\">\\tilde{x},\\ Q_1,\\ Q_3</annotation></semantics></math></span>","Training median and first and third quartiles (robust scaling) (original units)"]],"href":"learn/analytics/b02/scaling/"},{"id":"f:b02:coef-per-unit","kind":"formula","course":"b02","lesson":"scaling","front":"Coefficient per original unit from a standardised coefficient","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>b</mi><mi>j</mi></msub><mo>=</mo><mfrac><msubsup><mi>b</mi><mi>j</mi><mrow><mo stretchy=\"false\">(</mo><mi>z</mi><mo stretchy=\"false\">)</mo></mrow></msubsup><msub><mi>s</mi><mi>j</mi></msub></mfrac></mrow><annotation encoding=\"application/x-tex\">b_j = \\dfrac{b_j^{(z)}}{s_j}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>b</mi><mi>j</mi><mrow><mo stretchy=\"false\">(</mo><mi>z</mi><mo stretchy=\"false\">)</mo></mrow></msubsup></mrow><annotation encoding=\"application/x-tex\">b_j^{(z)}</annotation></semantics></math></span>","Coefficient on the standardised predictor j: change in the prediction per standard deviation of the predictor (units of y)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>s</mi><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">s_j</annotation></semantics></math></span>","Standard deviation of predictor j used for the scaling (units of predictor j)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>b</mi><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">b_j</annotation></semantics></math></span>","Change in the prediction per one-unit increase in predictor j (units of y per unit of predictor j)"]],"href":"learn/analytics/b02/scaling/"},{"id":"f:b02:encoded-columns","kind":"formula","course":"b02","lesson":"encoding-categories","front":"Columns created by one-hot and dummy coding","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>p</mi><mtext>one-hot</mtext></msub><mo>=</mo><munder><mo>∑</mo><mi>j</mi></munder><msub><mi>k</mi><mi>j</mi></msub><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>p</mi><mtext>dummy</mtext></msub><mo>=</mo><munder><mo>∑</mo><mi>j</mi></munder><mo stretchy=\"false\">(</mo><msub><mi>k</mi><mi>j</mi></msub><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">p_{\\text{one-hot}} = \\sum_{j} k_j, \\qquad p_{\\text{dummy}} = \\sum_{j} (k_j - 1)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>k</mi><mi>j</mi></msub></mrow><annotation encoding=\"application/x-tex\">k_j</annotation></semantics></math></span>","Number of categories of categorical variable j (after cleaning) (categories)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p</mi></mrow><annotation encoding=\"application/x-tex\">p</annotation></semantics></math></span>","Number of columns the encoded variables occupy (columns)"]],"href":"learn/analytics/b02/encoding-categories/"},{"id":"f:b02:dummy-coefficients","kind":"formula","course":"b02","lesson":"encoding-categories","front":"Dummy coefficients with one categorical predictor","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mover accent=\"true\"><mi>y</mi><mo>^</mo></mover><mo>=</mo><msub><mi>b</mi><mn>0</mn></msub><mo>+</mo><munder><mo>∑</mo><mrow><mi>c</mi><mo mathvariant=\"normal\">≠</mo><mtext>ref</mtext></mrow></munder><msub><mi>b</mi><mi>c</mi></msub><msub><mi>D</mi><mi>c</mi></msub><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>b</mi><mn>0</mn></msub><mo>=</mo><msub><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mtext>ref</mtext></msub><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>b</mi><mi>c</mi></msub><mo>=</mo><msub><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mi>c</mi></msub><mo>−</mo><msub><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mtext>ref</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\hat{y} = b_0 + \\sum_{c \\neq \\text{ref}} b_c D_c, \\qquad b_0 = \\bar{y}_{\\text{ref}}, \\qquad b_c = \\bar{y}_c - \\bar{y}_{\\text{ref}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>D</mi><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">D_c</annotation></semantics></math></span>","Dummy variable: 1 if the row is in category c, 0 otherwise"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mtext>ref</mtext></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\bar{y}_{\\text{ref}},\\ \\bar{y}_c</annotation></semantics></math></span>","Mean of the target in the reference category and in category c (units of y)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>b</mi><mn>0</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>b</mi><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">b_0,\\ b_c</annotation></semantics></math></span>","Intercept and the coefficient of category c (units of y)"]],"href":"learn/analytics/b02/encoding-categories/"},{"id":"f:b02:frequency-encoding","kind":"formula","course":"b02","lesson":"encoding-categories","front":"Frequency encoding","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>f</mi><mi>c</mi></msub><mo>=</mo><mfrac><msub><mi>n</mi><mi>c</mi></msub><mi>n</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">f_c = \\dfrac{n_c}{n}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">n_c</annotation></semantics></math></span>","Training rows in category c (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","All training rows (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>f</mi><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">f_c</annotation></semantics></math></span>","Frequency encoding of category c: its share of the training rows"]],"href":"learn/analytics/b02/encoding-categories/"},{"id":"f:b02:target-encoding","kind":"formula","course":"b02","lesson":"encoding-categories","front":"Target encoding (category mean)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mi>c</mi></msub><mo>=</mo><mfrac><mn>1</mn><msub><mi>n</mi><mi>c</mi></msub></mfrac><munder><mo>∑</mo><mrow><mi>i</mi><mo>∈</mo><mi>c</mi></mrow></munder><msub><mi>y</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\bar{y}_c = \\dfrac{1}{n_c}\\sum_{i \\in c} y_i</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>y</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">y_i</annotation></semantics></math></span>","Target value of training row i (1 or 0 for a yes/no target) (units of y)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">n_c</annotation></semantics></math></span>","Training rows in category c (rows)"]],"href":"learn/analytics/b02/encoding-categories/"},{"id":"f:b02:smoothed-target-encoding","kind":"formula","course":"b02","lesson":"encoding-categories","front":"Smoothed target encoding","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>S</mi><mi>c</mi></msub><mo>=</mo><msub><mi>λ</mi><mi>c</mi></msub><mtext> </mtext><msub><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mi>c</mi></msub><mo>+</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><msub><mi>λ</mi><mi>c</mi></msub><mo stretchy=\"false\">)</mo><mtext> </mtext><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>λ</mi><mi>c</mi></msub><mo>=</mo><mfrac><msub><mi>n</mi><mi>c</mi></msub><mrow><msub><mi>n</mi><mi>c</mi></msub><mo>+</mo><mi>m</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">S_c = \\lambda_c\\,\\bar{y}_c + (1 - \\lambda_c)\\,\\bar{y}, \\qquad \\lambda_c = \\dfrac{n_c}{n_c + m}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">S_c</annotation></semantics></math></span>","Smoothed target encoding of category c (units of y)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\bar{y}_c</annotation></semantics></math></span>","Mean of the target in category c (units of y)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">n_c</annotation></semantics></math></span>","Training rows in category c (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>y</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{y}</annotation></semantics></math></span>","Overall mean of the target in the training data (units of y)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>λ</mi><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\lambda_c</annotation></semantics></math></span>","Weight on the category’s own mean, between 0 and 1"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Smoothing strength: the larger it is, the more small categories are pulled towards the overall mean (rows)"]],"href":"learn/analytics/b02/encoding-categories/"},{"id":"f:b02:derived-order-total","kind":"formula","course":"b02","lesson":"transforming-data","front":"Expected order total","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>expected total</mtext><mo>=</mo><mi>q</mi><mo>×</mo><mi>p</mi><mo>−</mo><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">\\text{expected total} = q \\times p - d</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q</mi></mrow><annotation encoding=\"application/x-tex\">q</annotation></semantics></math></span>","Quantity: number of packs ordered (packs)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p</mi></mrow><annotation encoding=\"application/x-tex\">p</annotation></semantics></math></span>","Unit price of one pack ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span>","Discount on the whole order ($)"]],"href":"learn/analytics/b02/transforming-data/"},{"id":"f:b02:nights-between-dates","kind":"formula","course":"b02","lesson":"transforming-data","front":"Nights between two dates","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>nights</mtext><mo>=</mo><mtext>check-out date</mtext><mo>−</mo><mtext>check-in date</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{nights} = \\text{check-out date} - \\text{check-in date}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>check-in date</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{check-in date}</annotation></semantics></math></span>","Date of arrival, stored as a true date (date)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>check-out date</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{check-out date}</annotation></semantics></math></span>","Date of departure, stored as a true date (date)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>nights</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{nights}</annotation></semantics></math></span>","Number of nights stayed; the check-out day is not counted (nights)"]],"href":"learn/analytics/b02/transforming-data/"},{"id":"f:b02:equal-width-bins","kind":"formula","course":"b02","lesson":"transforming-data","front":"Width of equal-width bins","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>w</mi><mo>=</mo><mfrac><mrow><msub><mi>x</mi><mi>max</mi><mo>⁡</mo></msub><mo>−</mo><msub><mi>x</mi><mi>min</mi><mo>⁡</mo></msub></mrow><mi>k</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">w = \\dfrac{x_{\\max} - x_{\\min}}{k}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>w</mi></mrow><annotation encoding=\"application/x-tex\">w</annotation></semantics></math></span>","Width of every bin (same unit as x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>max</mi><mo>⁡</mo></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>x</mi><mi>min</mi><mo>⁡</mo></msub></mrow><annotation encoding=\"application/x-tex\">x_{\\max},\\ x_{\\min}</annotation></semantics></math></span>","Largest and smallest value (same unit as x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","Number of bins"]],"href":"learn/analytics/b02/transforming-data/"},{"id":"f:b02:mean-from-group-means","kind":"formula","course":"b02","lesson":"transforming-data","front":"Overall mean from group means","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mo>=</mo><mfrac><mrow><munder><mo>∑</mo><mi>g</mi></munder><msub><mi>n</mi><mi>g</mi></msub><mtext> </mtext><msub><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mi>g</mi></msub></mrow><mrow><munder><mo>∑</mo><mi>g</mi></munder><msub><mi>n</mi><mi>g</mi></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\bar{x} = \\dfrac{\\sum_g n_g\\,\\bar{x}_g}{\\sum_g n_g}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover><mi>g</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\bar{x}_g</annotation></semantics></math></span>","Mean of group g (unit of x)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mi>g</mi></msub></mrow><annotation encoding=\"application/x-tex\">n_g</annotation></semantics></math></span>","Number of rows in group g (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>x</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{x}</annotation></semantics></math></span>","Mean of all the rows (unit of x)"]],"href":"learn/analytics/b02/transforming-data/"},{"id":"f:b02:join-row-count","kind":"formula","course":"b02","lesson":"transforming-data","front":"Rows produced by inner and left joins","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>N</mi><mtext>inner</mtext></msub><mo>=</mo><munder><mo>∑</mo><mi>k</mi></munder><msub><mi>a</mi><mi>k</mi></msub><mtext> </mtext><msub><mi>b</mi><mi>k</mi></msub><mspace width=\"2em\"/><msub><mi>N</mi><mtext>left</mtext></msub><mo>=</mo><munder><mo>∑</mo><mi>k</mi></munder><msub><mi>a</mi><mi>k</mi></msub><mi>max</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><msub><mi>b</mi><mi>k</mi></msub><mo separator=\"true\">,</mo><mtext> </mtext><mn>1</mn><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">N_{\\text{inner}} = \\sum_k a_k\\, b_k \\qquad N_{\\text{left}} = \\sum_k a_k \\max(b_k,\\, 1)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>a</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">a_k</annotation></semantics></math></span>","Rows with key value k in the left table (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>b</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">b_k</annotation></semantics></math></span>","Rows with key value k in the right table (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Rows in the joined table (rows)"]],"href":"learn/analytics/b02/transforming-data/"},{"id":"f:b02:full-join-row-count","kind":"formula","course":"b02","lesson":"transforming-data","front":"Rows produced by a full outer join","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>N</mi><mtext>full</mtext></msub><mo>=</mo><msub><mi>N</mi><mtext>inner</mtext></msub><mo>+</mo><msub><mi>U</mi><mi>L</mi></msub><mo>+</mo><msub><mi>U</mi><mi>R</mi></msub></mrow><annotation encoding=\"application/x-tex\">N_{\\text{full}} = N_{\\text{inner}} + U_L + U_R</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N</mi><mtext>full</mtext></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>N</mi><mtext>inner</mtext></msub></mrow><annotation encoding=\"application/x-tex\">N_{\\text{full}},\\ N_{\\text{inner}}</annotation></semantics></math></span>","Rows in the full outer join and in the inner join (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>U</mi><mi>L</mi></msub></mrow><annotation encoding=\"application/x-tex\">U_L</annotation></semantics></math></span>","Left rows whose key has no match in the right table (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>U</mi><mi>R</mi></msub></mrow><annotation encoding=\"application/x-tex\">U_R</annotation></semantics></math></span>","Right rows whose key has no match in the left table (rows)"]],"href":"learn/analytics/b02/transforming-data/"},{"id":"f:b02:missing-share","kind":"formula","course":"b02","lesson":"data-quality-report","front":"Share of values missing in a column","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>missing %</mtext><mo>=</mo><mfrac><mi>m</mi><mi>n</mi></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">\\text{missing \\%} = \\dfrac{m}{n} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Missing values in the column (values)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Rows in the table at the time of the profile (rows)"]],"href":"learn/analytics/b02/data-quality-report/"},{"id":"f:b02:rows-retained","kind":"formula","course":"b02","lesson":"data-quality-report","front":"Share of rows retained","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>retained %</mtext><mo>=</mo><mfrac><msub><mi>n</mi><mtext>after</mtext></msub><msub><mi>n</mi><mtext>before</mtext></msub></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">\\text{retained \\%} = \\dfrac{n_{\\text{after}}}{n_{\\text{before}}} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mtext>before</mtext></msub></mrow><annotation encoding=\"application/x-tex\">n_{\\text{before}}</annotation></semantics></math></span>","Rows in the raw data (rows)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mtext>after</mtext></msub></mrow><annotation encoding=\"application/x-tex\">n_{\\text{after}}</annotation></semantics></math></span>","Rows in the cleaned data (rows)"]],"href":"learn/analytics/b02/data-quality-report/"},{"id":"f:b02:percentage-point-change","kind":"formula","course":"b02","lesson":"data-quality-report","front":"Change in percentage points and relative change","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi mathvariant=\"normal\">Δ</mi><mtext>pp</mtext></msub><mo>=</mo><msub><mi>p</mi><mn>2</mn></msub><mo>−</mo><msub><mi>p</mi><mn>1</mn></msub><mspace width=\"2em\"/><msub><mi mathvariant=\"normal\">Δ</mi><mi mathvariant=\"normal\">%</mi></msub><mo>=</mo><mfrac><mrow><msub><mi>p</mi><mn>2</mn></msub><mo>−</mo><msub><mi>p</mi><mn>1</mn></msub></mrow><msub><mi>p</mi><mn>1</mn></msub></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">\\Delta_{\\text{pp}} = p_2 - p_1 \\qquad \\Delta_{\\%} = \\dfrac{p_2 - p_1}{p_1} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>p</mi><mn>2</mn></msub></mrow><annotation encoding=\"application/x-tex\">p_1,\\ p_2</annotation></semantics></math></span>","A percentage before and after (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">Δ</mi><mtext>pp</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\Delta_{\\text{pp}}</annotation></semantics></math></span>","Change in percentage points (pp)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">Δ</mi><mi mathvariant=\"normal\">%</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\Delta_{\\%}</annotation></semantics></math></span>","Relative (percentage) change (%)"]],"href":"learn/analytics/b02/data-quality-report/"},{"id":"f:m02:customer-value","kind":"formula","course":"m02","lesson":"marketing-mix","front":"Customer value (a way of thinking)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>Customer value</mtext><mo>=</mo><mfrac><mtext>Perceived benefits</mtext><mtext>Perceived total cost</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{Customer value} = \\dfrac{\\text{Perceived benefits}}{\\text{Perceived total cost}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Perceived benefits</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Perceived benefits}</annotation></semantics></math></span>","The functional, emotional and social benefits of the offer, as the customer judges them"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Perceived total cost</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Perceived total cost}</annotation></semantics></math></span>","The price plus the time, effort and risk of buying and using the offer"]],"href":"learn/marketing/m02/marketing-mix/"},{"id":"f:m02:kept-per-unit","kind":"formula","course":"m02","lesson":"marketing-mix","front":"Gross margin per unit sold through a retailer","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>g</mi><mo>=</mo><mi>P</mi><mo>×</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><mi>m</mi><mo stretchy=\"false\">)</mo><mo>−</mo><mi>c</mi></mrow><annotation encoding=\"application/x-tex\">g = P \\times (1 - m) - c</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","Gross margin per unit: what the producer keeps after the trade’s share and the cost of the unit ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Shelf price paid by the shopper ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Share of the shelf price kept by the distributor and retailer together (decimal (0.32 = 32%))"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>c</mi></mrow><annotation encoding=\"application/x-tex\">c</annotation></semantics></math></span>","Cost of goods per unit (for Lantern: liquid, can, co-packing and freight to the distributor) ($ per unit)"]],"href":"learn/marketing/m02/marketing-mix/"},{"id":"f:m02:cogs-difference","kind":"formula","course":"m02","lesson":"product-decisions","front":"Extra cost of goods from a better tier","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>C</mi><mo>=</mo><mo stretchy=\"false\">(</mo><msub><mi>c</mi><mtext>high</mtext></msub><mo>−</mo><msub><mi>c</mi><mtext>low</mtext></msub><mo stretchy=\"false\">)</mo><mo>×</mo><mi>Q</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta C = (c_{\\text{high}} - c_{\\text{low}}) \\times Q</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta C</annotation></semantics></math></span>","Extra cost of goods for the volume sold ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>c</mi><mtext>high</mtext></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>c</mi><mtext>low</mtext></msub></mrow><annotation encoding=\"application/x-tex\">c_{\\text{high}},\\ c_{\\text{low}}</annotation></semantics></math></span>","Cost of goods per unit of the two tiers ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q</mi></mrow><annotation encoding=\"application/x-tex\">Q</annotation></semantics></math></span>","Units sold (units)"]],"href":"learn/marketing/m02/product-decisions/"},{"id":"f:m02:range-fixed-cost","kind":"formula","course":"m02","lesson":"product-decisions","front":"Extra fixed cost of a wider range","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>F</mi><mo>=</mo><mo stretchy=\"false\">(</mo><msub><mi>n</mi><mtext>wide</mtext></msub><mo>−</mo><msub><mi>n</mi><mtext>narrow</mtext></msub><mo stretchy=\"false\">)</mo><mo>×</mo><munder><mo>∑</mo><mi>k</mi></munder><msub><mi>L</mi><mi>k</mi></msub><mo>+</mo><msub><mi>F</mi><mtext>range</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\Delta F = (n_{\\text{wide}} - n_{\\text{narrow}}) \\times \\sum_{k} L_k + F_{\\text{range}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>F</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta F</annotation></semantics></math></span>","Extra fixed cost per year of the wider range ($ per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mtext>wide</mtext></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>n</mi><mtext>narrow</mtext></msub></mrow><annotation encoding=\"application/x-tex\">n_{\\text{wide}},\\ n_{\\text{narrow}}</annotation></semantics></math></span>","Number of SKUs (flavours) in each range (SKUs)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>L</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">L_k</annotation></semantics></math></span>","Listing fee per SKU per year in retail channel k ($ per SKU per year)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>F</mi><mtext>range</mtext></msub></mrow><annotation encoding=\"application/x-tex\">F_{\\text{range}}</annotation></semantics></math></span>","Other fixed costs of the wider range: production runs, labels, printing plates ($ per year)"]],"href":"learn/marketing/m02/product-decisions/"},{"id":"f:m02:payback-units","kind":"formula","course":"m02","lesson":"product-decisions","front":"Extra units needed to pay for a fixed cost","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>Q</mi><mtext>extra</mtext></msub><mo>=</mo><mfrac><mrow><mi mathvariant=\"normal\">Δ</mi><mi>F</mi></mrow><mi>g</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">Q_{\\text{extra}} = \\dfrac{\\Delta F}{g}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q</mi><mtext>extra</mtext></msub></mrow><annotation encoding=\"application/x-tex\">Q_{\\text{extra}}</annotation></semantics></math></span>","Extra units the decision must sell to cover its own fixed cost (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>F</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta F</annotation></semantics></math></span>","The extra fixed cost of the decision ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","Gross margin per unit: what the producer keeps after the trade’s share and the cost of goods ($ per unit)"]],"href":"learn/marketing/m02/product-decisions/"},{"id":"f:m02:yoy-growth","kind":"formula","course":"m02","lesson":"product-life-cycle","front":"Year-on-year growth","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>g</mi><mo>=</mo><mfrac><mrow><msub><mi>S</mi><mi>t</mi></msub><mo>−</mo><msub><mi>S</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msub></mrow><msub><mi>S</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msub></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">g = \\dfrac{S_t - S_{t-1}}{S_{t-1}} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","Growth rate over a year (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mi>t</mi></msub></mrow><annotation encoding=\"application/x-tex\">S_t</annotation></semantics></math></span>","Sales in the current year, or in a quarter (units or $)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mrow><mi>t</mi><mo>−</mo><mn>1</mn></mrow></msub></mrow><annotation encoding=\"application/x-tex\">S_{t-1}</annotation></semantics></math></span>","Sales in the year before, or in the same quarter a year earlier (units or $)"]],"href":"learn/marketing/m02/product-life-cycle/"},{"id":"f:m02:seasonal-adjustment","kind":"formula","course":"m02","lesson":"product-life-cycle","front":"Seasonally adjusted sales","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msubsup><mi>S</mi><mi>q</mi><mtext>adj</mtext></msubsup><mo>=</mo><mfrac><msub><mi>S</mi><mi>q</mi></msub><msub><mi>s</mi><mi>q</mi></msub></mfrac></mrow><annotation encoding=\"application/x-tex\">S^{\\text{adj}}_q = \\dfrac{S_q}{s_q}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>S</mi><mi>q</mi><mtext>adj</mtext></msubsup></mrow><annotation encoding=\"application/x-tex\">S^{\\text{adj}}_q</annotation></semantics></math></span>","Sales in quarter q, adjusted to an average quarter (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S</mi><mi>q</mi></msub></mrow><annotation encoding=\"application/x-tex\">S_q</annotation></semantics></math></span>","Actual sales in quarter q (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>s</mi><mi>q</mi></msub></mrow><annotation encoding=\"application/x-tex\">s_q</annotation></semantics></math></span>","Seasonal index for quarter q: its sales relative to an average quarter (Harbour City: 0.85, 1.05, 1.25, 0.85)"]],"href":"learn/marketing/m02/product-life-cycle/"},{"id":"f:m02:contribution-margin","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Contribution margin per unit","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>CM</mtext><mo>=</mo><mi>P</mi><mo>−</mo><mi>V</mi><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">\\text{CM} = P - VC</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Price the seller receives per unit, after any trade margin, commission or fulfilment cost deducted from it ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V</mi><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">VC</annotation></semantics></math></span>","Variable cost per unit ($ per unit)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:cm-ratio","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Contribution margin ratio","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>CM ratio</mtext><mo>=</mo><mfrac><mrow><mi>P</mi><mo>−</mo><mi>V</mi><mi>C</mi></mrow><mi>P</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{CM ratio} = \\dfrac{P - VC}{P}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>CM ratio</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{CM ratio}</annotation></semantics></math></span>","Share of each dollar of price left after variable costs (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Price the seller receives per unit ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V</mi><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">VC</annotation></semantics></math></span>","Variable cost per unit ($ per unit)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:markup","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Markup on cost and the cost-plus price","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>k</mi><mo>=</mo><mfrac><mrow><mi>P</mi><mo>−</mo><mi>C</mi></mrow><mi>C</mi></mfrac><mspace width=\"2em\"/><mi>P</mi><mo>=</mo><mi>C</mi><mtext> </mtext><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>k</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">k = \\dfrac{P - C}{C} \\qquad P = C\\,(1 + k)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","Markup: profit per unit as a share of the cost (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Unit cost the markup is applied to ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Selling price ($ per unit)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:margin","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Margin on price","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>m</mi><mo>=</mo><mfrac><mrow><mi>P</mi><mo>−</mo><mi>C</mi></mrow><mi>P</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">m = \\dfrac{P - C}{P}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Margin: profit per unit as a share of the price (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Selling price ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Unit cost ($ per unit)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:markup-margin","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Converting between markup and margin","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>m</mi><mo>=</mo><mfrac><mi>k</mi><mrow><mn>1</mn><mo>+</mo><mi>k</mi></mrow></mfrac><mspace width=\"2em\"/><mi>k</mi><mo>=</mo><mfrac><mi>m</mi><mrow><mn>1</mn><mo>−</mo><mi>m</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">m = \\dfrac{k}{1 + k} \\qquad k = \\dfrac{m}{1 - m}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span>","Markup on cost (decimal)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Margin on price (decimal)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:price-for-margin","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Price that gives a target margin","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>P</mi><mo>=</mo><mfrac><mi>C</mi><mrow><mn>1</mn><mo>−</mo><mi>m</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">P = \\dfrac{C}{1 - m}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">C</annotation></semantics></math></span>","Unit cost ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Target margin on price (decimal)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Price that gives the target margin ($ per unit)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:break-even-units","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Break-even volume","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>Q</mi><mtext>BE</mtext></msub><mo>=</mo><mfrac><mrow><mi>F</mi><mi>C</mi></mrow><mrow><mi>P</mi><mo>−</mo><mi>V</mi><mi>C</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">Q_{\\text{BE}} = \\dfrac{FC}{P - VC}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q</mi><mtext>BE</mtext></msub></mrow><annotation encoding=\"application/x-tex\">Q_{\\text{BE}}</annotation></semantics></math></span>","Units that must be sold in the period for total contribution to equal fixed costs (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">FC</annotation></semantics></math></span>","Fixed costs for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi><mo>−</mo><mi>V</mi><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">P - VC</annotation></semantics></math></span>","Contribution margin per unit ($ per unit)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:break-even-revenue","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Break-even revenue","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>R</mi><mtext>BE</mtext></msub><mo>=</mo><mfrac><mrow><mi>F</mi><mi>C</mi></mrow><mtext>CM ratio</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">R_{\\text{BE}} = \\dfrac{FC}{\\text{CM ratio}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R</mi><mtext>BE</mtext></msub></mrow><annotation encoding=\"application/x-tex\">R_{\\text{BE}}</annotation></semantics></math></span>","Sales value at which total contribution equals fixed costs ($)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:target-profit-volume","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Volume for a target profit","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>Q</mi><mtext>target</mtext></msub><mo>=</mo><mfrac><mrow><mi>F</mi><mi>C</mi><mo>+</mo><msup><mi>π</mi><mo lspace=\"0em\" rspace=\"0em\">∗</mo></msup></mrow><mrow><mi>P</mi><mo>−</mo><mi>V</mi><mi>C</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">Q_{\\text{target}} = \\dfrac{FC + \\pi^{*}}{P - VC}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q</mi><mtext>target</mtext></msub></mrow><annotation encoding=\"application/x-tex\">Q_{\\text{target}}</annotation></semantics></math></span>","Units that must be sold in the period to earn the target profit (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">FC</annotation></semantics></math></span>","Fixed costs for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>π</mi><mo lspace=\"0em\" rspace=\"0em\">∗</mo></msup></mrow><annotation encoding=\"application/x-tex\">\\pi^{*}</annotation></semantics></math></span>","Target profit for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Price the seller receives per unit ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V</mi><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">VC</annotation></semantics></math></span>","Variable cost per unit ($ per unit)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:target-return-price","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Target-return price","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>P</mi><mo>=</mo><mtext>unit cost</mtext><mo>+</mo><mfrac><mrow><mi>r</mi><mo>×</mo><mi>I</mi></mrow><mi>Q</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">P = \\text{unit cost} + \\dfrac{r \\times I}{Q}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Target-return price ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>unit cost</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{unit cost}</annotation></semantics></math></span>","Full cost per unit at the forecast volume: variable cost plus fixed costs ÷ Q ($ per unit)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Target rate of return on the capital invested, per period (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">I</annotation></semantics></math></span>","Capital invested ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q</mi></mrow><annotation encoding=\"application/x-tex\">Q</annotation></semantics></math></span>","Forecast unit sales for the period (units)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:economic-value","kind":"formula","course":"m02","lesson":"pricing-approaches","front":"Economic value to the customer","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>EV</mtext><mo>=</mo><mtext>reference value</mtext><mo>+</mo><mtext>differentiation value</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{EV} = \\text{reference value} + \\text{differentiation value}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>reference value</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{reference value}</annotation></semantics></math></span>","Price of the customer’s next-best alternative ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>differentiation value</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{differentiation value}</annotation></semantics></math></span>","Value to the customer of every difference from that alternative, positive or negative ($)"]],"href":"learn/marketing/m02/pricing-approaches/"},{"id":"f:m02:price-elasticity","kind":"formula","course":"m02","lesson":"price-response","front":"Price elasticity of demand","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>E</mi><mo>=</mo><mfrac><mrow><mi mathvariant=\"normal\">%</mi><mtext> </mtext><mi mathvariant=\"normal\">Δ</mi><mi>Q</mi></mrow><mrow><mi mathvariant=\"normal\">%</mi><mtext> </mtext><mi mathvariant=\"normal\">Δ</mi><mi>P</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">E = \\dfrac{\\%\\,\\Delta Q}{\\%\\,\\Delta P}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">%</mi><mtext> </mtext><mi mathvariant=\"normal\">Δ</mi><mi>Q</mi></mrow><annotation encoding=\"application/x-tex\">\\%\\,\\Delta Q</annotation></semantics></math></span>","Percentage change in quantity demanded (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">%</mi><mtext> </mtext><mi mathvariant=\"normal\">Δ</mi><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">\\%\\,\\Delta P</annotation></semantics></math></span>","Percentage change in price (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E</mi></mrow><annotation encoding=\"application/x-tex\">E</annotation></semantics></math></span>","Elasticity; usually negative. This course keeps the sign; many texts report the absolute value"]],"href":"learn/marketing/m02/price-response/"},{"id":"f:m02:point-elasticity","kind":"formula","course":"m02","lesson":"price-response","front":"Point elasticity (from a starting point)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>E</mi><mo>=</mo><mfrac><mrow><mo stretchy=\"false\">(</mo><msub><mi>Q</mi><mn>2</mn></msub><mo>−</mo><msub><mi>Q</mi><mn>1</mn></msub><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">/</mi><msub><mi>Q</mi><mn>1</mn></msub></mrow><mrow><mo stretchy=\"false\">(</mo><msub><mi>P</mi><mn>2</mn></msub><mo>−</mo><msub><mi>P</mi><mn>1</mn></msub><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">/</mi><msub><mi>P</mi><mn>1</mn></msub></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">E = \\dfrac{(Q_2 - Q_1)/Q_1}{(P_2 - P_1)/P_1}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E</mi></mrow><annotation encoding=\"application/x-tex\">E</annotation></semantics></math></span>","Price elasticity of demand; usually negative"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>Q</mi><mn>1</mn></msub></mrow><annotation encoding=\"application/x-tex\">P_1,\\ Q_1</annotation></semantics></math></span>","Starting price and quantity ($, units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P</mi><mn>2</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>Q</mi><mn>2</mn></msub></mrow><annotation encoding=\"application/x-tex\">P_2,\\ Q_2</annotation></semantics></math></span>","New price and quantity ($, units)"]],"href":"learn/marketing/m02/price-response/"},{"id":"f:m02:midpoint-elasticity","kind":"formula","course":"m02","lesson":"price-response","front":"Midpoint (arc) elasticity","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>E</mi><mo>=</mo><mfrac><mrow><mo stretchy=\"false\">(</mo><msub><mi>Q</mi><mn>2</mn></msub><mo>−</mo><msub><mi>Q</mi><mn>1</mn></msub><mo stretchy=\"false\">)</mo><mo fence=\"false\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">/</mo><mstyle displaystyle=\"false\" scriptlevel=\"0\"><mfrac><mn>1</mn><mn>2</mn></mfrac></mstyle><mo stretchy=\"false\">(</mo><msub><mi>Q</mi><mn>1</mn></msub><mo>+</mo><msub><mi>Q</mi><mn>2</mn></msub><mo stretchy=\"false\">)</mo></mrow><mrow><mo stretchy=\"false\">(</mo><msub><mi>P</mi><mn>2</mn></msub><mo>−</mo><msub><mi>P</mi><mn>1</mn></msub><mo stretchy=\"false\">)</mo><mo fence=\"false\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">/</mo><mstyle displaystyle=\"false\" scriptlevel=\"0\"><mfrac><mn>1</mn><mn>2</mn></mfrac></mstyle><mo stretchy=\"false\">(</mo><msub><mi>P</mi><mn>1</mn></msub><mo>+</mo><msub><mi>P</mi><mn>2</mn></msub><mo stretchy=\"false\">)</mo></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">E = \\dfrac{(Q_2 - Q_1) \\big/ \\tfrac{1}{2}(Q_1 + Q_2)}{(P_2 - P_1) \\big/ \\tfrac{1}{2}(P_1 + P_2)}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E</mi></mrow><annotation encoding=\"application/x-tex\">E</annotation></semantics></math></span>","Price elasticity of demand; usually negative"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>Q</mi><mn>1</mn></msub></mrow><annotation encoding=\"application/x-tex\">P_1,\\ Q_1</annotation></semantics></math></span>","First observed price and quantity ($, units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P</mi><mn>2</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>Q</mi><mn>2</mn></msub></mrow><annotation encoding=\"application/x-tex\">P_2,\\ Q_2</annotation></semantics></math></span>","Second observed price and quantity ($, units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>1</mn><mn>2</mn></mfrac><mo stretchy=\"false\">(</mo><msub><mi>Q</mi><mn>1</mn></msub><mo>+</mo><msub><mi>Q</mi><mn>2</mn></msub><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\tfrac{1}{2}(Q_1 + Q_2)</annotation></semantics></math></span>","Average of the two quantities (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>1</mn><mn>2</mn></mfrac><mo stretchy=\"false\">(</mo><msub><mi>P</mi><mn>1</mn></msub><mo>+</mo><msub><mi>P</mi><mn>2</mn></msub><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\tfrac{1}{2}(P_1 + P_2)</annotation></semantics></math></span>","Average of the two prices ($)"]],"href":"learn/marketing/m02/price-response/"},{"id":"f:m02:revenue-change","kind":"formula","course":"m02","lesson":"price-response","front":"Revenue after a price change","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mfrac><msub><mi>R</mi><mn>2</mn></msub><msub><mi>R</mi><mn>1</mn></msub></mfrac><mo>=</mo><mfrac><msub><mi>P</mi><mn>2</mn></msub><msub><mi>P</mi><mn>1</mn></msub></mfrac><mo>×</mo><mfrac><msub><mi>Q</mi><mn>2</mn></msub><msub><mi>Q</mi><mn>1</mn></msub></mfrac></mrow><annotation encoding=\"application/x-tex\">\\dfrac{R_2}{R_1} = \\dfrac{P_2}{P_1} \\times \\dfrac{Q_2}{Q_1}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi></mrow><annotation encoding=\"application/x-tex\">R</annotation></semantics></math></span>","Revenue, price × quantity ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>P</mi><mn>2</mn></msub></mrow><annotation encoding=\"application/x-tex\">P_1,\\ P_2</annotation></semantics></math></span>","Price before and after the change ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q</mi><mn>1</mn></msub><mo separator=\"true\">,</mo><mtext> </mtext><msub><mi>Q</mi><mn>2</mn></msub></mrow><annotation encoding=\"application/x-tex\">Q_1,\\ Q_2</annotation></semantics></math></span>","Quantity before and after the change (units)"]],"href":"learn/marketing/m02/price-response/"},{"id":"f:m02:required-volume","kind":"formula","course":"m02","lesson":"price-response","front":"Volume change that keeps contribution unchanged","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi mathvariant=\"normal\">%</mi><mtext> </mtext><mi mathvariant=\"normal\">Δ</mi><msub><mi>Q</mi><mtext>needed</mtext></msub><mo>=</mo><mfrac><mrow><mo>−</mo><mi mathvariant=\"normal\">Δ</mi><mi>P</mi></mrow><mrow><mi>C</mi><mi>M</mi><mo>+</mo><mi mathvariant=\"normal\">Δ</mi><mi>P</mi></mrow></mfrac></mrow><annotation encoding=\"application/x-tex\">\\%\\,\\Delta Q_{\\text{needed}} = \\dfrac{-\\Delta P}{CM + \\Delta P}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">%</mi><mtext> </mtext><mi mathvariant=\"normal\">Δ</mi><msub><mi>Q</mi><mtext>needed</mtext></msub></mrow><annotation encoding=\"application/x-tex\">\\%\\,\\Delta Q_{\\text{needed}}</annotation></semantics></math></span>","Percentage change in volume that keeps total contribution unchanged (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta P</annotation></semantics></math></span>","Change in the price the seller receives; negative for a cut ($ per unit or % of price)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi><mi>M</mi></mrow><annotation encoding=\"application/x-tex\">CM</annotation></semantics></math></span>","Contribution margin per unit at the current price (or the contribution margin ratio, if ΔP is a percentage) ($ per unit or % of price)"]],"href":"learn/marketing/m02/price-response/"},{"id":"f:m02:net-price-indirect","kind":"formula","course":"m02","lesson":"distribution-channels","front":"Net price through an indirect channel","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>N</mi><mo>=</mo><mi>P</mi><mo>×</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><mi>m</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">N = P \\times (1 - m)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Net price: what the producer receives per unit ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Shelf price paid by the final customer ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow><annotation encoding=\"application/x-tex\">m</annotation></semantics></math></span>","Trade margin: the share of the shelf price kept by all intermediaries together"]],"href":"learn/marketing/m02/distribution-channels/"},{"id":"f:m02:net-price-direct","kind":"formula","course":"m02","lesson":"distribution-channels","front":"Net price through a direct channel","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>N</mi><mo>=</mo><mi>P</mi><mo>−</mo><mi>f</mi></mrow><annotation encoding=\"application/x-tex\">N = P - f</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Net price: what the producer receives per unit ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi></mrow><annotation encoding=\"application/x-tex\">P</annotation></semantics></math></span>","Price paid by the final customer ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f</mi></mrow><annotation encoding=\"application/x-tex\">f</annotation></semantics></math></span>","Fulfilment cost per unit: storing, picking, packing and delivering ($)"]],"href":"learn/marketing/m02/distribution-channels/"},{"id":"f:m02:gross-margin-per-unit","kind":"formula","course":"m02","lesson":"distribution-channels","front":"Gross margin per unit","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>g</mi><mo>=</mo><mi>N</mi><mo>−</mo><mi>c</mi></mrow><annotation encoding=\"application/x-tex\">g = N - c</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","Gross margin per unit, before fixed fees, promotion and overhead ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Net price per unit: what the producer receives after the trade’s margin (and, selling direct, after fulfilment) ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>c</mi></mrow><annotation encoding=\"application/x-tex\">c</annotation></semantics></math></span>","Cost of goods per unit ($)"]],"href":"learn/marketing/m02/distribution-channels/"},{"id":"f:m02:compound-trade-margin","kind":"formula","course":"m02","lesson":"distribution-channels","front":"Combined margin of a multi-level channel","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>m</mi><mo>=</mo><mn>1</mn><mo>−</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><msub><mi>m</mi><mi>r</mi></msub><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><msub><mi>m</mi><mi>d</mi></msub><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">m = 1 - (1 - m_r)(1 - m_d)</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>m</mi><mi>r</mi></msub></mrow><annotation encoding=\"application/x-tex\">m_r</annotation></semantics></math></span>","Retailer’s margin, as a share of the shelf price"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>m</mi><mi>d</mi></msub></mrow><annotation encoding=\"application/x-tex\">m_d</annotation></semantics></math></span>","Distributor’s margin, as a share of the price it sells to the retailer at"]],"href":"learn/marketing/m02/distribution-channels/"},{"id":"f:m02:fee-payback-units","kind":"formula","course":"m02","lesson":"distribution-channels","front":"Units needed to cover a fixed channel cost","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>Q</mi><mo>=</mo><mfrac><mi>F</mi><mi>g</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">Q = \\dfrac{F}{g}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q</mi></mrow><annotation encoding=\"application/x-tex\">Q</annotation></semantics></math></span>","Units that must be sold in a year to cover the fee (round up) (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi></mrow><annotation encoding=\"application/x-tex\">F</annotation></semantics></math></span>","Fixed yearly cost of the channel: listing fees × SKUs, or the running cost of a direct channel ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g</mi></mrow><annotation encoding=\"application/x-tex\">g</annotation></semantics></math></span>","Gross margin per unit in the channel ($)"]],"href":"learn/marketing/m02/distribution-channels/"},{"id":"f:m02:pct-of-sales-budget","kind":"formula","course":"m02","lesson":"promotion-mix","front":"Percentage-of-sales budget","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>B</mi><mo>=</mo><mi>s</mi><mo>×</mo><mi>R</mi></mrow><annotation encoding=\"application/x-tex\">B = s \\times R</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B</mi></mrow><annotation encoding=\"application/x-tex\">B</annotation></semantics></math></span>","Promotion budget for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">s</annotation></semantics></math></span>","Chosen percentage of sales, as a decimal"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi></mrow><annotation encoding=\"application/x-tex\">R</annotation></semantics></math></span>","Sales revenue: last period’s actual or this period’s forecast ($)"]],"href":"learn/marketing/m02/promotion-mix/"},{"id":"f:m02:competitive-parity-budget","kind":"formula","course":"m02","lesson":"promotion-mix","front":"Competitive-parity budget (average of rivals)","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>B</mi><mo>=</mo><mfrac><mn>1</mn><mi>n</mi></mfrac><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><msub><mi>B</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">B = \\dfrac{1}{n}\\sum_{i=1}^{n} B_i</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B</mi><mi>i</mi></msub></mrow><annotation encoding=\"application/x-tex\">B_i</annotation></semantics></math></span>","Estimated promotion spending of rival i ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">n</annotation></semantics></math></span>","Number of rivals used as the benchmark"]],"href":"learn/marketing/m02/promotion-mix/"},{"id":"f:m02:objective-task-budget","kind":"formula","course":"m02","lesson":"promotion-mix","front":"Objective-and-task budget","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>B</mi><mo>=</mo><munder><mo>∑</mo><mi>k</mi></munder><msub><mi>q</mi><mi>k</mi></msub><mo>×</mo><msub><mi>c</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">B = \\sum_{k} q_k \\times c_k</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B</mi></mrow><annotation encoding=\"application/x-tex\">B</annotation></semantics></math></span>","Promotion budget for the period ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>q</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">q_k</annotation></semantics></math></span>","Quantity of task k needed to reach the objectives (demo days, thousands of impressions, events…) (units)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>c</mi><mi>k</mi></msub></mrow><annotation encoding=\"application/x-tex\">c_k</annotation></semantics></math></span>","Cost per unit of task k ($ per unit)"]],"href":"learn/marketing/m02/promotion-mix/"},{"id":"f:m02:avg-frequency","kind":"formula","course":"m02","lesson":"measuring-the-mix","front":"Average frequency","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mover accent=\"true\"><mi>f</mi><mo>ˉ</mo></mover><mo>=</mo><mfrac><mi>I</mi><mi>R</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\bar{f} = \\dfrac{I}{R}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>f</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{f}</annotation></semantics></math></span>","Average frequency: times each reached person was exposed"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">I</annotation></semantics></math></span>","Impressions delivered to the target audience (impressions)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi></mrow><annotation encoding=\"application/x-tex\">R</annotation></semantics></math></span>","Reach: different people exposed at least once (people)"]],"href":"learn/marketing/m02/measuring-the-mix/"},{"id":"f:m02:grp","kind":"formula","course":"m02","lesson":"measuring-the-mix","front":"Gross rating points","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>GRPs</mtext><mo>=</mo><mi>r</mi><mo>×</mo><mover accent=\"true\"><mi>f</mi><mo>ˉ</mo></mover><mo>=</mo><mfrac><mi>I</mi><mi>N</mi></mfrac><mo>×</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">\\text{GRPs} = r \\times \\bar{f} = \\dfrac{I}{N} \\times 100</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">r</annotation></semantics></math></span>","Reach as a percentage of the target audience (%)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover accent=\"true\"><mi>f</mi><mo>ˉ</mo></mover></mrow><annotation encoding=\"application/x-tex\">\\bar{f}</annotation></semantics></math></span>","Average frequency"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">I</annotation></semantics></math></span>","Impressions delivered to the target audience (impressions)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow><annotation encoding=\"application/x-tex\">N</annotation></semantics></math></span>","Size of the target audience (people)"]],"href":"learn/marketing/m02/measuring-the-mix/"},{"id":"f:m02:cpm","kind":"formula","course":"m02","lesson":"measuring-the-mix","front":"Cost per thousand impressions","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>CPM</mtext><mo>=</mo><mfrac><mtext>Spend</mtext><mi>I</mi></mfrac><mo>×</mo><mn>1,000</mn></mrow><annotation encoding=\"application/x-tex\">\\text{CPM} = \\dfrac{\\text{Spend}}{I} \\times 1{,}000</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Spend</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Spend}</annotation></semantics></math></span>","Cost of the media ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">I</annotation></semantics></math></span>","Impressions bought (impressions)"]],"href":"learn/marketing/m02/measuring-the-mix/"},{"id":"f:m02:ctr","kind":"formula","course":"m02","lesson":"measuring-the-mix","front":"Click-through rate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>CTR</mtext><mo>=</mo><mfrac><mtext>Clicks</mtext><mi>I</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{CTR} = \\dfrac{\\text{Clicks}}{I}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Clicks</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Clicks}</annotation></semantics></math></span>","Clicks on the ad (clicks)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">I</annotation></semantics></math></span>","Impressions of the ad (impressions)"]],"href":"learn/marketing/m02/measuring-the-mix/"},{"id":"f:m02:conversion-rate","kind":"formula","course":"m02","lesson":"measuring-the-mix","front":"Conversion rate","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>CR</mtext><mo>=</mo><mfrac><mtext>Conversions</mtext><mtext>Clicks</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{CR} = \\dfrac{\\text{Conversions}}{\\text{Clicks}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Conversions</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Conversions}</annotation></semantics></math></span>","Completed target actions, such as orders (conversions)"]],"href":"learn/marketing/m02/measuring-the-mix/"},{"id":"f:m02:cpa","kind":"formula","course":"m02","lesson":"measuring-the-mix","front":"Cost per acquisition","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>CPA</mtext><mo>=</mo><mfrac><mtext>Spend</mtext><mtext>Conversions</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{CPA} = \\dfrac{\\text{Spend}}{\\text{Conversions}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>CPA</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{CPA}</annotation></semantics></math></span>","Cost of each conversion ($)"]],"href":"learn/marketing/m02/measuring-the-mix/"},{"id":"f:m02:roas","kind":"formula","course":"m02","lesson":"measuring-the-mix","front":"Return on ad spend","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>ROAS</mtext><mo>=</mo><mfrac><mtext>Attributed revenue</mtext><mtext>Ad spend</mtext></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{ROAS} = \\dfrac{\\text{Attributed revenue}}{\\text{Ad spend}}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext>Attributed revenue</mtext></mrow><annotation encoding=\"application/x-tex\">\\text{Attributed revenue}</annotation></semantics></math></span>","Revenue credited to the campaign by the attribution rule in use ($)"]],"href":"learn/marketing/m02/measuring-the-mix/"},{"id":"f:m02:marketing-roi","kind":"formula","course":"m02","lesson":"measuring-the-mix","front":"Marketing ROI","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mtext>ROI</mtext><mo>=</mo><mfrac><mrow><mi mathvariant=\"normal\">Δ</mi><mi>C</mi><mo>−</mo><mi>M</mi></mrow><mi>M</mi></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{ROI} = \\dfrac{\\Delta C - M}{M}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>C</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta C</annotation></semantics></math></span>","Incremental contribution: extra revenue caused by the marketing minus its variable costs ($)"],["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>M</mi></mrow><annotation encoding=\"application/x-tex\">M</annotation></semantics></math></span>","Marketing cost ($)"]],"href":"learn/marketing/m02/measuring-the-mix/"},{"id":"f:m02:breakeven-roas","kind":"formula","course":"m02","lesson":"measuring-the-mix","front":"Break-even ROAS","back":"<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mtext>ROAS</mtext><mtext>BE</mtext></msub><mo>=</mo><mfrac><mn>1</mn><msub><mi>m</mi><mi>c</mi></msub></mfrac></mrow><annotation encoding=\"application/x-tex\">\\text{ROAS}_{\\text{BE}} = \\dfrac{1}{m_c}</annotation></semantics></math></span>","where":[["<span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>m</mi><mi>c</mi></msub></mrow><annotation encoding=\"application/x-tex\">m_c</annotation></semantics></math></span>","Contribution margin ratio on the revenue counted in ROAS"]],"href":"learn/marketing/m02/measuring-the-mix/"}];
